'use client'

import { useState } from "react"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Textarea } from "@/components/ui/textarea"
import { Plus, Loader2 } from "lucide-react"
import { addZone } from "../actions"

export function AddZoneForm({ ferryId }: { ferryId: string }) {
    const [loading, setLoading] = useState(false)

    async function handleSubmit(formData: FormData) {
        setLoading(true)
        const result = await addZone(ferryId, formData)
        setLoading(false)

        if (result?.error) {
            alert(`Error adding zone: ${result.error}`)
        } else {
            // success
            const form = document.querySelector('form#add-zone-form') as HTMLFormElement
            if (form) form.reset()
        }
    }

    return (
        <form id="add-zone-form" action={handleSubmit} className="grid gap-4">
            <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                    <label className="text-sm font-medium leading-none">Zone Name</label>
                    <Input name="name" placeholder="e.g. VIP Lounge" required />
                </div>
                <div className="space-y-2">
                    <label className="text-sm font-medium leading-none">Capacity</label>
                    <Input name="capacity" type="number" placeholder="40" required />
                </div>
            </div>
            <div className="space-y-2">
                <label className="text-sm font-medium leading-none">Description (Optional)</label>
                <Textarea name="description" placeholder="Description of zone amenities..." />
            </div>
            <Button type="submit" className="w-fit" disabled={loading}>
                {loading ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <Plus size={16} className="mr-2" />}
                Add Zone
            </Button>
        </form>
    )
}

'use client'

import { useState } from "react"
import { Button } from "@/components/ui/button"
import { Trash2, Loader2 } from "lucide-react"
import { deleteZone } from "../actions"

export function DeleteZoneButton({ zoneId, ferryId }: { zoneId: string, ferryId: string }) {
    const [loading, setLoading] = useState(false)

    async function handleDelete() {
        if (!confirm("Are you sure you want to delete this zone?")) return

        setLoading(true)
        const result = await deleteZone(zoneId, ferryId)
        setLoading(false)

        if (result?.error) {
            alert(`Error deleting zone: ${result.error}`)
        }
    }

    return (
        <Button
            variant="ghost"
            size="icon"
            className="text-red-500 hover:text-red-700 hover:bg-red-50"
            onClick={handleDelete}
            disabled={loading}
        >
            {loading ? <Loader2 size={16} className="animate-spin" /> : <Trash2 size={16} />}
        </Button>
    )
}

import { createClient } from "@/utils/supabase/server"
import { notFound } from "next/navigation"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Textarea } from "@/components/ui/textarea"
import { Trash2, Plus, Ship } from "lucide-react"
import Link from "next/link"
import { AddZoneForm } from "./add-zone-form"
import { DeleteZoneButton } from "./delete-zone-button"

export default async function FerryDetailPage({
    params
}: {
    params: { id: string }
}) {
    const { id } = await params
    const supabase = await createClient()

    const { data: ferry } = await supabase
        .from("clnt_ferries")
        .select(`*, zones:clnt_ferry_zones(*)`)
        .eq("id", id)
        .single()

    if (!ferry) notFound()

    return (
        <div className="space-y-6">
            <div className="flex items-center gap-4">
                <Link href="/admin/ferries" className="text-sm text-blue-600 hover:underline">&larr; Back to Fleet</Link>
            </div>

            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-bold tracking-tight flex items-center gap-3">
                        <Ship className="text-blue-500" />
                        {ferry.name}
                    </h1>
                    <p className="text-muted-foreground">Manage capacity and zones for this ship.</p>
                </div>
            </div>

            <div className="grid gap-6 md:grid-cols-3">
                <Card className="md:col-span-1">
                    <CardHeader>
                        <CardTitle>Ship Capacities</CardTitle>
                    </CardHeader>
                    <CardContent className="space-y-4">
                        <div>
                            <p className="text-xs font-medium text-muted-foreground uppercase">Passengers</p>
                            <p className="text-2xl font-bold">{ferry.capacity_passengers}</p>
                        </div>
                        <div>
                            <p className="text-xs font-medium text-muted-foreground uppercase">Bikes</p>
                            <p className="text-2xl font-bold">{ferry.capacity_bikes}</p>
                        </div>
                        <div>
                            <p className="text-xs font-medium text-muted-foreground uppercase">Pets</p>
                            <p className="text-2xl font-bold">{ferry.capacity_pets}</p>
                        </div>
                    </CardContent>
                </Card>

                <div className="md:col-span-2 space-y-6">
                    <Card>
                        <CardHeader>
                            <CardTitle>Ship Zones</CardTitle>
                        </CardHeader>
                        <CardContent>
                            <Table>
                                <TableHeader>
                                    <TableRow>
                                        <TableHead>Zone Name</TableHead>
                                        <TableHead>Capacity</TableHead>
                                        <TableHead>Description</TableHead>
                                        <TableHead className="text-right">Action</TableHead>
                                    </TableRow>
                                </TableHeader>
                                <TableBody>
                                    {ferry.zones?.length === 0 ? (
                                        <TableRow>
                                            <TableCell colSpan={4} className="text-center py-8 text-muted-foreground">
                                                No zones defined for this ship.
                                            </TableCell>
                                        </TableRow>
                                    ) : (
                                        ferry.zones?.map((zone: any) => (
                                            <TableRow key={zone.id}>
                                                <TableCell className="font-medium">{zone.name}</TableCell>
                                                <TableCell>{zone.capacity}</TableCell>
                                                <TableCell className="text-sm text-muted-foreground truncate max-w-[200px]">{zone.description || '-'}</TableCell>
                                                <TableCell className="text-right">
                                                    <DeleteZoneButton zoneId={zone.id} ferryId={ferry.id} />
                                                </TableCell>
                                            </TableRow>
                                        ))
                                    )}
                                </TableBody>
                            </Table>
                        </CardContent>
                    </Card>

                    <Card>
                        <CardHeader>
                            <CardTitle>Add New Zone</CardTitle>
                        </CardHeader>
                        <CardContent>
                            <AddZoneForm ferryId={ferry.id} />
                        </CardContent>
                    </Card>
                </div>
            </div>
        </div>
    )
}

'use server'

import { createClient } from "@/utils/supabase/server"
import { revalidatePath } from "next/cache"

export async function createFerry(formData: FormData) {
    const supabase = await createClient()

    const name = formData.get("name") as string
    const capacity_passengers = parseInt(formData.get("capacity_passengers") as string)
    const capacity_bikes = parseInt(formData.get("capacity_bikes") as string)
    const capacity_pets = parseInt(formData.get("capacity_pets") as string)

    try {
        const { error } = await supabase.from("clnt_ferries").insert({
            name,
            capacity_passengers,
            capacity_bikes,
            capacity_pets,
            is_active: true
        })

        if (error) throw new Error(error.message)

        revalidatePath("/admin/ferries")
        return { success: true }
    } catch (error: any) {
        return { success: false, error: error.message }
    }
}

export async function toggleFerryStatus(id: string, isActive: boolean) {
    const supabase = await createClient()
    try {
        const { error } = await supabase.from('clnt_ferries').update({ is_active: isActive }).eq('id', id)
        if (error) throw new Error(error.message)
        revalidatePath('/admin/ferries')
        return { success: true }
    } catch (error: any) {
        return { success: false, error: error.message }
    }
}

export async function deleteFerry(id: string) {
    const supabase = await createClient()
    try {
        // Check for associated trips
        const { count, error: countError } = await supabase
            .from('clnt_trips')
            .select('*', { count: 'exact', head: true })
            .eq('ferry_id', id)

        if (countError) throw new Error(countError.message)

        if (count && count > 0) {
            // Check if ANY of those trips have reservations?
            // Actually, for safety and data integrity, we should default to NOT deleting if trips exist.
            // The user asked "only if there are no reservations", but typically trips imply history.
            // Let's check reservations specifically if we want to be permissive for empty trips.

            // Get all trip IDs for this ferry
            const { data: trips } = await supabase.from('clnt_trips').select('id').eq('ferry_id', id)

            if (trips && trips.length > 0) {
                const tripIds = trips.map(t => t.id)
                // Check reservations
                const { count: resCount, error: resError } = await supabase
                    .from('clnt_reservations')
                    .select('*', { count: 'exact', head: true })
                    .in('trip_id', tripIds)

                if (resError) throw new Error(resError.message)

                if (resCount && resCount > 0) {
                    throw new Error("Cannot delete ship. It has scheduled trips with existing reservations. Please deactivate it instead.")
                }
            }
            // If strictly following "only if no reservations", we might allow deleting if no reservations found.
            // However, depending on FK constraints, deleting the ferry might cascade delete trips (BAD) or fail (GOOD).
            // Let's assume we proceed to try delete, and if DB fails due to FK, we catch it.
            // But if we want to be safe, we might warn even for empty trips.
            // For now, adhering to user request: blocked if RESERVATIONS exist.
        }

        const { error } = await supabase.from("clnt_ferries").delete().eq("id", id)
        if (error) {
            // Catch FK constraint violation if it happens (e.g. trips exist but no reservations)
            if (error.code === '23503') { // foreign_key_violation
                throw new Error("Cannot delete ship because it operates existing trips. Please delete the trips first or deactivate the ship.")
            }
            throw new Error(error.message)
        }
        revalidatePath("/admin/ferries")
        return { success: true }
    } catch (error: any) {
        return { success: false, error: error.message }
    }
}

export async function addZone(ferryId: string, formData: FormData) {
    const supabase = await createClient()
    const name = formData.get("name") as string
    const capacity = parseInt(formData.get("capacity") as string)
    const description = formData.get("description") as string

    try {
        // VALIDATION: Check if new capacity validation
        const { data: ferry } = await supabase.from("clnt_ferries").select(`capacity_passengers, zones:clnt_ferry_zones(capacity)`).eq("id", ferryId).single()

        if (!ferry) throw new Error("Ferry not found")

        const currentTotal = ferry.zones.reduce((sum: number, z: any) => sum + (z.capacity || 0), 0)

        if (currentTotal + capacity > ferry.capacity_passengers) {
            throw new Error(`Total zone capacity (${currentTotal + capacity}) exceeds ship passenger limit (${ferry.capacity_passengers})`)
        }

        const { error } = await supabase.from("clnt_ferry_zones").insert({
            ferry_id: ferryId,
            name,
            capacity,
            description
        })

        if (error) throw new Error(error.message)
        revalidatePath(`/admin/ferries/${ferryId}`)
        return { success: true }
    } catch (error: any) {
        return { success: false, error: error.message }
    }
}

export async function deleteZone(zoneId: string, ferryId: string) {
    const supabase = await createClient()
    try {
        const { error } = await supabase.from("clnt_ferry_zones").delete().eq("id", zoneId)
        if (error) throw new Error(error.message)
        revalidatePath(`/admin/ferries/${ferryId}`)
        return { success: true }
    } catch (error: any) {
        return { success: false, error: error.message }
    }
}

'use client'

