                        <Label htmlFor="pets" className="text-right">
                            Pet Capacity
                        </Label>
                        <Input
                            id="pets"
                            name="capacity_pets"
                            type="number"
                            defaultValue="10"
                            className="col-span-3"
                            required
                        />
                    </div>
                    <DialogFooter>
                        <Button type="submit">save changes</Button>
                    </DialogFooter>
                </form>
            </DialogContent>
        </Dialog>
    )
}

import { createClient } from "@/utils/supabase/server"
import { FerriesContent } from "@/components/admin/ferries/ferries-content"

export default async function FerriesPage() {
    const supabase = await createClient()
    const { data: ferries, error } = await supabase.from("clnt_ferries").select("*").order('created_at', { ascending: false })

    if (error) {
        return (
            <div className="p-4 text-red-500 bg-red-50 rounded-md border border-red-200">
                Error loading ferries. Please ensure database schema is applied. <br />
                <code className="text-xs">{error.message}</code>
            </div>
        )
    }

    return (
        <FerriesContent ferries={ferries || []} />
    )
}

