import { AdminDashboardContent } from "@/components/admin/admin-dashboard-content"
import { getAdminMenu } from "@/modules/admin-menu/actions"
import { createClient } from "@/utils/supabase/server"
import { createServiceClient } from "@/utils/supabase/service"
import { AdminPageHeader } from "@/components/admin/admin-page-header"
import { CustomizeButton } from "@/components/admin/customize-button"

interface PageProps {
    searchParams: Promise<{ [key: string]: string | string[] | undefined }>
}

export default async function ServicesPage({ searchParams }: PageProps) {
    const sp = await searchParams
    const isEditMode = sp.edit === 'true'
    const contextId = 'services-cockpit'

    const supabase = await createClient()
    const { data: { user } } = await supabase.auth.getUser()

    if (!user) {
        return <div className="p-8">Odmowa dostępu</div>
    }

    const serviceSupabase = createServiceClient()
    if (!serviceSupabase) {
        return <div className="p-8">Błąd konfiguracji serwisu</div>
    }

    const { data: profile } = await serviceSupabase
        .from('auth_profiles')
        .select('is_superadmin')
        .eq('id', user.id)
        .single()

    // Fetch menu with context
    const fullMenu = await getAdminMenu(isEditMode, contextId)

    // Filter for Services Cockpit sections
    // Keys: menu.sections.fleet, menu.sections.additional_services
    const servicesSections = fullMenu.filter(s =>
        s.name === 'menu.sections.fleet' ||
        s.name === 'menu.sections.additional_services'
    )

    return (
        <div className="space-y-12 animate-in fade-in duration-1000">
            <AdminPageHeader
                titleKey="admin.services.title"
            >
                <CustomizeButton />
            </AdminPageHeader>
            <AdminDashboardContent
                initialMenu={servicesSections}
                userId={user.id}
                isSuperAdmin={profile?.is_superadmin || false}
                contextId={contextId}
            />
        </div>
    )
}

