import { Suspense } from 'react';
import { verifyPageAccess } from '@/core/auth/actions';
import ServiceList from './ServiceList';
import { getServicesAction } from '@/modules/ferry-booking/services/actions';
import { Loader2 } from 'lucide-react';

export default async function ServicesPage({ params }: { params: { tenantSlug: string } }) {
    const { tenantId } = await verifyPageAccess(params.tenantSlug);

    const services = await getServicesAction(tenantId);

    return (
        <div className="p-6 max-w-6xl mx-auto">
            <h1 className="text-2xl font-bold mb-6">Services</h1>
            <Suspense fallback={<div className="flex justify-center p-12"><Loader2 className="animate-spin text-gray-400" /></div>}>
                <ServiceList tenantId={tenantId} services={services} />
            </Suspense>
        </div>
    );
}

'use client';

import React, { useState } from 'react';
import { Service } from '@/modules/ferry-booking/services/types';
import { upsertServiceAction, deleteServiceAction } from '@/modules/ferry-booking/services/actions';
import { Plus, Edit, Trash2, Loader2, X } from 'lucide-react';

interface ServiceListProps {
    tenantId: string;
    services: Service[];
}

export default function ServiceList({ tenantId, services }: ServiceListProps) {
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingService, setEditingService] = useState<Partial<Service>>({});
    const [loading, setLoading] = useState(false);

    const handleOpenModal = (service?: Service) => {
        setEditingService(service || { is_active: true });
        setIsModalOpen(true);
    };

    const handleCloseModal = () => {
        setIsModalOpen(false);
        setEditingService({});
    };

    const handleSave = async () => {
        setLoading(true);
        try {
            const res = await upsertServiceAction(tenantId, editingService);
            if (res.success) {
                handleCloseModal();
            } else {
                alert(res.error);
            }
        } finally {
            setLoading(false);
        }
    };

    const handleDelete = async (id: string) => {
        if (!confirm('Are you sure?')) return;
        await deleteServiceAction(tenantId, id);
    };

    return (
        <div>
            <div className="flex justify-end mb-4">
                <button
                    onClick={() => handleOpenModal()}
                    className="flex items-center gap-2 bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700"
                >
                    <Plus className="w-4 h-4" />
                    New Service
                </button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {services.map((service) => (
                    <div key={service.id} className="bg-white p-4 rounded-lg shadow border flex flex-col">
                        <div className="flex justify-between items-start mb-2">
                            <div className="flex items-center gap-2">
                                <div className="p-2 bg-gray-100 rounded">
                                    {/* Placeholder Icon */}
                                    <div className="w-5 h-5 bg-gray-300 rounded" />
                                </div>
                                <div>
                                    <h3 className="font-semibold text-gray-900">{service.name}</h3>
                                    <span className={`text-xs px-2 py-0.5 rounded-full ${service.is_active ? 'bg-green-100 text-green-800' : 'bg-gray-100 text-gray-800'}`}>
                                        {service.is_active ? 'Active' : 'Inactive'}
                                    </span>
                                </div>
                            </div>
                            <div className="flex gap-1">
                                <button onClick={() => handleOpenModal(service)} className="p-1 text-gray-400 hover:text-blue-600">
