'use server'

import { createClient } from "@/utils/supabase/server"
import { revalidatePath } from "next/cache"

import { fromWallTime } from "@/utils/date-config"
import { getTimezone } from "../settings/actions"

export async function createTrip(formData: FormData) {
    const supabase = await createClient()

    const route_id = formData.get("route_id") as string
    const ferry_id = formData.get("ferry_id") as string
    const seller_id = formData.get("seller_id") as string
    const departure_time_raw = formData.get("departure_time") as string // "YYYY-MM-DDTHH:MM"

    // Get configured timezone
    const timezone = await getTimezone()

    // Convert Wall Time (User Input) -> UTC ID
    // If input is "2026-02-04T13:00" and TZ is Warsaw, we want 12:00 UTC.
    const departure_date_utc = fromWallTime(departure_time_raw, timezone)

    const { data: route } = await supabase.from("clnt_routes").select("estimated_duration_minutes").eq("id", route_id).single()

    const arrival_date = new Date(departure_date_utc)
    if (route) {
        arrival_date.setMinutes(arrival_date.getMinutes() + route.estimated_duration_minutes)
    }

    const zone_config_raw = formData.get("zone_config") as string
    const zone_config = zone_config_raw ? JSON.parse(zone_config_raw) : {}

    const { data: trip, error } = await supabase.from("clnt_trips").insert({
        route_id,
        ferry_id,
        seller_id,
        departure_time: departure_date_utc.toISOString(),
        arrival_time: arrival_date.toISOString(),
        status: 'SCHEDULED',
        zone_config
    }).select().single()

    if (error) throw new Error(error.message)

    const services = ['ADULT', 'CHILD', 'BIKE', 'PET', 'VEHICLE']
    const pricingInserts = services.map(s => ({
        trip_id: trip.id,
        service_type: s,
        price: 0
    }))

    await supabase.from("clnt_trip_pricing").insert(pricingInserts)
    revalidatePath("/admin/trips")
}

export async function updateTrip(id: string, formData: FormData) {
    const supabase = await createClient()

    const route_id = formData.get("route_id") as string
    const ferry_id = formData.get("ferry_id") as string
    const seller_id = formData.get("seller_id") as string
    const departure_time = new Date(formData.get("departure_time") as string).toISOString()
    const zone_config_raw = formData.get("zone_config") as string
    const zone_config = zone_config_raw ? JSON.parse(zone_config_raw) : {}

    const { data: route } = await supabase.from("clnt_routes").select("estimated_duration_minutes").eq("id", route_id).single()

    const arrival_date = new Date(departure_time)
    if (route) {
        arrival_date.setMinutes(arrival_date.getMinutes() + route.estimated_duration_minutes)
    }

    const { error } = await supabase.from("clnt_trips").update({
        route_id,
        ferry_id,
        seller_id,
        departure_time,
        arrival_time: arrival_date.toISOString(),
        zone_config
    }).eq("id", id)

    if (error) throw new Error(error.message)
    revalidatePath("/admin/trips")
}

export async function deleteTrip(id: string) {
    const supabase = await createClient()
    try {
        const { error } = await supabase.from("clnt_trips").delete().eq("id", id)
        if (error) {
            // Check for foreign key constraint violation
            if (error.code === '23503') { // Postgres foreign_key_violation
                throw new Error("Cannot delete trip because it has existing reservations. Please cancel/delete reservations first.")
            }
            throw new Error(error.message)
        }
        revalidatePath("/admin/trips")
        return { success: true }
    } catch (error: any) {
        return { success: false, error: error.message }
    }
}

export async function updateTripPrice(tripId: string, serviceType: string, price: number) {
    const supabase = await createClient()
    const { error } = await supabase.from("clnt_trip_pricing").upsert({
        trip_id: tripId,
        service_type: serviceType,
        price: price
    }, { onConflict: 'trip_id, service_type, zone_id' })

    if (error) throw new Error(error.message)
    revalidatePath("/admin/trips")
}

export async function exportSchedule() {
    const supabase = await createClient()

    const { data: trips, error } = await supabase
        .from("clnt_trips")
        .select(`
            *,
            route:clnt_routes(
                id, 
                origin:clnt_locations!origin_id(name), 
                destination:clnt_locations!destination_id(name)
            ),
            ferry:clnt_ferries(id, name),
            pricing:clnt_trip_pricing(*)
        `)
        .order("departure_time", { ascending: true })

    if (error) throw new Error(error.message)

    const headers = "origin,destination,ferry,departure_time,arrival_time,price_adult,price_child,price_bike\n"
    const rows = (trips || []).map(trip => {
        const adultPrice = trip.pricing?.find((p: any) => p.service_type === 'ADULT')?.price || 0
        const childPrice = trip.pricing?.find((p: any) => p.service_type === 'CHILD')?.price || 0
        const bikePrice = trip.pricing?.find((p: any) => p.service_type === 'BIKE')?.price || 0

        return `${trip.route?.origin?.name || ''},${trip.route?.destination?.name || ''},${trip.ferry?.name || ''},${trip.departure_time},${trip.arrival_time},${adultPrice},${childPrice},${bikePrice}`
    }).join("\n")

    return headers + rows
}

export async function importSchedule(formData: FormData) {
    const supabase = await createClient()
    const file = formData.get("file") as File

    if (!file) throw new Error("No file provided")

    const text = await file.text()
    const lines = text.split("\n").filter(line => line.trim())
    const dataLines = lines.slice(1)

    // Pre-fetch all lookups to avoid N+1 in lookup
    const { data: locations } = await supabase.from("clnt_locations").select("*")
    const { data: ferries } = await supabase.from("clnt_ferries").select("*")
    const { data: routes } = await supabase.from("clnt_routes").select("*")

    for (const line of dataLines) {
        const [origin_name, dest_name, ferry_name, departure_time, arrival_time, price_adult, price_child, price_bike] = line.split(",").map(v => v.trim().replace(/^"|"$/g, ''))

        // Resolve Ferry
        const ferry = ferries?.find(f => f.name.toLowerCase() === ferry_name.toLowerCase())
        if (!ferry) continue

        // Resolve Origin/Dest IDs
        const origin = locations?.find(l => l.name.toLowerCase() === origin_name.toLowerCase())
        const dest = locations?.find(l => l.name.toLowerCase() === dest_name.toLowerCase())
        if (!origin || !dest) continue

        // Resolve Route
        let route = routes?.find(r => r.origin_id === origin.id && r.destination_id === dest.id)

        // If route doesn't exist, maybe we should create it or skip
        if (!route) {
            // Auto-create route if it doesn't exist?
            const { data: newRoute, error: routeError } = await supabase.from("clnt_routes").insert({
                origin_id: origin.id,
                destination_id: dest.id,
                estimated_duration_minutes: 60 // Default
            }).select().single()
            if (routeError) continue
            route = newRoute
        }

        const { data: trip, error: tripError } = await supabase
            .from("clnt_trips")
            .insert({
                route_id: route.id,
                ferry_id: ferry.id,
                departure_time,
                arrival_time,
                status: 'SCHEDULED'
            })
            .select()
            .single()

        if (tripError) continue

        await supabase.from("clnt_trip_pricing").insert([
            { trip_id: trip.id, service_type: 'ADULT', price: parseFloat(price_adult) || 0 },
            { trip_id: trip.id, service_type: 'CHILD', price: parseFloat(price_child) || 0 },
            { trip_id: trip.id, service_type: 'BIKE', price: parseFloat(price_bike) || 0 },
            { trip_id: trip.id, service_type: 'PET', price: 0 },
            { trip_id: trip.id, service_type: 'VEHICLE', price: 0 }
        ])
    }

    revalidatePath("/admin/trips")
}

export async function toggleTripVisibility(id: string, isPublic: boolean) {
    const supabase = await createClient()
    const { error } = await supabase.from("clnt_trips").update({
        is_public: isPublic
    }).eq("id", id)

    if (error) throw new Error(error.message)
    revalidatePath("/admin/trips")
}

export async function toggleOperationalStatus(ferryId: string, date: string, isOperational: boolean) {
    const supabase = await createClient()
    const { error } = await supabase.from("clnt_ferry_status").upsert({
        ferry_id: ferryId,
        date: date,
        is_operational: isOperational
    }, { onConflict: 'ferry_id, date' })

    if (error) throw new Error(error.message)
    revalidatePath("/admin/trips")
}

export async function regenerateSchedule(year: number, month: number) {
    const supabase = await createClient()

    // Calculate start and end of the target month
    // month is 1-indexed (1=Jan, 12=Dec)
    const startDate = new Date(year, month - 1, 1) // Start of month, 00:00:00 local approx, need UTC care

    // Better to work with simple strings or UTC to avoid timezone shifts on server
    // For simplicity, let's treat input as local calendar intent. 
    // We will generate ISO strings assuming local time noon or start of day.

    // Let's use date-fns helpers or simple iteration if imports available?
    // We don't have date-fns imported here yet, let's stick to native Date carefully.

    const nextMonth = new Date(startDate)
    nextMonth.setMonth(nextMonth.getMonth() + 1)
    const endDate = new Date(nextMonth.getTime() - 1) // Last millisecond of the month

    const startStr = startDate.toISOString()
    const endStr = endDate.toISOString()

    // 1. Delete *future* trips in that month
    // We don't want to delete past trips even if in the same month (history preservation)
    const now = new Date()
    // Safety buffer: only delete things 1 hour from now or later? Or just now.
    const deleteStart = now > startDate ? now.toISOString() : startStr

    // Only proceed if the month covers future dates
    if (new Date(endStr) > now) {
        const { error: deleteError } = await supabase
            .from("clnt_trips")
            .delete()
            .gte("departure_time", deleteStart)
            .lte("departure_time", endStr)

        if (deleteError) throw new Error(`Failed to clear old schedule: ${deleteError.message}`)
    }

    // 2. Fetch Templates
    const { data: templates } = await supabase.from("clnt_schedule_templates").select(`
        *,
        ferry:clnt_ferries(*),
        route:clnt_routes(estimated_duration_minutes)
    `)
    if (!templates || templates.length === 0) return // No templates, nothing to do.

    // 3. Generate new trips
    const tripsToInsert: any[] = []

    // Get configured timezone
    const timezone = await getTimezone()

    // Iterate through every day of the month
    const iterDate = new Date(startDate)

    // Prevent infinite loop if something is wrong with caching/date math
    let safetyCounter = 0
    while (iterDate.getMonth() === month - 1 && safetyCounter < 32) {
        safetyCounter++

        const dayOfWeek = iterDate.getDay() // 0=Sun, 1=Mon...
        const isoDay = dayOfWeek === 0 ? 7 : dayOfWeek

        for (const template of templates) {
            // Check if template runs on this day
            if (template.days_of_week && template.days_of_week.includes(isoDay)) {

                // Construct specific departure time for this day
                // Template time is HH:MM in "Wall Time" (e.g. 13:00)
                const [hours, minutes] = template.departure_time.split(':')

                // Construct a date string like "2026-02-04T13:00:00"
                const yearStr = iterDate.getFullYear()
                const monthStr = (iterDate.getMonth() + 1).toString().padStart(2, '0')
                const dayStr = iterDate.getDate().toString().padStart(2, '0')
                const timeStr = `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:00`

                const wallTimeStr = `${yearStr}-${monthStr}-${dayStr}T${timeStr}`

                // Convert using our TZ helper
                const departureDateTimeUtc = fromWallTime(wallTimeStr, timezone)
                const departureIso = departureDateTimeUtc.toISOString()

                // Skip if in the past/before safe delete window
                if (departureIso <= deleteStart) continue

                // Calculate Arrival
                const arrivalDateTime = new Date(departureDateTimeUtc)
                arrivalDateTime.setMinutes(arrivalDateTime.getMinutes() + (template.route.estimated_duration_minutes || 60))

                tripsToInsert.push({
                    route_id: template.route_id,
                    ferry_id: template.ferry_id,
                    seller_id: template.seller_id,
                    departure_time: departureIso,
                    arrival_time: arrivalDateTime.toISOString(),
                    status: 'SCHEDULED',
                    zone_config: template.zone_config,
                })
            }
        }
        iterDate.setDate(iterDate.getDate() + 1)
    }

    // Batch insert trips
    if (tripsToInsert.length > 0) {
        // Insert trips and select them back to get IDs
        const { data: insertedTrips, error: insertError } = await supabase
            .from("clnt_trips")
            .insert(tripsToInsert)
            .select()

        if (insertError) throw new Error(`Failed to insert trips: ${insertError.message}`)

        if (insertedTrips && insertedTrips.length > 0) {
            const pricingInserts: any[] = []

            // For each inserted trip, find its matching template to get pricing
            // This is O(N*M) but N(trips)~150, M(templates)~10 -> Fast enough.
            for (const trip of insertedTrips) {
                // Find template that matches route, ferry, and time logic? 
                // Or departure time components match?
                // We lost direct link. 
                // Heuristic: Match route_id, ferry_id, and check if template runs on this day of week.
                // This is slightly ambiguous if multiple templates match same slot (unlikely).

                const tripDate = new Date(trip.departure_time)
                const dayOfWeek = tripDate.getDay() || 7
                const timeStr = `${tripDate.getHours().toString().padStart(2, '0')}:${tripDate.getMinutes().toString().padStart(2, '0')}` // HH:MM (UTC?) - careful.

                // Be careful with time matching due to ISO/Timezone conversions.
                // Simpler approach: We just assume we should copy pricing from ANY template
                // that matches route + ferry + seller + days_of_week.
                // Ideally, templates should decrease in ambiguity.

                // Let's try to match purely on route/ferry for now, assuming pricing is uniform for that route/ferry?
                // No, different slots might have different prices.

                // Better: query `schedule_templates` again? No we have them.
                // Filter templates first by route/ferry/seller
                const candidates = templates.filter(t =>
                    t.route_id === trip.route_id &&
                    t.ferry_id === trip.ferry_id &&
                    t.seller_id === trip.seller_id &&
                    t.days_of_week.includes(dayOfWeek)
                )

                // If multiple, try to match time?
                // If template.departure_time (HH:MM string) roughly matches trip time?
                // Depending on TZ, this is hard.
                // Let's assume just taking the first candidate's pricing is "good enough" for MVP.
                const sourceTemplate = candidates[0]

                if (sourceTemplate && sourceTemplate.pricing) {
                    // pricing jsonb in template: [{service_type: 'ADULT', price: 10}, ...]
                    const tPrices = sourceTemplate.pricing as any[]
                    if (Array.isArray(tPrices)) {
                        for (const p of tPrices) {
                            pricingInserts.push({
                                trip_id: trip.id,
                                service_type: p.service_type,
                                price: p.price,
                                currency: p.currency || 'PLN'
                            })
                        }
                    }
                } else {
                    // Fallback default pricing if no template pricing found
                    ['ADULT', 'CHILD', 'BIKE', 'PET', 'VEHICLE'].forEach(st => {
                        pricingInserts.push({
                            trip_id: trip.id,
                            service_type: st,
                            price: 0
                        })
                    })
                }
            }

            if (pricingInserts.length > 0) {
                await supabase.from("clnt_trip_pricing").insert(pricingInserts)
            }
        }
    }


    revalidatePath("/admin/trips")
}

export async function getTripsForMonth(start: Date, end: Date) {
    const supabase = await createClient()
    const { data: trips, error } = await supabase
        .from("clnt_trips")
        .select(`
            *,
            route:clnt_routes(origin:clnt_locations!origin_id(name), destination:clnt_locations!destination_id(name)),
            ferry:clnt_ferries(name)
        `)
        .gte('departure_time', start.toISOString())
        .lte('departure_time', end.toISOString())
        .order('departure_time', { ascending: true })

    if (error) {
        console.error('Error fetching trips:', error)
        return []
    }

    return trips
}

'use client'

import { Button } from "@/components/ui/button"
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
} from "@/components/ui/dialog"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { Label } from "@/components/ui/label"
import { Input } from "@/components/ui/input"
import { useState } from "react"
import { Calendar as CalendarIcon, Loader2 } from "lucide-react"
import { applyTemplate } from "../templates/actions"
import { useTranslation } from "react-i18next"
import { Checkbox } from "@/components/ui/checkbox"

export function ApplyTemplateDialog({
    templates,
    ferries
}: {
    templates: any[],
    ferries: any[]
}) {
    const { t } = useTranslation()
    const [open, setOpen] = useState(false)
    const [loading, setLoading] = useState(false)
    const [report, setReport] = useState<{ success: boolean, error?: string } | null>(null)

    async function handleSubmit(formData: FormData) {
        setLoading(true)
        setReport(null)

        try {
            const templateId = formData.get("template_id") as string
            const ferryId = formData.get("ferry_id") as string
            const startDate = formData.get("start_date") as string
            const endDate = formData.get("end_date") as string
            const overwrite = formData.get("overwrite") === "on"

            if (!startDate || !endDate) throw new Error("Dates required")

            // Generate array of dates
            const start = new Date(startDate)
            const end = new Date(endDate)
            const dates = []
            for (let d = start; d <= end; d.setDate(d.getDate() + 1)) {
                dates.push(new Date(d))
            }

            const result = await applyTemplate(templateId, ferryId, dates, overwrite)
            if (result.success) {
                setOpen(false)
            } else {
                setReport({ success: false, error: result.error })
            }
        } catch (e: any) {
            setReport({ success: false, error: e.message })
        } finally {
            setLoading(false)
        }
    }

    return (
        <Dialog open={open} onOpenChange={setOpen}>
            <DialogTrigger asChild>
                <Button variant="outline" className="gap-2">
                    <CalendarIcon size={16} />
                    {t('admin.trips.applyTemplate')}
                </Button>
            </DialogTrigger>
            <DialogContent className="sm:max-w-[425px]">
                <DialogHeader>
                    <DialogTitle>Apply Schedule Template</DialogTitle>
                    <DialogDescription>
                        Generate trips for a date range.
                    </DialogDescription>
                </DialogHeader>
                <form action={handleSubmit} className="grid gap-4 py-4">
                    <div className="grid gap-2">
                        <Label>Select Template</Label>
                        <Select name="template_id" required>
                            <SelectTrigger>
                                <SelectValue placeholder="Choose template..." />
                            </SelectTrigger>
                            <SelectContent>
                                {templates.map(t => (
                                    <SelectItem key={t.id} value={t.id}>{t.name}</SelectItem>
                                ))}
                            </SelectContent>
                        </Select>
                    </div>

                    <div className="grid gap-2">
                        <Label>Assign to Ferry</Label>
                        <Select name="ferry_id" required>
                            <SelectTrigger>
                                <SelectValue placeholder="Choose ferry..." />
                            </SelectTrigger>
                            <SelectContent>
                                {ferries.map(f => (
                                    <SelectItem key={f.id} value={f.id}>{f.name}</SelectItem>
                                ))}
                            </SelectContent>
                        </Select>
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <div className="grid gap-2">
                            <Label>Start Date</Label>
                            <Input type="date" name="start_date" required />
                        </div>
                        <div className="grid gap-2">
                            <Label>End Date</Label>
                            <Input type="date" name="end_date" required />
                        </div>
                    </div>

                    <div className="flex items-center space-x-2">
                        <Checkbox id="overwrite" name="overwrite" />
                        <label
                            htmlFor="overwrite"
                            className="text-sm font-medium leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70"
                        >
                            Overwrite existing trips (if no reservations)
                        </label>
                    </div>

                    {report && !report.success && (
                        <div className="text-red-600 text-sm bg-red-50 p-2 rounded">
                            Error: {report.error}
                        </div>
                    )}

                    <DialogFooter>
                        <Button type="submit" disabled={loading}>
                            {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                            Generate Trips
                        </Button>
                    </DialogFooter>
                </form>
            </DialogContent>
        </Dialog>
    )
}

