import { createClient } from "@/utils/supabase/server"
import { getHeatmapConfig } from "@/app/admin/settings/actions"

export async function getTripsData(searchParams: { ferryId?: string, routeId?: string, date?: string }) {
    const supabase = await createClient()

    // Fetch dependencies
    const { data: routes } = await supabase
        .from("clnt_routes")
        .select(`*, origin:clnt_locations!origin_id(name), destination:clnt_locations!destination_id(name)`)
    const { data: ferries } = await supabase.from("clnt_ferries").select("*, zones:clnt_ferry_zones(*)")
    const { data: partners } = await supabase.from("business_partners").select("*").in("type", ['SELLER', 'BOTH'])
    const { data: operationalStatuses } = await supabase.from("clnt_ferry_status").select("*")
    const { data: templates } = await supabase.from("clnt_schedule_templates").select("*")
    const heatmapConfig = await getHeatmapConfig()

    // Fetch trips with relations and filters
    let query = supabase
        .from("clnt_trips")
        .select(`
            *,
            route:clnt_routes(id, estimated_duration_minutes, origin:clnt_locations!origin_id(name), destination:clnt_locations!destination_id(name)),
            ferry:clnt_ferries(name, capacity_passengers),
            seller:business_partners(name),
            pricing:clnt_trip_pricing(*)
        `)
        .order("departure_time", { ascending: true })

    if (searchParams.ferryId && searchParams.ferryId !== 'all') {
        query = query.eq('ferry_id', searchParams.ferryId)
    }
    if (searchParams.routeId && searchParams.routeId !== 'all') {
        query = query.eq('route_id', searchParams.routeId)
    }
    if (searchParams.date) {
        query = query
            .gte('departure_time', `${searchParams.date}T00:00:00`)
            .lt('departure_time', `${searchParams.date}T23:59:59`)
    }

    const { data: rawTrips } = await query

    // Calculate booked counts manually for now
    const tripIds = rawTrips?.map(t => t.id) || []
    const { data: reservations } = await supabase
        .from("clnt_reservations")
        .select("trip_id, count_passengers")
        .in("trip_id", tripIds)
        .neq("status", "CANCELLED")

    const trips = rawTrips?.map(trip => {
        const tripRes = reservations?.filter(r => r.trip_id === trip.id) || []
        const bookedCount = tripRes.reduce((sum, r) => sum + (r.count_passengers || 0), 0)
        return {
            ...trip,
            booked_count: bookedCount,
            is_full: bookedCount >= (trip.ferry?.capacity_passengers || 0)
        }
    })

    return {
        trips: trips || [],
        routes: routes || [],
        ferries: ferries || [],
        partners: partners || [],
        operationalStatuses: operationalStatuses || [],
        templates: templates || [],
        heatmapConfig
    }
}

