    if (!tenant) {
        notFound();
    }

    // 3. Resolve Contexts
    const [tenantContext, userContext] = await Promise.all([
        getTenantContext(tenant.id, tenant.slug),
        getUserContext(user.id, tenant.id)
    ]);

    if (!tenantContext || !userContext) {
        forbidden();
    }

    // 4. Module Access Check & Permission Check
    const moduleDef = moduleRegistry.getModule('ferry-booking/trips');
    if (!moduleDef || !canAccessModule(moduleDef, userContext!)) {
        forbidden();
    }

    const hasPermission = userContext!.permissions.includes('trips.create') || userContext!.permissions.includes('*');
    if (!hasPermission) {
        forbidden();
    }

    // 5. Data Fetch
    const routeRepo = new SupabaseFerryRouteRepository();
    const service = new FerryBookingService(routeRepo);

    const routes = await service.getRoutes(tenant.id);
