export default async function TripDetailsPage({ params }: { params: Promise<{ tenantSlug: string; id: string }> }) {
    // 1. Auth Check
    const supabase = createAuthClient();
    const { data: { user } } = await supabase.auth.getUser();

    if (!user) {
        redirect('/login');
    }

    // 2. Tenant Resolution
    const tenantRepo = new SupabaseTenantRepository();
    const { tenantSlug, id } = await params;
    const tenant = await tenantRepo.resolveTenantForUser(user.id, tenantSlug);

    if (!tenant) {
        notFound();
    }

    // 3. Resolve Contexts
    const [tenantContext, userContext] = await Promise.all([
        getTenantContext(tenant.id, tenant.slug),
        getUserContext(user.id, tenant.id)
    ]);

    if (!tenantContext || !userContext) {
        forbidden();
    }

    // 4. Module Access Check
    const moduleDef = moduleRegistry.getModule('ferry-booking/trips');
    if (!moduleDef || !canAccessModule(moduleDef, userContext!)) {
        forbidden();
    }

    const hasPermission = userContext!.permissions.includes('trips.view') || userContext!.permissions.includes('*');
    if (!hasPermission) {
        forbidden();
    }

    // 5. Data Fetch
    const tripRepo = new SupabaseTripRepository();
    const orderRepo = new SupabaseOrderRepository();
    const resRepo = new SupabaseReservationRepository();
    // Use SalesService for consistency, though Repo direct access is also fine in admin if needed.
    const service = new FerrySalesService(tripRepo, orderRepo, resRepo);

    const trip = await service.getTripById(tenant.id, id);

    if (!trip) {
        notFound();
    }

    // Check edit permission for the form
    const canEdit = userContext!.permissions.includes('trips.edit') || userContext!.permissions.includes('*');

    // 6. Render
