}

'use client';

import { useTransition } from 'react';
import { updateTripAction } from '../actions';
import { FerryTrip } from '@/modules/ferry-booking/domain/types';

interface EditTripFormProps {
    tenantSlug: string;
    trip: FerryTrip;
}

export function EditTripForm({ tenantSlug, trip }: EditTripFormProps) {
    const [isPending, startTransition] = useTransition();

    const handleSubmit = async (formData: FormData) => {
        await updateTripAction(tenantSlug, trip.id, null, formData);
    };

    // Format for datetime-local: YYYY-MM-DDTHH:mm
    const formatDateTime = (dateStr: string) => {
        if (!dateStr) return '';
        const d = new Date(dateStr);
        // Helper to ensure local time representation for input
        // Note: Database stores UTC. This simplistic conversion might depend on browser time zone.
        // For strictness, we should handle TZ carefully, but for MVP local simplified.
        // Using toISOString().slice(0, 16) gives UTC time if we don't offset.
        // Let's use simplified approach:
        const pad = (n: number) => n < 10 ? '0' + n : n;
        return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
    };

    return (
        <form action={handleSubmit} className="space-y-6 max-w-lg bg-card p-6 rounded shadow border">
            <div>
                <label className="block text-sm font-medium mb-1">Route</label>
                <div className="p-2 border rounded bg-muted text-muted-foreground">
                    {trip.route?.origin?.name} → {trip.route?.destination?.name}
                </div>
                <p className="text-xs text-muted-foreground mt-1">Route cannot be changed.</p>
            </div>

            <div>
                <label className="block text-sm font-medium mb-1">Ferry</label>
                <div className="p-2 border rounded bg-muted text-muted-foreground">
                    {trip.ferry?.name || 'Unknown'}
                </div>
                <p className="text-xs text-muted-foreground mt-1">Ferry assignment cannot be changed.</p>
            </div>

            <div className="grid grid-cols-2 gap-4">
                <div>
                    <label className="block text-sm font-medium mb-1">Departure Time</label>
                    <input
                        type="datetime-local"
                        name="departureTime"
                        defaultValue={formatDateTime(trip.departureTime)}
                        required
                        className="w-full border rounded p-2 bg-background"
                    />
                </div>
                <div>
                    <label className="block text-sm font-medium mb-1">Arrival Time</label>
                    <input
                        type="datetime-local"
                        name="arrivalTime"
                        defaultValue={formatDateTime(trip.arrivalTime)}
                        required
                        className="w-full border rounded p-2 bg-background"
                    />
                </div>
            </div>

            <div className="flex items-center gap-2">
                <input type="checkbox" name="isPublic" id="isPublic" defaultChecked={trip.isPublic} />
                <label htmlFor="isPublic" className="text-sm font-medium">Publicly Visible</label>
            </div>

            <div className="pt-4 flex justify-end gap-2">
                <button type="submit" disabled={isPending} className="bg-primary text-primary-foreground px-4 py-2 rounded hover:bg-primary/90 disabled:opacity-50">
                    {isPending ? 'Saving...' : 'Save Changes'}
                </button>
            </div>
        </form>
    );
}


import { createAuthClient } from '@/infra/supabase/server-auth';
