import { SupabaseReservationRepository } from '@/modules/ferry-booking/infrastructure/SupabaseReservationRepository';
import { FerrySalesService } from '@/modules/ferry-booking/application/FerrySalesService';
import { notFound, redirect, forbidden } from 'next/navigation';
import { canAccessModule } from '@/core/rbac';
import { moduleRegistry } from '@/core/moduleRegistry';
import TripsList from './TripsList';

// Force dynamic rendering as we depend on cookies/auth
export const dynamic = 'force-dynamic';

export default async function TripsPage({ params }: { params: Promise<{ tenantSlug: string }> }) {
    // 1. Auth Check
    const supabase = createAuthClient();
    const { data: { user } } = await supabase.auth.getUser();

    if (!user) {
        redirect('/login');
    }

    // 2. Tenant Resolution
    const tenantRepo = new SupabaseTenantRepository();
    const { tenantSlug } = await params;
    const tenant = await tenantRepo.resolveTenantForUser(user.id, tenantSlug);

    if (!tenant) {
        notFound();
    }

    // 3. Resolve Contexts
    const [tenantContext, userContext] = await Promise.all([
        getTenantContext(tenant.id, tenant.slug),
        getUserContext(user.id, tenant.id)
    ]);

    if (!tenantContext || !userContext) {
        forbidden();
    }

    // 4. Module Access Check
    // We check the specific sub-module for Trips
    const moduleDef = moduleRegistry.getModule('ferry-booking/trips');
    if (!moduleDef) {
        console.error("Module 'ferry-booking/trips' not found in registry");
        notFound();
    }

    if (!canAccessModule(moduleDef, userContext!)) {
        forbidden();
    }

    // 5. Granular Feature Permission Check
    const hasPermission = userContext!.permissions.includes('trips.view') || userContext!.permissions.includes('*');
    if (!hasPermission) {
        forbidden();
    }

    // 6. Data Fetch (Strict Repository Pattern)
    const tripRepo = new SupabaseTripRepository();
    const orderRepo = new SupabaseOrderRepository();
    const resRepo = new SupabaseReservationRepository();
    const service = new FerrySalesService(tripRepo, orderRepo, resRepo);

    // Pass tenant_id explicitly (Fail-Closed)
    // TODO: Add support for pagination or date filtering in the query string
    const trips = await service.getTrips(tenant.id);

    const canCreate = userContext!.permissions.includes('trips.create') || userContext!.permissions.includes('*');
    const canDelete = userContext!.permissions.includes('trips.delete') || userContext!.permissions.includes('*');

    // 7. Render
    return <TripsList trips={trips} tenantSlug={tenantSlug} canCreate={canCreate} canDelete={canDelete} />;
}


