import { createClient } from "@/utils/supabase/server"
import { generateInvoicePDFBuffer } from "@/utils/invoice-pdf"
import { revalidatePath } from "next/cache"

export async function cancelOrder(orderId: string) {
    try {
        const supabase = await createClient()

        // 1. Update Order Status
        const { error: orderError } = await supabase
            .from("clnt_orders")
            .update({ status: 'CANCELLED', payment_status: 'REFUNDED' }) // Simplified refund logic
            .eq('id', orderId)

        if (orderError) throw new Error("Failed to update order status: " + orderError.message)

        // 2. Update Reservations Linked to Order
        const { error: resError } = await supabase
            .from("clnt_reservations")
            .update({ status: 'CANCELLED' })
            .eq('order_id', orderId)

        if (resError) throw new Error("Failed to cancel linked reservations: " + resError.message)

        revalidatePath('/admin/orders')
        revalidatePath(`/orders/${orderId}`)

        return { success: true }
    } catch (e: any) {
        console.error("Cancel Order Error:", e)
        return { success: false, error: e.message }
    }
}

export async function getInvoicePdf(orderId: string) {
    try {
        const supabase = await createClient()

        // Fetch Order & Invoice Data
        const { data: order, error: orderError } = await supabase
            .from("clnt_orders")
            .select(`
                *,
                reservations (
                    *,
                    trip:clnt_trips (
                        departure_time,
                        route:clnt_routes(origin:clnt_locations!origin_id(name), destination:clnt_locations!destination_id(name)),
                        ferry:clnt_ferries(name)
                    )
                ),
                invoices (*)
            `)
            .eq('id', orderId)
            .single()

        if (orderError || !order) throw new Error("Order not found")

        const invoice = order.invoices?.[0]
        // Fallback if no invoice record exists (legacy orders)
        const invoiceNumber = invoice?.invoice_number || `TMP-${orderId.slice(0, 8).toUpperCase()}`

        // Mock Summary Object expected by PDF generator
        // We aggregate reservations
        const mockSummary = {
            id: invoiceNumber,
            currency: 'PLN', // Default
            customer_first_name: order.customer_first_name,
            customer_last_name: order.customer_last_name || '',
            customer_email: order.customer_email,
            buyer_data: invoice?.buyer_data, // Use specific buyer data if available
            trip: {
                // If multiple trips, just show "Multi-Trip Order" or first one
                route: {
                    origin: { name: order.reservations.length > 1 ? 'Multiple Routes' : order.reservations[0]?.trip?.route?.origin?.name || 'Unknown' },
                    destination: { name: order.reservations.length > 1 ? 'See Details' : order.reservations[0]?.trip?.route?.destination?.name || 'Unknown' }
                },
                ferry: { name: order.reservations[0]?.trip?.ferry?.name || 'FerryPortal Fleet' },
                departure_time: order.reservations[0]?.trip?.departure_time || new Date().toISOString()
            },
            // Aggregate counts
            count_passengers: order.reservations.reduce((s: number, r: any) => s + (r.count_passengers || 0), 0),
            count_bikes: order.reservations.reduce((s: number, r: any) => s + (r.count_bikes || 0), 0),
            count_pets: order.reservations.reduce((s: number, r: any) => s + (r.count_pets || 0), 0),
            total_amount: order.total_amount
        }

        const pdfBuffer = await generateInvoicePDFBuffer(mockSummary)

        // Return base64 for client download
        return { success: true, pdfBase64: pdfBuffer.toString('base64'), filename: `Invoice_${invoiceNumber}.pdf` }

    } catch (e: any) {
        console.error("Get Invoice PDF Error:", e)
        return { success: false, error: e.message }
    }
}

'use client'

import { useState } from "react"
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from "@/components/ui/table"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { format } from "date-fns"
import {
    DropdownMenu,
    DropdownMenuCheckboxItem,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuLabel,
    DropdownMenuSeparator,
    DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { Settings2, Eye, MoreHorizontal, FileDown, Ban, ChevronDown, ChevronRight, FileText } from "lucide-react"
import Link from "next/link"
import { cancelOrder, getInvoicePdf } from "./actions"
import { useTranslation } from "react-i18next"

export function OrdersTable({ orders }: { orders: any[] }) {
    const { t } = useTranslation()

    const COLUMNS = [
        { id: 'expand', label: '' },
        { id: 'created_at', label: t('admin.ordersPage.table.date') },
        { id: 'id', label: t('admin.ordersPage.table.orderId') },
        { id: 'customer', label: t('admin.ordersPage.table.customer') },
        { id: 'items', label: t('admin.ordersPage.table.items') },
        { id: 'status', label: t('admin.ordersPage.table.status') },
        { id: 'amount', label: t('admin.ordersPage.table.totalAmount') },
        { id: 'actions', label: t('admin.ordersPage.table.actions') },
    ]

    const [columnVisibility, setColumnVisibility] = useState<Record<string, boolean>>({
        created_at: true,
        id: true,
        customer: true,
        items: true,
        status: true,
        amount: true,
        actions: true,
    })
    const [expandedRows, setExpandedRows] = useState<Set<string>>(new Set())
    const [loadingPdf, setLoadingPdf] = useState<string | null>(null)

    const isVisible = (colId: string) => columnVisibility[colId] ?? true

    const toggleRow = (id: string) => {
        const newSet = new Set(expandedRows)
        if (newSet.has(id)) newSet.delete(id)
        else newSet.add(id)
        setExpandedRows(newSet)
    }

    const handleDownloadInvoice = async (orderId: string) => {
        setLoadingPdf(orderId)
        try {
            const res = await getInvoicePdf(orderId)
            if (res.success && res.pdfBase64) {
                const link = document.createElement('a')
                link.href = `data:application/pdf;base64,${res.pdfBase64}`
                link.download = res.filename || 'invoice.pdf'
                document.body.appendChild(link)
                link.click()
                document.body.removeChild(link)
            } else {
                alert("Failed to generate invoice: " + res.error)
            }
        } catch (e) {
            alert("Error downloading invoice")
        } finally {
            setLoadingPdf(null)
        }
    }

    const handleCancelOrder = async (orderId: string) => {
        if (!confirm(t('admin.ordersPage.table.actions_label.cancelOrder') + "?")) return

        const res = await cancelOrder(orderId)
        if (!res.success) {
            alert("Failed to cancel order: " + res.error)
        }
    }

    return (
        <div className="space-y-4">
            <div className="flex justify-end">
                <DropdownMenu>
                    <DropdownMenuTrigger asChild>
                        <Button variant="outline" size="sm" className="ml-auto hidden h-8 lg:flex">
                            <Settings2 className="mr-2 h-4 w-4" />
                            Columns
                        </Button>
                    </DropdownMenuTrigger>
                    <DropdownMenuContent align="end" className="w-[150px]">
                        <DropdownMenuLabel>Toggle columns</DropdownMenuLabel>
                        <DropdownMenuSeparator />
                        {COLUMNS.map((column) => (
                            // Skip expand column in toggle
                            column.id !== 'expand' && (
                                <DropdownMenuCheckboxItem
                                    key={column.id}
                                    className="capitalize"
                                    checked={columnVisibility[column.id]}
                                    onCheckedChange={(value) =>
                                        setColumnVisibility((prev) => ({ ...prev, [column.id]: value }))
                                    }
                                >
                                    {column.label}
                                </DropdownMenuCheckboxItem>
                            )
                        ))}
                    </DropdownMenuContent>
                </DropdownMenu>
            </div>

            <div className="border rounded-lg bg-white shadow-sm overflow-hidden">
                <Table>
                    <TableHeader className="bg-gray-50">
                        <TableRow>
                            <TableHead className="w-[50px]"></TableHead>
                            {isVisible('created_at') && <TableHead>{t('admin.ordersPage.table.date')}</TableHead>}
                            {isVisible('id') && <TableHead>{t('admin.ordersPage.table.orderId')}</TableHead>}
                            {isVisible('customer') && <TableHead>{t('admin.ordersPage.table.customer')}</TableHead>}
                            {isVisible('items') && <TableHead className="text-center">{t('admin.ordersPage.table.items')}</TableHead>}
                            {isVisible('status') && <TableHead>{t('admin.ordersPage.table.status')}</TableHead>}
                            {isVisible('amount') && <TableHead className="text-right">{t('admin.ordersPage.table.totalAmount')}</TableHead>}
                            {isVisible('actions') && <TableHead className="text-right">{t('admin.ordersPage.table.actions')}</TableHead>}
                        </TableRow>
                    </TableHeader>
                    <TableBody>
                        {(!orders || orders.length === 0) && (
                            <TableRow>
                                <TableCell colSpan={COLUMNS.length} className="text-center h-24 text-muted-foreground italic">
                                    {t('admin.ordersPage.table.noOrders')}
                                </TableCell>
                            </TableRow>
                        )}
                        {orders?.map((order: any) => (
                            <>
                                <TableRow
                                    key={order.id}
                                    className={`cursor-pointer hover:bg-slate-50 ${expandedRows.has(order.id) ? 'bg-slate-50' : ''}`}
                                    onClick={() => toggleRow(order.id)}
                                >
                                    <TableCell>
                                        {expandedRows.has(order.id) ? <ChevronDown size={16} /> : <ChevronRight size={16} />}
                                    </TableCell>
                                    {isVisible('created_at') && (
                                        <TableCell className="text-xs text-muted-foreground whitespace-nowrap">
                                            {order.created_at ? format(new Date(order.created_at), "dd.MM.yyyy HH:mm") : '-'}
                                        </TableCell>
                                    )}
                                    {isVisible('id') && (
                                        <TableCell className="font-mono text-xs text-slate-500">
                                            {order.id.slice(0, 8)}...
                                        </TableCell>
                                    )}
                                    {isVisible('customer') && (
                                        <TableCell>
                                            <div className="flex flex-col">
                                                <div className="font-medium text-sm text-slate-900">
                                                    {order.customer_first_name} {order.customer_last_name}
                                                </div>
                                                <div className="text-xs text-muted-foreground">{order.customer_email}</div>
                                            </div>
                                        </TableCell>
                                    )}
                                    {isVisible('items') && (
                                        <TableCell className="text-center">
                                            <Badge variant="outline" className="bg-white">
                                                {order.reservations ? order.reservations.length : 0} Res.
                                            </Badge>
                                        </TableCell>
                                    )}
                                    {isVisible('status') && (
                                        <TableCell>
                                            <Badge
                                                variant={order.status === 'COMPLETED' ? 'secondary' : order.status === 'CANCELLED' ? 'destructive' : 'outline'}
                                                className={order.status === 'COMPLETED' ? 'bg-green-100 text-green-700 hover:bg-green-100' : ''}
                                            >
                                                {order.status}
                                            </Badge>
                                        </TableCell>
                                    )}
                                    {isVisible('amount') && (
                                        <TableCell className="text-right font-bold">
                                            {order.total_amount} PLN
                                        </TableCell>
                                    )}
                                    {isVisible('actions') && (
                                        <TableCell className="text-right" onClick={(e) => e.stopPropagation()}>
                                            <div className="flex justify-end gap-1">
                                                <Button
                                                    size="sm"
                                                    variant="ghost"
                                                    onClick={() => handleDownloadInvoice(order.id)}
                                                    disabled={loadingPdf === order.id}
                                                    title={t('admin.ordersPage.table.actions_label.downloadInvoice')}
                                                >
                                                    {loadingPdf === order.id ? <span className="animate-spin">⌛</span> : <FileDown size={16} />}
                                                </Button>

                                                <DropdownMenu>
                                                    <DropdownMenuTrigger asChild>
                                                        <Button size="sm" variant="ghost">
                                                            <MoreHorizontal size={16} />
                                                        </Button>
                                                    </DropdownMenuTrigger>
                                                    <DropdownMenuContent align="end">
                                                        <DropdownMenuLabel>{t('admin.ordersPage.table.actions')}</DropdownMenuLabel>
                                                        <DropdownMenuItem asChild>
                                                            <Link href={`/orders/${order.id}`} target="_blank">
                                                                <Eye className="mr-2 h-4 w-4" /> {t('admin.ordersPage.table.actions_label.viewDetails')}
                                                            </Link>
                                                        </DropdownMenuItem>
                                                        <DropdownMenuSeparator />
                                                        <DropdownMenuItem
                                                            className="text-red-600 focus:text-red-600"
                                                            onClick={() => handleCancelOrder(order.id)}
                                                        >
                                                            <Ban className="mr-2 h-4 w-4" /> {t('admin.ordersPage.table.actions_label.cancelOrder')}
                                                        </DropdownMenuItem>
                                                    </DropdownMenuContent>
                                                </DropdownMenu>
                                            </div>
                                        </TableCell>
                                    )}
                                </TableRow>

                                {expandedRows.has(order.id) && (
                                    <TableRow className="bg-slate-50 hover:bg-slate-50">
                                        <TableCell colSpan={COLUMNS.length + 1} className="p-0">
                                            <div className="p-4 pl-12 border-t border-b border-slate-100">
                                                <h4 className="text-xs font-semibold uppercase text-slate-500 mb-2">{t('admin.ordersPage.table.reservationsInOrder')}</h4>
                                                <div className="space-y-2">
                                                    {order.reservations?.map((res: any) => (
                                                        <div key={res.id} className="flex items-center justify-between bg-white p-2 rounded border border-slate-100 text-sm shadow-sm">
                                                            <div className="flex gap-4 items-center">
                                                                <span className="font-mono text-xs text-slate-400">#{res.id.slice(0, 8)}</span>
                                                                <span className="font-medium text-slate-700">
                                                                    Reservation Link
                                                                </span>
                                                            </div>
                                                            <div className="flex gap-4 text-xs text-slate-500 items-center">
                                                                <span>{res.count_passengers} {t('admin.ordersPage.table.pax')}</span>
                                                                <span className="font-semibold text-slate-700">{res.total_amount} PLN</span>
                                                                <Link href={`/admin/reservations?q=${res.id}`} className="text-blue-600 hover:underline bg-blue-50 px-2 py-1 rounded">
                                                                    {t('admin.ordersPage.table.manage')}
                                                                </Link>
                                                            </div>
                                                        </div>
                                                    ))}
                                                    {(!order.reservations || order.reservations.length === 0) && (
                                                        <div className="text-xs italic text-slate-400">No linked reservations found.</div>
                                                    )}
                                                </div>

                                                <div className="mt-4 flex gap-2">
                                                    <Button size="sm" variant="outline" onClick={() => handleDownloadInvoice(order.id)} disabled={loadingPdf === order.id}>
                                                        <FileText size={14} className="mr-2 text-slate-500" />
                                                        {loadingPdf === order.id ? t('common.loading') : t('admin.ordersPage.table.actions_label.downloadInvoice')}
                                                    </Button>
                                                </div>
                                            </div>
                                        </TableCell>
                                    </TableRow>
                                )}
                            </>
                        ))}
                    </TableBody>
                </Table>
            </div>
        </div>
    )
}

import { createClient } from "@/utils/supabase/server"
import { OrdersTable } from "./orders-table"
import { AdminPageHeader } from "@/components/admin/admin-page-header"

export default async function OrdersPage({
    searchParams,
}: {
    searchParams: { q?: string; status?: string }
}) {
    const supabase = await createClient()
    const { q: searchTerm, status } = await searchParams

    // Construct Query
    let query = supabase
        .from("clnt_orders")
        .select(`
            *,
            reservations (
                id,
                total_amount,
                count_passengers
            )
        `)
        .order("created_at", { ascending: false })

    // Apply Filters
    if (status && status !== 'all') {
        query = query.eq('status', status)
    }

    if (searchTerm) {
        const isUuidLike = /^[0-9a-fA-F-]+$/.test(searchTerm)

        const conditions = [
            `customer_email.ilike.%${searchTerm}%`,
            `customer_last_name.ilike.%${searchTerm}%`,
            `customer_first_name.ilike.%${searchTerm}%`
        ]

        if (isUuidLike) {
            conditions.push(`id.ilike.%${searchTerm}%`)
        }

        query = query.or(conditions.join(','))
    }

    const { data: orders } = await query

    return (
        <div className="space-y-6">
            <AdminPageHeader titleKey="admin.ordersPage.title" subtitleKey="admin.ordersPage.manageOrders" />

            {/* <OrdersFilters /> - Can implement later if needed, mostly search is enough */}
            <div className="flex gap-2">
                {/* Placeholder for filters if needed */}
            </div>

            <OrdersTable orders={orders || []} />
        </div>
    )
}

