'use client';

import { useState } from 'react';
import { Order } from '@/modules/ferry-booking/domain/types';
import { getOrderDetailsAction } from '../actions';

export default function OrdersClient({
    tenantSlug,
    orders
}: {
    tenantSlug: string;
    orders: Order[];
}) {
    const [selectedOrder, setSelectedOrder] = useState<Order | null>(null);
    const [loading, setLoading] = useState(false);

    const handleView = async (orderId: string) => {
        if (selectedOrder?.id === orderId) {
            setSelectedOrder(null);
            return;
        }
        setLoading(true);
        try {
            const details = await getOrderDetailsAction(tenantSlug, orderId);
            setSelectedOrder(details);
        } catch (e) {
            console.error(e);
            alert('Failed to load order details');
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="p-6">
            <h1 className="text-2xl font-bold mb-6">Orders</h1>

            <div className="bg-white rounded-lg shadow border border-gray-200 overflow-hidden">
                <table className="w-full">
                    <thead className="bg-gray-50 border-b border-gray-200">
                        <tr>
                            <th className="p-4 text-left font-semibold text-gray-600 text-sm">Order ID</th>
                            <th className="p-4 text-left font-semibold text-gray-600 text-sm">Customer</th>
                            <th className="p-4 text-left font-semibold text-gray-600 text-sm">Total</th>
                            <th className="p-4 text-left font-semibold text-gray-600 text-sm">Status</th>
                            <th className="p-4 text-left font-semibold text-gray-600 text-sm">Payment</th>
                            <th className="p-4 text-right font-semibold text-gray-600 text-sm">Actions</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100">
                        {orders.length === 0 && (
                            <tr>
                                <td colSpan={6} className="p-8 text-center text-gray-500">No orders found.</td>
                            </tr>
                        )}
                        {orders.map(order => (
                            <>
                                <tr key={order.id} className="hover:bg-gray-50 transition-colors">
                                    <td className="p-4 font-mono text-xs">{order.id.slice(0, 8)}...</td>
                                    <td className="p-4 text-sm">
                                        <div>{order.customerFirstName} {order.customerLastName}</div>
                                        <div className="text-gray-500 text-xs">{order.customerEmail}</div>
                                    </td>
                                    <td className="p-4 text-sm font-medium">
                                        {Number(order.totalAmount).toLocaleString(undefined, { style: 'currency', currency: order.currency })}
                                    </td>
                                    <td className="p-4">
                                        <span className={`inline-flex items-center px-2 py-0.5 rounded text-xs font-medium ${order.status === 'PAID' ? 'bg-green-100 text-green-800' :
                                            order.status === 'CANCELLED' ? 'bg-red-100 text-red-800' : 'bg-gray-100 text-gray-800'
                                            }`}>
                                            {order.status}
                                        </span>
                                    </td>
                                    <td className="p-4">
                                        <span className={`inline-flex items-center px-2 py-0.5 rounded text-xs font-medium ${order.paymentStatus === 'PAID' ? 'bg-green-100 text-green-800' :
                                            order.paymentStatus === 'REFUNDED' ? 'bg-yellow-100 text-yellow-800' : 'bg-gray-100 text-gray-800'
                                            }`}>
                                            {order.paymentStatus}
                                        </span>
                                    </td>
                                    <td className="p-4 text-right">
                                        <button
                                            onClick={() => handleView(order.id)}
                                            className="text-blue-600 hover:text-blue-800 text-sm font-medium"
                                        >
                                            {selectedOrder?.id === order.id ? 'Close' : 'View'}
                                        </button>
                                    </td>
                                </tr>
                                {selectedOrder?.id === order.id && (
                                    <tr className="bg-gray-50">
                                        <td colSpan={6} className="p-4">
                                            <div className="bg-white border rounded p-4 shadow-sm">
                                                <h3 className="font-semibold mb-2">Reservations in Order</h3>
                                                {loading ? <div>Loading...</div> : (
                                                    <div className="space-y-2">
                                                        {selectedOrder.reservations?.map(res => (
                                                            <div key={res.id} className="flex justify-between items-center text-sm border-b pb-2">
                                                                <div>
                                                                    <div className="font-medium">Trip: {res.trip?.ferry?.name || 'Unknown Ferry'}</div>
                                                                    <div className="text-gray-500">
                                                                        {res.trip ? new Date(res.trip.departureTime).toLocaleString() : 'Date Unknown'}
                                                                    </div>
                                                                </div>
                                                                <div className="text-right">
                                                                    <div>{res.countPassengers} Pax, {res.countVehicles} Vehicles</div>
                                                                    <div className="font-mono">{Number(res.totalAmount).toLocaleString(undefined, { style: 'currency', currency: order.currency })}</div>
                                                                </div>
                                                            </div>
                                                        ))}
                                                    </div>
                                                )}
                                            </div>
                                        </td>
                                    </tr>
                                )}
                            </>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
    );
}


import { Suspense } from 'react';
import { verifyPageAccess } from '@/core/auth/actions';
import { listOrdersAction } from '../actions';
import OrdersClient from './OrdersClient';
import { Loader2 } from 'lucide-react';

export default async function OrdersPage({ params }: { params: Promise<{ tenantSlug: string }> }) {
    const { tenantSlug } = await params;
    await verifyPageAccess(tenantSlug, 'orders.view');

    const orders = await listOrdersAction(tenantSlug);

    return (
        <Suspense fallback={<div className="flex justify-center p-12"><Loader2 className="animate-spin h-8 w-8 text-indigo-600" /></div>}>
            <OrdersClient tenantSlug={tenantSlug} orders={orders} />
        </Suspense>
    );
}

'use client';

import { Invoice } from '../types';
