'use server'

import { createClient } from "@/utils/supabase/server"
import { revalidatePath } from "next/cache"

export async function createRoute(formData: FormData) {
    const supabase = await createClient()

    const origin_id = formData.get("origin_id") as string
    const destination_id = formData.get("destination_id") as string
    let ferry_id = formData.get("ferry_id") as string | null
    if (ferry_id === "none") ferry_id = null

    const estimated_duration_minutes = parseInt(formData.get("duration") as string)
    const is_standard = formData.get("is_standard") === "on"

    try {
        const { error } = await supabase.from("clnt_routes").insert({
            origin_id,
            destination_id,
            ferry_id,
            estimated_duration_minutes,
            is_standard
        })

        if (error) throw error
        revalidatePath("/admin/routes")
        return { success: true }
    } catch (e: any) {
        console.error("Create Route Error:", e)
        return { success: false, error: e.message }
    }
}

export async function updateRoute(id: string, formData: FormData) {
    const supabase = await createClient()

    const origin_id = formData.get("origin_id") as string
    const destination_id = formData.get("destination_id") as string
    let ferry_id = formData.get("ferry_id") as string | null
    if (ferry_id === "none") ferry_id = null

    const estimated_duration_minutes = parseInt(formData.get("duration") as string)
    const is_standard = formData.get("is_standard") === "on"

    try {
        const { error } = await supabase.from("clnt_routes").update({
            origin_id,
            destination_id,
            ferry_id,
            estimated_duration_minutes,
            is_standard
        }).eq("id", id)

        if (error) throw error
        revalidatePath("/admin/routes")
        return { success: true }
    } catch (e: any) {
        console.error("Update Route Error:", e)
        return { success: false, error: e.message }
    }
}

