import { createAuthClient } from '@/infra/supabase/server-auth';
import { SupabaseTenantRepository } from '@/infra/repositories/SupabaseTenantRepository';
import { SupabaseFerryRouteRepository } from '@/modules/ferry-booking/infrastructure/SupabaseFerryRouteRepository';
import { FerryBookingService } from '@/modules/ferry-booking/application/FerryBookingService';
import { notFound, redirect } from 'next/navigation';
import { createRouteAction } from '@/modules/ferry-booking/routes/actions';
import { moduleRegistry } from '@/core/moduleRegistry';
import { canAccessModule } from '@/core/rbac';
import { getUserContext } from '@/core/context/getUserContext';
import { getTenantContext } from '@/core/context/getTenantContext';

// Force dynamic rendering
export const dynamic = 'force-dynamic';

export default async function CreateRoutePage({ params }: { params: { tenantSlug: string } }) {
    // 1. Auth & Tenant
    const supabase = createAuthClient();
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) redirect('/login');

    const tenantRepo = new SupabaseTenantRepository();
    const { tenantSlug } = params;
    const tenant = await tenantRepo.resolveTenantForUser(user.id, tenantSlug);
    if (!tenant) notFound();

    // 2. Module & Permission Check
    const [tenantContext, userContext] = await Promise.all([
        getTenantContext(tenant.id, tenant.slug),
        getUserContext(user.id, tenant.id)
    ]);

    if (!tenantContext || !userContext) redirect('/login');

    const moduleDef = moduleRegistry.getModule('ferry-booking'); // 'ferry-booking' (root) or 'ferry-booking/routes'?
    // Registry likely has 'ferry-booking'. The sub-app ID might be 'ferry-booking/routes' but RBAC check usually on main module?
    // The original code had: moduleRegistry.getModule('ferry-booking/routes');
    // Let's stick to original, but safeguard if not found (try 'ferry-booking'?)
    // Actually detailed inventory says 'ferry-booking/routes'.
    // Let's use 'ferry-booking' as fallback if 'ferry-booking/routes' fails?
    // Or just trust the original code's intent.
    // Original: const moduleDef = moduleRegistry.getModule('ferry-booking/routes');

    let finalModuleDef = moduleRegistry.getModule('ferry-booking/routes');
    if (!finalModuleDef) {
        // Fallback to main module if specific app module not found
        finalModuleDef = moduleRegistry.getModule('ferry-booking');
    }

    if (!finalModuleDef || !canAccessModule(finalModuleDef, userContext)) {
        notFound();
    }

    if (!userContext.permissions.includes('routes.create') && !userContext.permissions.includes('*')) {
        redirect('/admin/unauthorized');
    }

    // 2. Data Fetch (Locations)
    const repo = new SupabaseFerryRouteRepository();
    const service = new FerryBookingService(repo);
    // Explicit tenant_id
    const locations = await service.getLocations(tenant.id);

    // 3. Render
    return (
        <div className="p-6 max-w-lg mx-auto bg-white rounded shadow">
            <h1 className="text-2xl font-bold mb-6">Create New Route</h1>

            <form action={createRouteAction} className="space-y-4">
                <input type="hidden" name="tenantSlug" value={tenantSlug} />

                <div>
                    <label className="block text-sm font-medium mb-1">Origin</label>
                    <select name="originId" className="w-full border p-2 rounded" required>
                        <option value="">Select Origin...</option>
                        {locations.map(loc => (
                            <option key={loc.id} value={loc.id}>{loc.name}</option>
                        ))}
                    </select>
                </div>

                <div>
                    <label className="block text-sm font-medium mb-1">Destination</label>
                    <select name="destinationId" className="w-full border p-2 rounded" required>
                        <option value="">Select Destination...</option>
                        {locations.map(loc => (
                            <option key={loc.id} value={loc.id}>{loc.name}</option>
                        ))}
                    </select>
                </div>

                <div>
                    <label className="block text-sm font-medium mb-1">Duration (Minutes)</label>
                    <input
                        type="number"
                        name="duration"
                        className="w-full border p-2 rounded"
                        defaultValue={60}
                        min={1}
                        required
                    />
                </div>

                <button
                    type="submit"
                    className="w-full bg-blue-600 text-white py-2 px-4 rounded hover:bg-blue-700"
                >
                    Create Route
                </button>
            </form>
        </div>
    );
}


import { createAuthClient } from '@/infra/supabase/server-auth';
import { SupabaseTenantRepository } from '@/infra/repositories/SupabaseTenantRepository';
import { getTenantContext } from '@/core/context/getTenantContext';
import { getUserContext } from '@/core/context/getUserContext';
import { SupabaseFerryRouteRepository } from '@/modules/ferry-booking/infrastructure/SupabaseFerryRouteRepository';
import { FerryBookingService } from '@/modules/ferry-booking/application/FerryBookingService';
import { notFound, redirect, forbidden } from 'next/navigation';
import { canAccessModule } from '@/core/rbac';
import { moduleRegistry } from '@/core/moduleRegistry';
import RoutesClient from './RoutesClient';

// Force dynamic rendering as we depend on cookies/auth
export const dynamic = 'force-dynamic';

export default async function RoutesPage({ params }: { params: { tenantSlug: string } }) {
    const { tenantSlug } = params;
    // 1. Resolve Auth Context (Hits the memoized React cache from AdminLayout)
    const { resolveAuthContext } = await import('@/core/context/resolveAuthContext');
    const authContext = await resolveAuthContext(tenantSlug);

    if (!authContext) {
        notFound();
    }

    const { user, userContext, tenantContext, tenant } = authContext;

    // 2. Module Access Check
    const moduleDef = moduleRegistry.getModule('ferry-booking');
    if (!moduleDef) {
        console.error("Module 'ferry-booking' not found in registry");
        notFound();
    }

    if (!canAccessModule(moduleDef, userContext)) {
        console.warn(`User ${user.id} denied access to module ferry-booking`);
        forbidden();
    }

    // 3. Granular Feature Permission Check
    // Rule: Must have 'routes.view' or Superuser '*'
    const hasPermission = userContext.permissions.includes('routes.view') || userContext.permissions.includes('*');
    if (!hasPermission) {
        console.warn(`User ${user.id} missing 'routes.view' permission`);
        forbidden();
    }

    // 4. Data Fetch (Strict Repository Pattern)
    const dStart = performance.now();
    const routesRepo = new SupabaseFerryRouteRepository();
    const service = new FerryBookingService(routesRepo);

    // Pass tenant_id explicitly (Fail-Closed)
    const routes = await service.getRoutes(tenant.id);
    console.log(`[Perf] RoutesPage getRoutes: ${(performance.now() - dStart).toFixed(2)}ms`);

    // 5. Render
    return <RoutesClient routes={routes} tenantSlug={tenantSlug} />;
}


'use client';

import { useState, useTransition } from 'react';
import Link from 'next/link';
import { updateRouteStatusAction, deleteRouteAction } from '../actions';
import { FerryRoute } from '@/modules/ferry-booking/domain/types';

export default function RoutesClient({
    routes,
    tenantSlug
}: {
    routes: FerryRoute[];
    tenantSlug: string;
}) {
    return (
        <div className="p-6">
            <div className="flex justify-between items-center mb-6">
                <h1 className="text-2xl font-bold">Ferry Routes</h1>
                <Link
                    href={`/admin/t/${tenantSlug}/apps/ferry-booking/routes/create`}
                    className="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700 transition-colors shadow-sm font-medium"
                >
                    + Create Route
                </Link>
            </div>

            <pre className="bg-gray-100 p-2 rounded text-xs mb-4 text-gray-500">
                Tenant Scope: {tenantSlug}
            </pre>

            {routes.length === 0 ? (
                <div className="text-center p-12 bg-white rounded border border-gray-200 shadow-sm">
                    <p className="text-gray-500 mb-4">No routes defined for this tenant.</p>
                    <Link
                        href={`/admin/t/${tenantSlug}/apps/ferry-booking/routes/create`}
                        className="text-blue-600 hover:underline"
                    >
                        Create your first route
                    </Link>
                </div>
            ) : (
                <div className="bg-white rounded-lg shadow border border-gray-200 overflow-hidden">
                    <div className="grid divide-y divide-gray-100">
                        {routes.map((route) => (
                            <RouteRow key={route.id} route={route} tenantSlug={tenantSlug} />
                        ))}
                    </div>
                </div>
            )}
        </div>
    );
}

function RouteRow({ route, tenantSlug }: { route: FerryRoute; tenantSlug: string }) {
    const [isPending, startTransition] = useTransition();

    const handleToggle = () => {
        const newStatus = !route.isActive;
        if (confirm(`Are you sure you want to ${newStatus ? 'activate' : 'deactivate'} this route?`)) {
            startTransition(async () => {
                await updateRouteStatusAction(tenantSlug, route.id, newStatus);
            });
        }
    };

    return (
        <div className={`p-4 flex justify-between items-center hover:bg-gray-50 transition-colors ${!route.isActive ? 'opacity-75 bg-gray-50' : ''}`}>
            <div>
                <div className="flex items-center gap-3">
                    <span className="font-semibold text-lg text-gray-900">
                        {route.origin?.name || 'Unknown'} <span className="text-gray-400">→</span> {route.destination?.name || 'Unknown'}
                    </span>
                    <span
                        className={`px-2 py-0.5 rounded text-xs font-medium uppercase tracking-wide ${route.isActive
                            ? 'bg-green-100 text-green-800'
                            : 'bg-red-100 text-red-800'
                            }`}
                    >
                        {route.isActive ? 'Active' : 'Inactive'}
                    </span>
                </div>
                <div className="text-sm text-gray-500 mt-1 flex gap-4">
                    <span>⏱ {route.estimatedDurationMinutes} min</span>
                    {route.defaultFerry && (
                        <span>🚢 {route.defaultFerry.name}</span>
                    )}
                </div>
            </div>

            <div className="flex gap-2">
                <Link
                    href={`/admin/t/${tenantSlug}/apps/ferry-booking/routes/${route.id}/edit`}
                    className="px-3 py-1.5 text-xs font-medium text-gray-600 bg-white border border-gray-300 rounded hover:bg-gray-50 disabled:opacity-50"
                /* Edit not fully implemented yet, but keeping link for parity structure */
                >
                    Edit
                </Link>
                <button
                    onClick={handleToggle}
                    disabled={isPending}
                    className={`px-3 py-1.5 text-xs font-medium rounded border disabled:opacity-50 ${route.isActive
                        ? 'text-red-600 border-red-200 hover:bg-red-50'
                        : 'text-green-600 border-green-200 hover:bg-green-50'
                        }`}
                >
                    {isPending ? 'Saving...' : (route.isActive ? 'Deactivate' : 'Activate')}
                </button>
                <DeleteRouteButton routeId={route.id} tenantSlug={tenantSlug} />
            </div>
        </div>
    );
}

function DeleteRouteButton({ routeId, tenantSlug }: { routeId: string; tenantSlug: string }) {
    const [isPending, startTransition] = useTransition();

    const handleDelete = async () => {
        if (confirm('Are you sure you want to delete this route?')) {
            startTransition(async () => {
                await deleteRouteAction(tenantSlug, routeId);
            });
        }
    };

    return (
        <button
            onClick={handleDelete}
            disabled={isPending}
            className="px-3 py-1.5 text-xs font-medium text-red-600 border border-red-200 rounded hover:bg-red-50 disabled:opacity-50"
        >
            {isPending ? 'Deleting...' : 'Delete'}
        </button>
    );
}

