'use client';

import React, { useState, useEffect } from 'react';
import { FerryTrip as Trip } from '@/modules/ferry-booking/domain/types';
import { getCalendarTripsAction } from '@/modules/ferry-planning/calendar/actions';
import { ChevronLeft, ChevronRight, Loader2, Ship } from 'lucide-react';

interface CalendarClientProps {
    tenantId: string;
}

export default function CalendarClient({ tenantId }: CalendarClientProps) {
    const [currentDate, setCurrentDate] = useState(new Date());
    const [trips, setTrips] = useState<Trip[]>([]);
    const [loading, setLoading] = useState(false);
    const [selectedDay, setSelectedDay] = useState<Date | null>(null);

    const getMonthRange = (date: Date) => {
        const start = new Date(date.getFullYear(), date.getMonth(), 1);
        const end = new Date(date.getFullYear(), date.getMonth() + 1, 0, 23, 59, 59);
        return { start, end };
    };

    const fetchTrips = async () => {
        setLoading(true);
        const { start, end } = getMonthRange(currentDate);
        try {
            const data = await getCalendarTripsAction(tenantId, start.toISOString(), end.toISOString());
            setTrips(data);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchTrips();
    }, [currentDate]);

    const changeMonth = (delta: number) => {
        const newDate = new Date(currentDate);
        newDate.setMonth(newDate.getMonth() + delta);
        setCurrentDate(newDate);
        setSelectedDay(null);
    };

    const renderCalendarGrid = () => {
        const { start, end } = getMonthRange(currentDate);
        const startDay = start.getDay(); // 0 is Sunday
        const daysInMonth = end.getDate();

        const days = [];
        // Empty slots for previous month
        for (let i = 0; i < startDay; i++) {
            days.push(<div key={`empty-${i}`} className="bg-gray-50 border h-24" />);
        }

        for (let day = 1; day <= daysInMonth; day++) {
            const dateStr = new Date(currentDate.getFullYear(), currentDate.getMonth(), day).toISOString().split('T')[0];
            const dayTrips = trips.filter(t => t.departureTime.startsWith(dateStr));

            days.push(
                <div
                    key={day}
                    onClick={() => setSelectedDay(new Date(currentDate.getFullYear(), currentDate.getMonth(), day))}
                    className={`border h-24 p-2 relative hover:bg-blue-50 cursor-pointer overflow-hidden ${selectedDay?.getDate() === day ? 'ring-2 ring-blue-500' : ''}`}
                >
                    <span className="text-sm font-semibold text-gray-700">{day}</span>
                    <div className="mt-1 space-y-1">
                        {dayTrips.slice(0, 3).map(t => (
                            <div key={t.id} className="text-xs bg-blue-100 text-blue-800 rounded px-1 truncate">
                                {new Date(t.departureTime).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                            </div>
                        ))}
                        {dayTrips.length > 3 && (
                            <div className="text-xs text-gray-500 font-medium">+{dayTrips.length - 3} more</div>
                        )}
                    </div>
                </div>
            );
        }
        return days;
    };

    const tripsForSelectedDay = selectedDay
        ? trips.filter(t => t.departureTime.startsWith(selectedDay.toISOString().split('T')[0]))
        : [];

    return (
        <div className="flex flex-col lg:flex-row gap-6 h-[calc(100vh-200px)]">
            <div className="flex-1 flex flex-col bg-white rounded-lg shadow border">
                <div className="p-4 flex justify-between items-center border-b">
                    <h2 className="text-lg font-bold text-gray-900">
                        {currentDate.toLocaleString('default', { month: 'long', year: 'numeric' })}
                    </h2>
                    <div className="flex gap-2">
                        <button onClick={() => changeMonth(-1)} className="p-1 hover:bg-gray-100 rounded">
                            <ChevronLeft className="w-5 h-5" />
                        </button>
                        <button onClick={() => changeMonth(1)} className="p-1 hover:bg-gray-100 rounded">
                            <ChevronRight className="w-5 h-5" />
                        </button>
                    </div>
                </div>

                <div className="grid grid-cols-7 text-center py-2 border-b bg-gray-50 text-xs font-semibold text-gray-600">
                    <div>Sun</div><div>Mon</div><div>Tue</div><div>Wed</div><div>Thu</div><div>Fri</div><div>Sat</div>
                </div>

                <div className="grid grid-cols-7 flex-1 auto-rows-fr overflow-y-auto">
                    {loading ? (
                        <div className="col-span-7 flex items-center justify-center p-12">
                            <Loader2 className="w-8 h-8 animate-spin text-gray-300" />
                        </div>
                    ) : (
                        renderCalendarGrid()
                    )}
                </div>
            </div>

            {/* Side Panel for Day Details */}
            <div className="w-full lg:w-80 bg-white rounded-lg shadow border p-4 flex flex-col">
                <h3 className="font-semibold text-gray-900 mb-4 border-b pb-2">
                    {selectedDay ? selectedDay.toDateString() : 'Select a day'}
                </h3>

                <div className="flex-1 overflow-y-auto space-y-3">
                    {!selectedDay ? (
                        <p className="text-sm text-gray-500 text-center mt-10">Click on a calendar day to view scheduled trips.</p>
                    ) : tripsForSelectedDay.length === 0 ? (
                        <p className="text-sm text-gray-500 text-center mt-10">No trips scheduled.</p>
                    ) : (
                        tripsForSelectedDay.map(t => (
                            <div key={t.id} className="p-3 bg-gray-50 rounded border text-sm">
                                <div className="flex items-center gap-2 font-medium text-gray-900">
                                    <Ship className="w-3 h-3 text-blue-500" />
                                    {(t as any).ferry?.name || 'Unknown Ferry'}
                                </div>
                                <div className="mt-1 flex justify-between">
                                    <span>{(t as any).route?.origin?.name} → {(t as any).route?.destination?.name}</span>
                                </div>
                                <div className="mt-1 text-xs text-gray-500">
                                    {new Date(t.departureTime).toLocaleTimeString()} - {new Date(t.arrivalTime).toLocaleTimeString()}
                                </div>
                                <div className={`mt-2 text-xs px-2 py-0.5 inline-block rounded-full ${t.status === 'SCHEDULED' || t.status === 'COMPLETED' ? 'bg-green-100 text-green-800' :
                                    t.status === 'CANCELLED' ? 'bg-red-100 text-red-800' : 'bg-gray-100 text-gray-800'
                                    }`}>
                                    {t.status}
                                </div>
                            </div>
                        ))
                    )}
                </div>
            </div>
        </div>
    );
}


import { Suspense } from 'react';
import { verifyPageAccess } from '@/core/auth/actions';
import CalendarClient from './CalendarClient';
import { Loader2 } from 'lucide-react';

export default async function CalendarPage({ params }: { params: { tenantSlug: string } }) {
    const { tenantId } = await verifyPageAccess(params.tenantSlug);

    return (
        <div className="p-6 h-full">
            <h1 className="text-2xl font-bold mb-4">Operational Calendar</h1>
            <Suspense fallback={<div className="flex justify-center p-12"><Loader2 className="animate-spin text-gray-400" /></div>}>
                <CalendarClient tenantId={tenantId} />
            </Suspense>
        </div>
    );
}

