'use server'

import { createClient } from "@/utils/supabase/server"
import { revalidatePath } from "next/cache"

export async function createTemplate(formData: FormData) {
    const supabase = await createClient()
    const name = formData.get("name") as string
    const description = formData.get("description") as string

    const { data, error } = await supabase.from("clnt_schedule_templates").insert({
        name,
        description
    }).select().single()

    if (error) throw new Error(error.message)
    revalidatePath("/admin/templates")
    return data
}

export async function deleteTemplate(id: string) {
    const supabase = await createClient()
    const { error } = await supabase.from("clnt_schedule_templates").delete().eq("id", id)
    if (error) throw new Error(error.message)
    revalidatePath("/admin/templates")
}

export async function addItemToTemplate(templateId: string, formData: FormData) {
    const supabase = await createClient()
    const route_id = formData.get("route_id") as string
    const departure_time = formData.get("departure_time") as string // "08:00"

    const { error } = await supabase.from("clnt_schedule_template_items").insert({
        template_id: templateId,
        route_id,
        departure_time
    })

    if (error) throw new Error(error.message)
    revalidatePath("/admin/templates")
}

export async function deleteTemplateItem(itemId: string) {
    const supabase = await createClient()
    const { error } = await supabase.from("clnt_schedule_template_items").delete().eq("id", itemId)
    if (error) throw new Error(error.message)
    revalidatePath("/admin/templates")
}

export async function applyTemplate(templateId: string, ferryId: string, dates: Date[], overwrite: boolean = false) {
    const supabase = await createClient()

    // Fetch Items
    const { data: items } = await supabase.from("clnt_schedule_template_items")
        .select(`*, route:clnt_routes(estimated_duration_minutes)`)
        .eq("template_id", templateId)

    if (!items || items.length === 0) return { success: false, error: "Empty template" }

    // Range Logic for conflict check
    // We only check for the dates provided.
    // Construct range filter or just iterate? 
    // Since dates might not be contiguous or we have array, we can use `in` or `gte/lte`.
    // Assuming dates array is sorted or we take min/max.
    if (dates.length === 0) return { success: false, error: "No dates selected" }

    // Sort dates just in case
    const sortedDates = dates.sort((a, b) => a.getTime() - b.getTime())
    const startRange = sortedDates[0].toISOString()
    // endRange needs to cover the last dayfully.
    const lastDate = new Date(sortedDates[sortedDates.length - 1])
    lastDate.setHours(23, 59, 59, 999)
    const endRange = lastDate.toISOString()

    // CHECK FOR EXISTING TRIPS in this range for this ferry
    const { data: existingTrips, error: fetchError } = await supabase
        .from("clnt_trips")
        .select("id")
        .eq("ferry_id", ferryId)
        .gte("departure_time", startRange)
        .lte("departure_time", endRange)

    if (fetchError) throw new Error(fetchError.message)

    if (existingTrips && existingTrips.length > 0) {
        // Found existing trips. 
        // We only care about trips ON the dates we are applying.
        // The range query is a bit broad if dates are sparse, but usually it's a block.
        // Let's assume broad check is fine for safety, or refine if needed.

        // Check for reservations
        const tripIds = existingTrips.map(t => t.id)

        const { count: reservationCount, error: resError } = await supabase
            .from("clnt_reservations")
            .select("id", { count: 'exact', head: true })
            .in("trip_id", tripIds)

        if (resError) throw new Error(resError.message)

        if (reservationCount && reservationCount > 0) {
            return { success: false, error: `Cannot apply template: ${reservationCount} reservations exist for existing trips in this period.` }
        }

        if (!overwrite) {
            return { success: false, error: "Trips already exist for this period. Enable overwrite to replace them." }
        }

        // Safe to overwrite -> DELETE
        // First delete pricing (cascade usually handles it but explicit is safer or trust schema)
        // Schema likely has cascade.
        const { error: deleteError } = await supabase.from("clnt_trips").delete().in("id", tripIds)
        if (deleteError) throw new Error(deleteError.message)
    }

    const tripsToInsert = []
    const pricingToInsert = []
    const services = ['ADULT', 'CHILD', 'BIKE', 'PET', 'VEHICLE']

    // For each date, create trips
    for (const date of dates) {
        const dateStr = date.toISOString().split('T')[0]

        for (const item of items) {
            // item.departure_time is "08:00:00" probably
            const depTimeStr = `${dateStr}T${item.departure_time}`

            // Timezone fix: "08:00" in template means 08:00 LOCAL time (usually)
            // But here we construct ISO. 
            // If we treat "08:00" as local time, we map to UTC.
            // But previously we found that we need to send correct ISO string.
            // Here, let's assume the template stores "08:00" as the wall-clock time.
            // We need to construct the timestamp that Represents 08:00 at the location.
            // Since we don't have location TZ, we might just assume the server handles it or store it as is (if type is time without tz).
            // Supabase 'time' type is without timezone.
            // When we create a trip, 'departure_time' is timestamptz.
            // We need to convert "Date + 08:00" -> ISO Timestamp.
            // Simple hack: Assume 'Europe/Warsaw' or just use the String simple concat if the server treats ISO without Z as local? 
            // Ideally we shouldn't rely on that.
            // Let's assume input dates are correctly handled. 
            // For now, simple ISO construction "YYYY-MM-DDTHH:MM:00"

            // We'll insert it. Supabase will interpret "YYYY-MM-DDTHH:MM:00" as UTC if no offset.
            // The user bug report suggested "adding 1 hour", meaning they wanted 10:00 but got 11:00 (UTC interpretation issue).
            // If we want 10:00 Local, and Local is UTC+1. We should send 09:00Z.
            // But we don't know the offset here easily.
            // Let's stick to simple string and assume consistency with other parts for now.

            const depIso = depTimeStr // "2024-05-20T08:00:00"

            // Calculate arrival
            const depDate = new Date(depIso)
            const arrDate = new Date(depDate.getTime() + (item.route.estimated_duration_minutes * 60000))

            tripsToInsert.push({
                route_id: item.route_id,
                ferry_id: ferryId,
                departure_time: depIso, // Check if this results in correct time
                arrival_time: arrDate.toISOString(),
                status: 'SCHEDULED'
            })
        }
    }

    // Batch Insert Trips
    const { data: createdTrips, error: tripsError } = await supabase.from("clnt_trips").insert(tripsToInsert).select()
    if (tripsError) throw new Error(tripsError.message)

    // Batch Insert Pricing
    if (createdTrips) {
        for (const trip of createdTrips) {
            for (const s of services) {
                pricingToInsert.push({
                    trip_id: trip.id,
                    service_type: s,
                    price: 0 // Default price
                })
            }
        }
        await supabase.from("clnt_trip_pricing").insert(pricingToInsert)
    }

    revalidatePath("/admin/trips")
    return { success: true }
}

import { createClient } from "@/utils/supabase/server"
import { TemplatesContent } from "@/components/admin/templates/templates-content"

export default async function TemplatesPage() {
    const supabase = await createClient()

    // Fetch Templates
    const { data: templates } = await supabase.from("clnt_schedule_templates")
        .select(`
            *,
            items:clnt_schedule_template_items(
                *,
                route:clnt_routes(
                    origin:clnt_locations!origin_id(name),
                    destination:clnt_locations!destination_id(name),
