            origin:clnt_locations!origin_id(name), 
            destination:clnt_locations!destination_id(name),
            estimated_duration_minutes,
            is_standard
        `)
        .order('is_standard', { ascending: false })

    return (
        <TemplatesContent templates={templates || []} routes={routes || []} />
    )
}

