import { listTemplatesAction } from "@/modules/ferry-planning/templates/actions";
import TemplatesClient from "./TemplatesClient";
import { createAuthClient } from "@/infra/supabase/server-auth";
import { notFound, redirect } from "next/navigation";
import { getUserContext } from "@/core/context/getUserContext";
import { getTenantContext } from "@/core/context/getTenantContext";
import { SupabaseTenantRepository } from "@/infra/repositories/SupabaseTenantRepository";

interface PageProps {
    params: Promise<{
        tenantSlug: string;
    }>;
}

export default async function TemplatesPage({ params }: PageProps) {
    const supabase = createAuthClient();
    const { data: { user } } = await supabase.auth.getUser();

    if (!user) redirect("/login");

    const { tenantSlug } = await params;

    const tenantRepo = new SupabaseTenantRepository();
    const tenant = await tenantRepo.resolveTenantForUser(user.id, tenantSlug);

    if (!tenant) notFound();

    const [tenantContext, userContext] = await Promise.all([
        getTenantContext(tenant.id, tenant.slug),
        getUserContext(user.id, tenant.id)
    ]);

    if (!tenantContext || !userContext) redirect('/login');

    // Strict Permissions Check
    if (!userContext.permissions.includes('planning.view') && !userContext.permissions.includes('*')) {
        redirect('/admin/unauthorized');
    }

    let templates: any[] = [];
    try {
        templates = await listTemplatesAction(tenantSlug);
    } catch (e) {
        console.error("Failed to fetch templates", e);
    }

    return <TemplatesClient tenantSlug={tenantSlug} templates={templates} />;
}


'use client';

import { useState, useTransition } from 'react';
import { createTemplateAction, updateTemplateAction, deleteTemplateAction } from '@/modules/ferry-planning/templates/actions';

type ScheduleTemplate = {
    id: string;
    tenantId: string;
    name: string;
    description?: string;
    startDate: string;
    endDate: string;
    isActive: boolean;
    createdAt: string;
    updatedAt: string;
};

export default function TemplatesClient({
    tenantSlug,
    templates
}: {
    tenantSlug: string;
    templates: ScheduleTemplate[];
}) {
    const [isPending, startTransition] = useTransition();
    const [showCreate, setShowCreate] = useState(false);
    const [editingTemplate, setEditingTemplate] = useState<ScheduleTemplate | null>(null);

    const handleDelete = async (templateId: string) => {
        if (confirm('Are you sure you want to delete this template?')) {
            startTransition(async () => {
                await deleteTemplateAction(tenantSlug, templateId);
            });
        }
    };

    return (
        <div className="p-6">
            <div className="flex justify-between items-center mb-6">
                <h1 className="text-2xl font-bold">Schedule Templates</h1>
                <button
                    onClick={() => setShowCreate(true)}
                    className="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700 transition-colors shadow-sm font-medium"
                >
                    + Add Template
                </button>
            </div>

            <div className="bg-white rounded-lg shadow border border-gray-200 overflow-hidden">
                <table className="w-full">
                    <thead className="bg-gray-50 border-b border-gray-200">
                        <tr>
                            <th className="p-4 text-left font-semibold text-gray-600 text-sm">Name</th>
                            <th className="p-4 text-left font-semibold text-gray-600 text-sm">Dates</th>
                            <th className="p-4 text-left font-semibold text-gray-600 text-sm">Status</th>
                            <th className="p-4 text-right font-semibold text-gray-600 text-sm">Actions</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100">
                        {templates.length === 0 && (
                            <tr>
                                <td colSpan={4} className="p-8 text-center text-gray-500">
                                    No templates found.
                                </td>
                            </tr>
                        )}
                        {templates.map((t) => (
                            <tr key={t.id} className="hover:bg-gray-50 transition-colors">
                                <td className="p-4 font-medium text-gray-900">
                                    <div>{t.name}</div>
                                    {t.description && <div className="text-xs text-gray-500">{t.description}</div>}
                                </td>
                                <td className="p-4 text-sm text-gray-600">
                                    {new Date(t.startDate).toLocaleDateString()} - {new Date(t.endDate).toLocaleDateString()}
                                </td>
                                <td className="p-4">
                                    {t.isActive ? (
                                        <span className="inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-green-100 text-green-800">
                                            Active
                                        </span>
                                    ) : (
                                        <span className="inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-gray-100 text-gray-800">
                                            Draft
                                        </span>
                                    )}
                                </td>
                                <td className="p-4 text-right">
                                    <div className="flex justify-end gap-2">
                                        <button
                                            onClick={() => setEditingTemplate(t)}
                                            className="px-3 py-1.5 text-xs font-medium text-blue-600 border border-blue-200 rounded hover:bg-blue-50"
                                        >
                                            Edit
                                        </button>
                                        <button
                                            onClick={() => handleDelete(t.id)}
                                            disabled={isPending}
                                            className="px-3 py-1.5 text-xs font-medium text-red-600 border border-red-200 rounded hover:bg-red-50 disabled:opacity-50"
                                        >
                                            Delete
                                        </button>
                                    </div>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>

            <div className="mt-4 text-xs text-gray-400">
                Tenant: {tenantSlug}
            </div>

            {/* Create/Edit Modal */}
            {(showCreate || editingTemplate) && (
                <TemplateModal
                    tenantSlug={tenantSlug}
                    template={editingTemplate}
                    onClose={() => {
