'use client';

import React, { useRef, useState, useEffect } from 'react';
import { GanttRow, GanttTask } from "@/modules/ferry-planning/domain/ports";
import Link from 'next/link';

interface GanttClientProps {
    tenantSlug: string;
    initialRows: GanttRow[];
    startDate: string;
    endDate: string;
}

export default function GanttClient({ tenantSlug, initialRows, startDate, endDate }: GanttClientProps) {
    // State for viewing range - strictly controlled for now to the passed range, 
    // but we can add navigation later.
    const containerRef = useRef<HTMLDivElement>(null);
    const [currentTime] = useState(new Date().getTime());

    // Visualization Config
    const HOUR_WIDTH = 40; // px per hour
    const ROW_HEIGHT = 48; // px
    const HEADER_HEIGHT = 40; // px
    const SIDEBAR_WIDTH = 200; // px

    const start = new Date(startDate).getTime();
    const end = new Date(endDate).getTime();
    const totalHours = (end - start) / (1000 * 60 * 60);
    const totalWidth = totalHours * HOUR_WIDTH;

    // Generate Time Markers
    const timeMarkers: Date[] = [];
    let currentMarker = new Date(start);
    // Align to nearest hour
    currentMarker.setMinutes(0, 0, 0);

    while (currentMarker.getTime() < end) {
        timeMarkers.push(new Date(currentMarker));
        currentMarker.setHours(currentMarker.getHours() + 1);
    }

    // Helper: Position Task
    const getTaskStyle = (task: GanttTask) => {
        const taskStart = new Date(task.startTime).getTime();
        const taskEnd = new Date(task.endTime).getTime();

        const offsetHours = (taskStart - start) / (1000 * 60 * 60);
        const durationHours = (taskEnd - taskStart) / (1000 * 60 * 60);

        const left = offsetHours * HOUR_WIDTH;
        const width = Math.max(durationHours * HOUR_WIDTH, 2); // Min 2px

        // Color based on status
        let bgColor = 'bg-blue-500';
        if (task.status === 'cancelled') bgColor = 'bg-red-500';
        if (task.status === 'completed') bgColor = 'bg-green-500';
        if (task.status === 'delayed') bgColor = 'bg-yellow-500';

        return {
            left: `${left}px`,
            width: `${width}px`,
            className: `absolute top-1 bottom-1 rounded ${bgColor} text-white text-xs flex items-center px-1 overflow-hidden whitespace-nowrap z-10 hover:brightness-110 shadow-sm cursor-pointer transition-all`
        };
    };

    // Calculate Current Time Line Position
    const nowOffsetHours = (currentTime - start) / (1000 * 60 * 60);
    const nowLeft = nowOffsetHours * HOUR_WIDTH;

    return (
        <div className="flex flex-col h-[calc(100vh-200px)] border rounded-lg bg-white overflow-hidden shadow-sm">
            {/* Toolbar */}
            <div className="p-4 border-b flex justify-between items-center bg-gray-50">
                <div className="flex items-center gap-4">
                    <h2 className="font-semibold text-lg">Timeline</h2>
                    <div className="text-sm text-gray-500">
                        {new Date(startDate).toLocaleDateString()} - {new Date(endDate).toLocaleDateString()}
                    </div>
                </div>
                <div className="flex gap-2">
                    <button className="px-3 py-1 bg-white border rounded hover:bg-gray-50 text-sm" onClick={() => alert("Navigation implementation pending")}>
                        Today
                    </button>
                    <div className="flex border rounded overflow-hidden">
                        <button className="px-3 py-1 bg-white hover:bg-gray-50 text-sm border-r" onClick={() => alert("Prev implementation pending")}>&lt;</button>
                        <button className="px-3 py-1 bg-white hover:bg-gray-50 text-sm" onClick={() => alert("Next implementation pending")}>&gt;</button>
                    </div>
                </div>
            </div>

            {/* Gantt Area */}
            <div className="flex flex-1 overflow-hidden relative">
                {/* Sidebar (Resources) */}
                <div className="w-[200px] border-r bg-white flex-shrink-0 z-20 shadow-[4px_0_12px_-4px_rgba(0,0,0,0.1)]">
                    <div className="h-[40px] border-b bg-gray-100 font-medium text-xs text-gray-500 flex items-center px-4 uppercase tracking-wider">
                        Vessel
                    </div>
                    <div className="overflow-y-hidden">
                        {initialRows.map(row => (
                            <div key={row.resourceId} className="h-[48px] border-b flex items-center px-4 font-medium text-sm text-gray-700 truncate hover:bg-gray-50">
                                {row.resourceName}
                            </div>
                        ))}
                    </div>
                </div>

                {/* Timeline Scroll Area */}
                <div className="flex-1 overflow-auto relative" ref={containerRef}>
                    <div style={{ width: `${totalWidth}px`, minWidth: '100%' }} className="relative">
                        {/* Header (Time Scale) */}
                        <div className="h-[40px] border-b bg-gray-50 flex sticky top-0 z-10">
                            {timeMarkers.map((date, i) => (
                                <div
                                    key={i}
                                    style={{ width: `${HOUR_WIDTH}px` }}
                                    className={`flex-shrink-0 border-r text-[10px] text-gray-400 flex items-end pb-1 pl-1 ${date.getHours() === 0 ? 'bg-gray-100 font-bold text-gray-600 border-r-gray-300' : ''}`}
                                >
                                    {date.getHours() === 0 ? date.toLocaleDateString(undefined, { day: 'numeric', month: 'short' }) : date.getHours()}
                                </div>
                            ))}
                        </div>

                        {/* Current Time Line */}
                        {nowLeft > 0 && nowLeft < totalWidth && (
                            <div
                                style={{ left: `${nowLeft}px` }}
                                className="absolute top-[40px] bottom-0 w-[2px] bg-red-500 z-0 pointer-events-none"
                            >
                                <div className="absolute -top-[5px] -left-[4px] w-[10px] h-[10px] rounded-full bg-red-500"></div>
                            </div>
                        )}

                        {/* Rows */}
                        <div className="relative">
                            {initialRows.map(row => (
                                <div key={row.resourceId} className="h-[48px] border-b relative hover:bg-gray-50/50 transition-colors">
                                    {/* Grid Lines (Vertical) */}
                                    {timeMarkers.map((date, i) => (
                                        <div
                                            key={i}
                                            style={{ left: `${i * HOUR_WIDTH}px`, width: `${HOUR_WIDTH}px` }}
                                            className={`absolute top-0 bottom-0 border-r border-gray-100 ${date.getHours() === 0 ? 'border-r-gray-200 bg-gray-50/30' : ''}`}
                                        ></div>
                                    ))}

                                    {/* Tasks */}
                                    {row.tasks.map(task => {
                                        const styleProps = getTaskStyle(task);
                                        return (
                                            <Link
                                                key={task.id}
                                                href={`/admin/t/${tenantSlug}/apps/ferry-booking/trips/${task.id}`}
                                                className={styleProps.className}
                                                style={{ left: styleProps.left, width: styleProps.width }}
                                                title={`${task.label} (${new Date(task.startTime).toLocaleTimeString()} - ${new Date(task.endTime).toLocaleTimeString()})`}
                                            >
                                                <span className="truncate px-1">{task.label}</span>
                                            </Link>
                                        );
                                    })}
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            </div>
            <div className="p-2 border-t bg-gray-50 text-xs text-gray-500 flex justify-between">
                <div>Shift+Scroll to pan horizontally</div>
                <div className="flex gap-4">
                    <span className="flex items-center gap-1"><span className="w-2 h-2 rounded bg-blue-500"></span> Scheduled</span>
                    <span className="flex items-center gap-1"><span className="w-2 h-2 rounded bg-green-500"></span> Completed</span>
                    <span className="flex items-center gap-1"><span className="w-2 h-2 rounded bg-yellow-500"></span> Delayed</span>
                    <span className="flex items-center gap-1"><span className="w-2 h-2 rounded bg-red-500"></span> Cancelled</span>
                </div>
            </div>
        </div>
    );
}


import { createAuthClient } from "@/infra/supabase/server-auth";
import { SupabaseTenantRepository } from "@/infra/repositories/SupabaseTenantRepository";
import { SupabaseGanttService } from "@/modules/ferry-planning/infrastructure/SupabaseGanttService";
import { notFound, redirect } from "next/navigation";
import { getUserContext } from "@/core/context/getUserContext";
import { getTenantContext } from "@/core/context/getTenantContext";
import GanttClient from "./GanttClient";

interface PageProps {
    params: Promise<{
        tenantSlug: string;
    }>;
}

export default async function GanttPage({ params }: PageProps) {
    const supabase = createAuthClient();
    const { data: { user } } = await supabase.auth.getUser();

    if (!user) redirect("/login");

    const { tenantSlug } = await params;
    const tenantRepo = new SupabaseTenantRepository();
    const tenant = await tenantRepo.resolveTenantForUser(user.id, tenantSlug);

    if (!tenant) notFound();

    // Context & RBAC
    const [tenantContext, userContext] = await Promise.all([
        getTenantContext(tenant.id, tenant.slug),
        getUserContext(user.id, tenant.id)
    ]);

    if (!tenantContext || !userContext) redirect('/login');

    if (userContext.permissions && !userContext.permissions.includes('planning.view') && !userContext.permissions.includes('*')) {
        redirect('/admin/unauthorized');
    }

    // Fetch Gantt Data (Next 7 days by default)
    const startDate = new Date();
    startDate.setHours(0, 0, 0, 0); // Start of today

    const endDate = new Date(startDate);
    endDate.setDate(endDate.getDate() + 7); // +7 Days

    const ganttService = new SupabaseGanttService();
    const rows = await ganttService.getGanttData(tenant.id, startDate.toISOString(), endDate.toISOString());

    return (
        <div className="p-6 h-full flex flex-col">
            <h1 className="text-2xl font-bold mb-4">Trips Gantt Chart</h1>
            <div className="flex-1">
                <GanttClient
                    tenantSlug={tenantSlug}
                    initialRows={rows}
                    startDate={startDate.toISOString()}
                    endDate={endDate.toISOString()}
                />
            </div>
        </div>
    );
}

import { listProfilesAction } from "@/modules/ferry-pricing/profiles/actions";
import PricingProfilesClient from "./PricingProfilesClient";
import { createAuthClient } from "@/infra/supabase/server-auth";
import { notFound, redirect } from "next/navigation";
import { getUserContext } from "@/core/context/getUserContext";
import { getTenantContext } from "@/core/context/getTenantContext";
import { SupabaseTenantRepository } from "@/infra/repositories/SupabaseTenantRepository";

interface PageProps {
    params: Promise<{
        tenantSlug: string;
    }>;
}

export default async function PricingProfilesPage({ params }: PageProps) {
    const supabase = createAuthClient();
    const { data: { user } } = await supabase.auth.getUser();

    if (!user) redirect("/login");

    const { tenantSlug } = await params;
    const tenantRepo = new SupabaseTenantRepository();
    const tenant = await tenantRepo.resolveTenantForUser(user.id, tenantSlug);

    if (!tenant) notFound();

    // Context & RBAC
    const [tenantContext, userContext] = await Promise.all([
        getTenantContext(tenant.id, tenant.slug),
        getUserContext(user.id, tenant.id)
    ]);

    if (!tenantContext || !userContext) redirect('/login');

    if (!userContext.permissions.includes('pricing.view') && !userContext.permissions.includes('*')) {
