'use client';

import { useState, useTransition } from 'react';
import { createProfileAction, updateProfileAction, deleteProfileAction } from '@/modules/ferry-pricing/profiles/actions';

type PriceProfile = {
    id: string;
    tenantId: string;
    name: string;
    description?: string;
    basePriceAdult: number;
    basePriceChild: number;
    basePriceVehicle: number;
    basePriceBike: number;
    currency: string;
    isActive: boolean;
    createdAt: string;
    updatedAt: string;
};

export default function PricingProfilesClient({
    tenantSlug,
    profiles
}: {
    tenantSlug: string;
    profiles: PriceProfile[];
}) {
    const [isPending, startTransition] = useTransition();
    const [showCreate, setShowCreate] = useState(false);
    const [editingProfile, setEditingProfile] = useState<PriceProfile | null>(null);

    const handleDelete = async (profileId: string) => {
        if (confirm('Are you sure you want to delete this profile?')) {
            startTransition(async () => {
                await deleteProfileAction(tenantSlug, profileId);
            });
        }
    };

    return (
        <div className="p-6">
            <div className="flex justify-between items-center mb-6">
                <div>
                    <h1 className="text-2xl font-bold">Price Profiles</h1>
                    <p className="text-gray-500">Manage base prices for different seasons or routes.</p>
                </div>
                <button
                    onClick={() => setShowCreate(true)}
                    className="bg-blue-600 text-white px-4 py-2 rounded shadow hover:bg-blue-700 transition-colors"
                >
                    + New Profile
                </button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {profiles.map(p => (
                    <div key={p.id} className="bg-white rounded shadow p-6 border-t-4 border-blue-500 relative group">
                        <div className="flex justify-between items-start mb-4">
                            <h3 className="font-bold text-lg text-gray-900">{p.name}</h3>
                            {p.isActive ? (
                                <span className="text-green-600 text-xs bg-green-100 px-2 py-1 rounded font-medium">Active</span>
                            ) : (
                                <span className="text-gray-400 text-xs bg-gray-100 px-2 py-1 rounded font-medium">Draft</span>
                            )}
                        </div>
                        <p className="text-gray-500 text-sm mb-4 h-10 overflow-hidden text-ellipsis">{p.description || "No description."}</p>

                        <div className="space-y-2 mb-6">
                            <div className="flex justify-between text-sm border-b border-gray-50 pb-1">
                                <span className="text-gray-600">Adult</span>
                                <span className="font-mono font-medium">{p.currency} {p.basePriceAdult.toFixed(2)}</span>
                            </div>
                            <div className="flex justify-between text-sm border-b border-gray-50 pb-1">
                                <span className="text-gray-600">Child</span>
                                <span className="font-mono font-medium">{p.currency} {p.basePriceChild.toFixed(2)}</span>
                            </div>
                            <div className="flex justify-between text-sm border-b border-gray-50 pb-1">
                                <span className="text-gray-600">Vehicle</span>
                                <span className="font-mono font-medium">{p.currency} {p.basePriceVehicle.toFixed(2)}</span>
                            </div>
                            <div className="flex justify-between text-sm border-b border-gray-50 pb-1">
                                <span className="text-gray-600">Bike</span>
                                <span className="font-mono font-medium">{p.currency} {p.basePriceBike.toFixed(2)}</span>
                            </div>
                        </div>

                        <div className="flex justify-end items-center gap-3 pt-4 border-t border-gray-100">
                            <button
                                onClick={() => handleDelete(p.id)}
                                disabled={isPending}
                                className="text-red-500 hover:text-red-700 text-sm font-medium disabled:opacity-50"
                            >
                                Delete
                            </button>
                            <button
                                onClick={() => setEditingProfile(p)}
                                className="text-blue-600 hover:underline text-sm font-medium"
                            >
                                Edit Profile
                            </button>
                        </div>
                    </div>
                ))}

                {/* Empty State / Add New Card */}
                <button
                    onClick={() => setShowCreate(true)}
                    className="border-2 border-dashed border-gray-300 rounded p-6 flex flex-col items-center justify-center text-gray-400 hover:border-blue-500 hover:text-blue-500 transition-colors h-full min-h-[300px]"
                >
                    <span className="text-4xl mb-2">+</span>
                    <span className="font-medium">Create New Profile</span>
                </button>
            </div>

            {/* Create/Edit Modal */}
            {(showCreate || editingProfile) && (
                <ProfileModal
                    tenantSlug={tenantSlug}
                    profile={editingProfile}
                    onClose={() => {
                        setShowCreate(false);
                        setEditingProfile(null);
                    }}
                />
            )}
        </div>
    );
}

function ProfileModal({
    tenantSlug,
