                                    step="0.01"
                                    defaultValue={profile?.basePriceChild}
                                    className="w-full border p-2 rounded focus:ring-2 focus:ring-blue-500 outline-none"
                                    placeholder="0.00"
                                />
                            </div>
                            <div>
                                <label className="block text-xs font-medium text-gray-500 mb-1 uppercase">Vehicle Fare</label>
                                <input
                                    name="basePriceVehicle"
                                    type="number"
                                    step="0.01"
                                    defaultValue={profile?.basePriceVehicle}
                                    className="w-full border p-2 rounded focus:ring-2 focus:ring-blue-500 outline-none"
                                    placeholder="0.00"
