import { createAuthClient } from "@/infra/supabase/server-auth";
import { SupabaseTenantRepository } from "@/infra/repositories/SupabaseTenantRepository";
import { SupabaseFerryRouteRepository } from "@/modules/ferry-booking/infrastructure/SupabaseFerryRouteRepository";
import { SupabasePricingRepository } from "@/modules/ferry-pricing/infrastructure/SupabasePricingRepository";
import { notFound, redirect } from "next/navigation";
import { getUserContext } from "@/core/context/getUserContext";
import { getTenantContext } from "@/core/context/getTenantContext";
import { RoutePricingTable } from "./RoutePricingTable";

interface PageProps {
    params: Promise<{ tenantSlug: string }>;
    searchParams: Promise<{ routeId?: string }>;
}

export default async function PricingRoutingPage({ params, searchParams }: PageProps) {
    const supabase = createAuthClient();
    const { data: { user } } = await supabase.auth.getUser();

    if (!user) redirect("/login");

    const { tenantSlug } = await params;
    const tenantRepo = new SupabaseTenantRepository();
    const tenant = await tenantRepo.resolveTenantForUser(user.id, tenantSlug);

    if (!tenant) notFound();

    // Context & RBAC
    const [tenantContext, userContext] = await Promise.all([
        getTenantContext(tenant.id, tenant.slug),
        getUserContext(user.id, tenant.id)
    ]);

    if (!tenantContext || !userContext) redirect('/login');

    // Fetch Routes and Profiles
    const routeRepo = new SupabaseFerryRouteRepository();
    const pricingRepo = new SupabasePricingRepository();

    const [routes, profiles] = await Promise.all([
        routeRepo.findAll(tenant.id),
        pricingRepo.findAllProfiles(tenant.id)
    ]);

    return (
        <div className="p-6">
            <h1 className="text-2xl font-bold mb-4">Route Pricing</h1>
            <p className="text-gray-500 mb-6 font-light">Assign base pricing profiles to your ferry routes.</p>

            <RoutePricingTable
                tenantId={tenant.id}
                routes={routes}
                profiles={profiles}
            />
        </div>
    );
}


'use client'

import React, { useState } from 'react';
import { FerryRoute } from "@/modules/ferry-booking/domain/types";
import { PriceProfile } from "@/modules/ferry-pricing/domain/types";
import { updateRoutePricing } from "@/modules/ferry-pricing/routes/actions";

interface Props {
    tenantId: string;
    routes: FerryRoute[];
    profiles: PriceProfile[];
}

export function RoutePricingTable({ tenantId, routes, profiles }: Props) {
    const [updating, setUpdating] = useState<string | null>(null);

    const handleProfileChange = async (routeId: string, profileId: string) => {
        setUpdating(routeId);
        try {
            await updateRoutePricing(tenantId, routeId, profileId === 'default' ? null : profileId);
        } catch (e) {
            alert("Failed to update pricing profile");
        } finally {
            setUpdating(null);
        }
    };

    return (
        <div className="bg-white rounded shadow overflow-hidden">
            <table className="w-full text-left border-collapse">
                <thead className="bg-gray-50 border-b">
                    <tr>
                        <th className="p-4 font-medium text-gray-500">Route</th>
                        <th className="p-4 font-medium text-gray-500">Origin</th>
                        <th className="p-4 font-medium text-gray-500">Destination</th>
                        <th className="p-4 font-medium text-gray-500">Duration</th>
                        <th className="p-4 font-medium text-gray-500">Default Price Profile</th>
                    </tr>
                </thead>
                <tbody className="divide-y divide-gray-100">
                    {routes.map(route => (
                        <tr key={route.id} className="hover:bg-gray-50">
                            <td className="p-4 font-medium">
                                {route.origin?.name} → {route.destination?.name}
                            </td>
                            <td className="p-4 text-gray-600">{route.origin?.name}</td>
                            <td className="p-4 text-gray-600">{route.destination?.name}</td>
                            <td className="p-4 text-gray-600">{route.estimatedDurationMinutes} min</td>
                            <td className="p-4">
                                <select
                                    className="border rounded px-3 py-2 w-full max-w-xs focus:ring-2 focus:ring-blue-500 bg-white"
                                    value={route.defaultPriceProfileId || 'default'}
                                    onChange={(e) => handleProfileChange(route.id, e.target.value)}
                                    disabled={updating === route.id}
                                >
                                    <option value="default">-- Select Profile --</option>
                                    {profiles.map(p => (
                                        <option key={p.id} value={p.id}>
                                            {p.name} ({p.currency})
                                        </option>
                                    ))}
                                </select>
                                {updating === route.id && <span className="ml-2 text-xs text-blue-500">Saving...</span>}
                            </td>
                        </tr>
                    ))}
                    {routes.length === 0 && (
                        <tr>
                            <td colSpan={5} className="p-8 text-center text-gray-500">
                                No routes found. Please define routes in Fleet Management first.
                            </td>
                        </tr>
                    )}
                </tbody>
            </table>
        </div>
    );
}

