    try {
        const supabase = await createClient()
        const { error } = await supabase
            .from("business_partners")
            .delete()
            .eq("id", id)

        if (error) throw error

        revalidatePath("/admin/partners")
        return { success: true }
    } catch (e: any) {
        return { success: false, error: e.message }
    }
}

import { createClient } from "@/utils/supabase/server"
import { PartnersContent } from "@/components/admin/partners/partners-content"

export default async function PartnersPage({ searchParams: searchParamsPromise }: { searchParams: Promise<{ type?: string }> }) {
    const searchParams = await searchParamsPromise
    const activeFilter = searchParams.type || "SELLER"
    const supabase = await createClient()

    let partners: any[] = []
    let errorMsg = null

    try {
        let query = supabase.from("business_partners").select("*")

        if (activeFilter === "SELLER") {
            // Strict filter: Type must be SELLER or BOTH
            query = query.in("type", ["SELLER", "BOTH"])
        } else if (activeFilter === "BUYER") {
            query = query.in("type", ["BUYER", "BOTH"])
        }
        // If ALL, no filter applied

        const { data, error } = await query.order("name")
        if (error) throw error
        partners = data || []
    } catch (e: any) {
        console.error("Partners Page Error:", e)
        errorMsg = "Failed to load partners. Please try again."
    }

    return (
        <PartnersContent partners={partners} activeFilter={activeFilter} errorMsg={errorMsg} />
    )
}

