'use server'

import { createClient } from "@/utils/supabase/server"
import { createServiceClient } from "@/utils/supabase/service"
import { revalidatePath } from "next/cache"
import { getSiteUrl } from "@/modules/profile/actions"
import { sendEmail } from "@/utils/email-service"

export async function getUsers() {
    const supabase = await createClient()
    const { data: profiles } = await supabase
        .from('auth_profiles')
        .select('*, auth_roles(name)')

    // Get current user's Root status for UI purposes
    const { data: { user } } = await supabase.auth.getUser()
    let currentUserIsRoot = false
    if (user) {
        const { data: currentProfile } = await supabase
            .from('auth_profiles')
            .select('is_superadmin')
            .eq('id', user.id)
            .single()
        currentUserIsRoot = currentProfile?.is_superadmin || false
    }

    return { users: profiles || [], currentUserIsRoot }
}

export async function createUser(data: {
    email: string,
    login: string,
    firstName: string,
    lastName: string,
    phone: string,
    roleId: string | null,
    isSuperadmin: boolean
}) {
    const serviceClient = createServiceClient()
    if (!serviceClient) throw new Error("Failed to initialize service client")

    // [SECURITY] Root Privilege Protection
    if (data.isSuperadmin) {
        const adminSupabase = await createClient()
        const { data: { user: currentUser } } = await adminSupabase.auth.getUser()
        if (!currentUser) throw new Error("Brak autoryzacji")

        const { data: callerProfile } = await serviceClient
            .from('auth_profiles')
            .select('is_superadmin')
            .eq('id', currentUser.id)
            .single()

        if (!callerProfile?.is_superadmin) {
            throw new Error("Tylko Root może nadawać uprawnienia Root (Bypass).")
        }
    }

    // [SECURITY] Generate Invitation Link
    const siteUrl = await getSiteUrl()
    const { data: inviteData, error: authError } = await serviceClient.auth.admin.generateLink({
        type: 'invite',
        email: data.email,
        options: {
            redirectTo: `${siteUrl}/admin/auth/update?type=password`
        }
    })

    if (authError || !inviteData.user) throw new Error(authError?.message || "Błąd generowania zaproszenia")

    // Create Profile with is_active: false (unless superadmin, but even then better hold)
    const { error: profileError } = await serviceClient
        .from('auth_profiles')
        .insert({
            id: inviteData.user.id,
            role_id: data.roleId || null,
            is_superadmin: data.isSuperadmin,
            first_name: data.firstName,
            last_name: data.lastName,
            login: data.login,
            phone: data.phone,
            email: data.email,
            is_active: false // [SECURITY] Inactive by default
        })

    if (profileError) throw new Error(profileError.message)

    // Send Custom Onboarding Email
    const setupLink = inviteData.properties?.action_link
    await sendEmail({
        to: data.email,
        subject: 'Witaj w Zalew Portal - Twoje dane dostępowe',
        text: `
Cześć ${data.firstName} ${data.lastName},

Zostałeś dodany jako administrator do portalu Zalew. 
Twój login to: ${data.login}

Twoje konto jest obecnie nieaktywne. Aby je aktywować i ustawić swoje pierwsze hasło, kliknij w poniższy link:
${setupLink}

Ważne informacje:
1. Podczas pierwszego logowania zostaniesz poproszony o kod weryfikacyjny wysłany na ten adres email (weryfikacja nowego urządzenia).
2. Twoje hasło musi mieć minimum 12 znaków i spełniać wymogi bezpieczeństwa.

Witamy w zespole!

---
Ferry Portal
        `.trim()
    })

    revalidatePath('/admin/users')
}

export async function updateUser(id: string, data: {
    email: string,
    firstName: string,
    lastName: string,
    phone: string,
    roleId: string | null,
    isSuperadmin: boolean
}) {
    const serviceClient = createServiceClient()
    if (!serviceClient) throw new Error("Service client error")

    // [SECURITY] Root Privilege Protection
    if (data.isSuperadmin) {
        const adminSupabase = await createClient()
        const { data: { user: currentUser } } = await adminSupabase.auth.getUser()
        if (!currentUser) throw new Error("Brak autoryzacji")

        const { data: callerProfile } = await serviceClient
            .from('auth_profiles')
            .select('is_superadmin')
            .eq('id', currentUser.id)
            .single()

        if (!callerProfile?.is_superadmin) {
            // Check if they are trying to SET it to true, or just keeping it true?
            // Usually, only Roots should even be able to save a Root profile if they are changing it.
            // But if they are just editing a user, we must ensure they don't TURN IT ON.
            const { data: targetProfile } = await serviceClient
                .from('auth_profiles')
                .select('is_superadmin')
                .eq('id', id)
                .single()

            if (data.isSuperadmin && !targetProfile?.is_superadmin) {
                throw new Error("Tylko Root może nadawać uprawnienia Root (Bypass).")
            }
        }
    }

    // 1. Get current profile to check if email changed
    const { data: currentProfile } = await serviceClient
        .from('auth_profiles')
        .select('email')
        .eq('id', id)
        .single()

    const emailChanged = currentProfile && currentProfile.email !== data.email

    // 2. Update Auth User if email changed
    if (emailChanged) {
        const { error: authError } = await serviceClient.auth.admin.updateUserById(id, {
            email: data.email,
            email_confirm: true // Force confirm since admin did it manually
        })
        if (authError) throw new Error(`Błąd aktualizacji e-mail w Auth: ${authError.message}`)
    }

    // 3. Update Profile
    const { error } = await serviceClient
        .from('auth_profiles')
        .update({
            email: data.email,
            first_name: data.firstName,
            last_name: data.lastName,
            phone: data.phone,
            role_id: data.roleId,
            is_superadmin: data.isSuperadmin
        })
        .eq('id', id)

    if (error) throw new Error(error.message)

    // 4. Send Notification if email changed
    if (emailChanged) {
        await sendEmail({
            to: data.email,
            subject: 'Twoje dane logowania zostały zaktualizowane - Zalew Portal',
            text: `
Witaj ${data.firstName} ${data.lastName},

Twój adres e-mail do logowania w portalu Zalew został zmieniony przez administratora na: ${data.email}

Od teraz prosimy używać nowego adresu e-mail lub swojego loginu do wchodzenia do systemu.
Wszystkie Twoje uprawnienia pozostają bez zmian.

---
Ferry Portal
            `.trim()
        })
    }

    revalidatePath('/admin/users')
}

export async function deleteUser(id: string) {
    const serviceClient = createServiceClient()
    if (!serviceClient) throw new Error("Failed to initialize service client")

    // 1. Fetch user data before deletion for notification
    const { data: profile } = await serviceClient
        .from('auth_profiles')
        .select('email, first_name, last_name')
        .eq('id', id)
        .single()

    // 2. Send farewell email
    if (profile?.email) {
        await sendEmail({
            to: profile.email,
            subject: 'Twoje konto zostało usunięte - Zalew Portal',
            text: `
Witaj ${profile.first_name || ''} ${profile.last_name || ''},

Twoje konto administratora w portalu Zalew zostało usunięte przez głównego administratora. 
Twój dostęp do systemu został wygaszony.

Dziękujemy za dotychczasową współpracę.

---
Ferry Portal
            `.trim()
        })
    }

    // 3. Delete Auth user (deletes profile via CASCADE)
    const { error } = await serviceClient.auth.admin.deleteUser(id)
    if (error) throw new Error(error.message)

    revalidatePath('/admin/users')
}
async function wipeUserSessionsAndDevices(id: string) {
    const serviceClient = createServiceClient()
    if (!serviceClient) throw new Error("Service client error")

    // 1. Sign out from all sessions
    await serviceClient.auth.admin.signOut(id)

    // 2. Clear trusted devices
    await serviceClient
        .from('auth_trusted_devices')
        .delete()
        .eq('user_id', id)
}

export async function lockUser(id: string) {
    const serviceClient = createServiceClient()
    if (!serviceClient) throw new Error("Service client error")

    // 1. Mark as inactive and locked
    const { error } = await serviceClient
        .from('auth_profiles')
        .update({
            is_active: false,
            locked_at: new Date().toISOString()
        })
        .eq('id', id)

    if (error) throw new Error(error.message)

    // 2. Enforcement
    await wipeUserSessionsAndDevices(id)

    revalidatePath('/admin/users')
}

export async function resetUserPassword(id: string, email: string, firstName: string, lastName: string) {
    const serviceClient = createServiceClient()
    if (!serviceClient) throw new Error("Service client error")

    // 1. Proactive security wipe
    await wipeUserSessionsAndDevices(id)

    // 2. Generate Reset Link (force set new password) - uses recovery flow
    const siteUrl = await getSiteUrl()
    const { data: inviteData, error: authError } = await serviceClient.auth.admin.generateLink({
        type: 'recovery',
        email: email,
        options: {
            redirectTo: `${siteUrl}/admin/auth/update?type=password`
        }
    })

    if (authError || !inviteData?.properties?.action_link) {
        throw new Error("Nie udało się wygenerować linku do resetu hasła.")
    }

    // 3. Send Email
    await sendEmail({
        to: email,
        subject: 'Reset hasła - Zalew Portal',
        text: `
Witaj ${firstName} ${lastName},

Została wygenerowana prośba o reset Twojego hasła do portalu Zalew. 
Wszystkie Twoje aktywne sesje zostały zakończone ze względów bezpieczeństwa.

Aby ustawić nowe hasło, kliknij w poniższy link:
${inviteData.properties.action_link}

Jeśli to nie Ty prosiłeś o reset, skontaktuj się z administratorem.

---
Ferry Portal
        `.trim()
    })

    return { success: true }
}

export async function unlockUser(id: string, email: string, firstName: string, lastName: string) {
    const serviceClient = createServiceClient()
    if (!serviceClient) throw new Error("Service client error")

    // 1. Reset lockout state and activate
    const { error: profileError } = await serviceClient
        .from('auth_profiles')
        .update({
            failed_attempts: 0,
            locked_at: null,
            is_active: true
        })
        .eq('id', id)

    if (profileError) throw new Error(profileError.message)

    // 2. Proactive security wipe (ensure they start fresh on current device too)
    await wipeUserSessionsAndDevices(id)

    // 3. Generate Reset Link (force set new password)
    const siteUrl = await getSiteUrl()
    const { data: inviteData, error: authError } = await serviceClient.auth.admin.generateLink({
        type: 'recovery',
        email: email,
        options: {
            redirectTo: `${siteUrl}/admin/auth/update?type=password`
        }
    })

    if (authError || !inviteData?.properties?.action_link) {
        throw new Error("Konto odblokowane, ale nie udało się wygenerować linku do resetu hasła.")
    }

    // 4. Send Email
    await sendEmail({
        to: email,
        subject: 'Twoje konto zostało odblokowane - Zalew Portal',
        text: `
Witaj ${firstName} ${lastName},

Twoje konto administratora zostało odblokowane przez innego administratora.
Ze względów bezpieczeństwa, wszystkie Twoje dotychczasowe sesje zostały zakończone.

Aby przywrócić dostęp i ustawić nowe hasło, kliknij w poniższy link:
${inviteData.properties.action_link}

Jeśli to nie Ty prosiłeś o odblokowanie, skontaktuj się niezwłocznie z głównym administratorem.

---
Ferry Portal
        `.trim()
    })

    revalidatePath('/admin/users')
    return { success: true }
}

