'use client';

import { useState, useTransition } from 'react';
import { createCustomerAction, updateCustomerAction, deleteCustomerAction } from '../actions';
import { Customer } from '@/modules/crm/domain/types';

export default function CustomersClient({
    tenantSlug,
    customers
}: {
    tenantSlug: string;
    customers: Customer[];
}) {
    const [isPending, startTransition] = useTransition();
    const [showCreate, setShowCreate] = useState(false);
    const [editingCustomer, setEditingCustomer] = useState<Customer | null>(null);

    const handleDelete = async (customerId: string) => {
        if (confirm('Are you sure you want to delete this customer?')) {
            startTransition(async () => {
                await deleteCustomerAction(tenantSlug, customerId);
            });
        }
    };

    return (
        <div className="p-6">
            <div className="flex justify-between items-center mb-6">
                <h1 className="text-2xl font-bold">Customers (B2C)</h1>
                <button
                    onClick={() => setShowCreate(true)}
                    className="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700 transition-colors shadow-sm font-medium"
                >
                    + Add Customer
                </button>
            </div>

            <div className="bg-white rounded-lg shadow border border-gray-200 overflow-hidden">
                <table className="w-full">
                    <thead className="bg-gray-50 border-b border-gray-200">
                        <tr>
                            <th className="p-4 text-left font-semibold text-gray-600 text-sm">Name</th>
                            <th className="p-4 text-left font-semibold text-gray-600 text-sm">Contact</th>
                            <th className="p-4 text-left font-semibold text-gray-600 text-sm">Source</th>
                            <th className="p-4 text-left font-semibold text-gray-600 text-sm">Status</th>
                            <th className="p-4 text-right font-semibold text-gray-600 text-sm">Actions</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100">
                        {customers.length === 0 && (
                            <tr>
                                <td colSpan={5} className="p-8 text-center text-gray-500">
                                    No customers found.
                                </td>
                            </tr>
                        )}
                        {customers.map((c) => (
                            <tr key={c.id} className="hover:bg-gray-50 transition-colors">
                                <td className="p-4 font-medium text-gray-900">
                                    {c.firstName} {c.lastName}
                                </td>
                                <td className="p-4 text-sm">
                                    <div className="text-gray-900">{c.email}</div>
                                    <div className="text-gray-500 font-mono text-xs">{c.phone || '-'}</div>
                                </td>
                                <td className="p-4 text-sm text-gray-600">
                                    {c.source || 'Manual'}
                                </td>
                                <td className="p-4">
                                    {c.isActive ? (
                                        <span className="inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-green-100 text-green-800">
                                            Active
                                        </span>
                                    ) : (
                                        <span className="inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-gray-100 text-gray-800">
                                            Inactive
                                        </span>
                                    )}
                                </td>
                                <td className="p-4 text-right">
                                    <div className="flex justify-end gap-2">
                                        <button
                                            onClick={() => setEditingCustomer(c)}
                                            className="px-3 py-1.5 text-xs font-medium text-blue-600 border border-blue-200 rounded hover:bg-blue-50"
                                        >
                                            Edit
                                        </button>
                                        <button
                                            onClick={() => handleDelete(c.id)}
                                            disabled={isPending}
                                            className="px-3 py-1.5 text-xs font-medium text-red-600 border border-red-200 rounded hover:bg-red-50 disabled:opacity-50"
                                        >
                                            Delete
                                        </button>
                                    </div>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>

            {(showCreate || editingCustomer) && (
                <CustomerModal
                    tenantSlug={tenantSlug}
                    customer={editingCustomer}
                    onClose={() => {
                        setShowCreate(false);
                        setEditingCustomer(null);
                    }}
                />
            )}
        </div>
    );
}

function CustomerModal({
    tenantSlug,
    customer,
    onClose
}: {
    tenantSlug: string;
    customer: Customer | null;
    onClose: () => void;
}) {
    const isEdit = !!customer;
    return (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center p-4 z-50">
            <div className="bg-white rounded-lg shadow-xl max-w-md w-full p-6">
                <h2 className="text-xl font-bold mb-4">{isEdit ? 'Edit Customer' : 'Add New Customer'}</h2>
                <form action={async (formData) => {
                    if (isEdit) {
                        await updateCustomerAction(tenantSlug, customer.id, formData);
                    } else {
                        await createCustomerAction(tenantSlug, formData);
                    }
                    onClose();
                }}>
                    <div className="grid grid-cols-2 gap-4 mb-4">
                        <div>
                            <label className="block text-sm font-medium mb-1">First Name</label>
                            <input
                                name="firstName"
                                defaultValue={customer?.firstName}
                                className="w-full border p-2 rounded focus:ring-2 focus:ring-blue-500 outline-none"
                                required
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium mb-1">Last Name</label>
                            <input
                                name="lastName"
                                defaultValue={customer?.lastName}
                                className="w-full border p-2 rounded focus:ring-2 focus:ring-blue-500 outline-none"
                                required
                            />
                        </div>
                    </div>

                    <div className="mb-4">
                        <label className="block text-sm font-medium mb-1">Email</label>
                        <input
                            name="email"
                            type="email"
                            defaultValue={customer?.email}
                            className="w-full border p-2 rounded focus:ring-2 focus:ring-blue-500 outline-none"
                            required
                        />
                    </div>

                    <div className="mb-4">
                        <label className="block text-sm font-medium mb-1">Phone</label>
                        <input
                            name="phone"
                            type="tel"
                            defaultValue={customer?.phone}
                            className="w-full border p-2 rounded focus:ring-2 focus:ring-blue-500 outline-none"
                        />
                    </div>

                    <div className="mb-4">
                        <label className="block text-sm font-medium mb-1">Source</label>
                        <select
                            name="source"
                            defaultValue={customer?.source || 'manual'}
                            className="w-full border p-2 rounded focus:ring-2 focus:ring-blue-500 outline-none"
                        >
                            <option value="manual">Manual Entry</option>
                            <option value="website">Website</option>
                            <option value="referral">Referral</option>
                            <option value="other">Other</option>
                        </select>
                    </div>

                    <div className="mb-4">
                        <label className="block text-sm font-medium mb-1">Notes</label>
                        <textarea
                            name="notes"
                            defaultValue={customer?.notes}
                            className="w-full border p-2 rounded focus:ring-2 focus:ring-blue-500 outline-none"
                            rows={3}
                        />
                    </div>

                    <div className="mb-6">
                        <label className="flex items-center gap-2 cursor-pointer">
                            <input
                                name="isActive"
                                type="checkbox"
                                defaultChecked={customer?.isActive ?? true}
                                className="w-4 h-4 text-blue-600 rounded"
                            />
                            <span className="text-sm font-medium">Active Customer</span>
                        </label>
                    </div>

                    <div className="flex justify-end gap-2">
                        <button type="button" onClick={onClose} className="px-4 py-2 text-gray-600 hover:bg-gray-100 rounded">Cancel</button>
                        <button type="submit" className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700">
                            {isEdit ? 'Save Changes' : 'Create Customer'}
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );
}


import { Suspense } from 'react';
import { listCustomersAction } from '@/modules/crm/customers/actions';
import CustomersClient from './CustomersClient';
import { verifyPageAccess } from '@/core/auth/actions';

interface PageProps {
    params: Promise<{
        tenantSlug: string;
    }>;
}

export default async function CustomersPage({ params }: PageProps) {
    const { tenantSlug } = await params;
    await verifyPageAccess(tenantSlug);

    // Note: listCustomersAction should handle RBAC or verifyPageAccess should.
    // Assuming simple access check for now.

    let customers: any[] = [];
    try {
        customers = await listCustomersAction(tenantSlug);
    } catch (e) {
        console.warn("Failed to fetch customers", e);
    }

    return (
        <Suspense fallback={<div>Loading customers...</div>}>
            <CustomersClient
                tenantSlug={tenantSlug}
                customers={customers}
            />
        </Suspense>
    );
}

