import { createClient } from "@/utils/supabase/server"
import { notFound } from "next/navigation"
import { format } from "date-fns"
import { Button } from "@/components/ui/button"
import { Printer, ArrowLeft } from "lucide-react"
import Link from "next/link"
import { PrintButton } from "./print-button"
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from "@/components/ui/table"
import { Badge } from "@/components/ui/badge"
import { cn } from "@/lib/utils"

export default async function ManifestReportDetail({ params, searchParams }: { params: Promise<{ tripId: string }>, searchParams: Promise<{ [key: string]: string | string[] | undefined }> }) {
    const supabase = await createClient()
    const { tripId } = await params
    const sParams = await searchParams
    const returnUrl = (sParams?.returnUrl as string) || '/admin/reports/manifest'
    const isReturningToSchedule = returnUrl.includes('/admin/trips')

    // 1. Fetch Trip Details
    const { data: trip } = await supabase
        .from("clnt_trips")
        .select(`
            *,
            route:clnt_routes(origin:clnt_locations!origin_id(name), destination:clnt_locations!destination_id(name)),
            ferry:clnt_ferries(*)
        `)
        .eq("id", tripId)
        .single()

    if (!trip) return notFound()

    // 2. Fetch Reservations for this trip
    const { data: reservations } = await supabase
        .from("clnt_reservations")
        .select(`
            *,
            tickets:clnt_tickets(*),
            zone:clnt_ferry_zones(name)
        `)
        .eq("trip_id", tripId)
        .eq("status", "CONFIRMED")
        .order("created_at", { ascending: true })

    // Calculate totals
    const totalPassengers = reservations?.reduce((sum, res) => sum + (res.count_passengers || 0), 0) || 0
    const totalBikes = reservations?.reduce((sum, res) => sum + (res.count_bikes || 0), 0) || 0
    const totalPets = reservations?.reduce((sum, res) => sum + (res.count_pets || 0), 0) || 0

    // Group by Zone
    const groupedReservations: Record<string, typeof reservations> = {}
    const NO_ZONE_KEY = "General Admission"

    if (reservations) {
        reservations.forEach((res: any) => {
            const zoneName = res.zone?.name || NO_ZONE_KEY
            if (!groupedReservations[zoneName]) {
                groupedReservations[zoneName] = []
            }
            groupedReservations[zoneName].push(res)
        })
    }

    // Sort zone names
    const sortedZoneNames = Object.keys(groupedReservations).sort()

    return (
        <div className="space-y-8 max-w-5xl mx-auto print:max-w-none print:p-0">
            {/* Header / Navigation (Hidden in Print) */}
            <div className="flex items-center justify-between print:hidden">
                <Button variant="ghost" asChild>
                    <Link href={returnUrl}>
                        <ArrowLeft className="mr-2 h-4 w-4" />
                        {isReturningToSchedule ? "Back to Schedule" : "Back to Calendar"}
                    </Link>
                </Button>
                <PrintButton />
            </div>

            {/* Manifest Content */}
            <div className="bg-white p-8 rounded-xl shadow-sm border print:border-none print:shadow-none">
                {/* Trip Info Header */}
                <div className="border-b pb-6 mb-6">
                    <div className="flex justify-between items-start">
                        <div>
                            <h1 className="text-2xl font-bold text-slate-900">Passenger Manifest</h1>
                            <div className="text-slate-500 mt-1">
                                {trip.route?.origin?.name} &rarr; {trip.route?.destination?.name}
                            </div>
