'use client';

import { useState } from 'react';
import { Manifest } from '@/modules/ferry-reporting/domain/types';
import { getManifestDetailsAction } from '../actions';

export default function ManifestsClient({
    tenantSlug,
    initialManifests
}: {
    tenantSlug: string;
    initialManifests: Manifest[];
}) {
    const [manifests, setManifests] = useState<Manifest[]>(initialManifests);
    const [selectedTripId, setSelectedTripId] = useState<string | null>(null);
    const [details, setDetails] = useState<Manifest | null>(null);
    const [loadingDetails, setLoadingDetails] = useState(false);

    const handleViewDetails = async (tripId: string) => {
        if (selectedTripId === tripId) {
            setSelectedTripId(null);
            setDetails(null);
            return;
        }

        setSelectedTripId(tripId);
        setLoadingDetails(true);
        try {
            const data = await getManifestDetailsAction(tenantSlug, tripId);
            setDetails(data);
        } catch (e) {
            console.error(e);
            alert('Failed to load details');
        } finally {
            setLoadingDetails(false);
        }
    };

    return (
        <div className="p-6">
            <h1 className="text-2xl font-bold mb-6">Manifest Reports</h1>

            <div className="bg-white rounded-lg shadow border border-gray-200 overflow-hidden">
                <table className="w-full">
                    <thead className="bg-gray-50 border-b border-gray-200">
                        <tr>
                            <th className="p-4 text-left font-semibold text-gray-600 text-sm">Date/Time</th>
                            <th className="p-4 text-left font-semibold text-gray-600 text-sm">Route</th>
                            <th className="p-4 text-left font-semibold text-gray-600 text-sm">Ferry</th>
                            <th className="p-4 text-left font-semibold text-gray-600 text-sm">Passengers</th>
                            <th className="p-4 text-right font-semibold text-gray-600 text-sm">Actions</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100">
                        {manifests.length === 0 && (
                            <tr>
                                <td colSpan={5} className="p-8 text-center text-gray-500">
                                    No upcoming trips found.
                                </td>
                            </tr>
                        )}
                        {manifests.map((m) => (
                            <>
                                <tr key={m.tripId} className={`hover:bg-gray-50 transition-colors ${selectedTripId === m.tripId ? 'bg-blue-50' : ''}`}>
                                    <td className="p-4 text-sm font-medium">
                                        {new Date(m.tripDate).toLocaleString()}
                                    </td>
                                    <td className="p-4 text-sm">{m.routeName}</td>
                                    <td className="p-4 text-sm text-gray-600">{m.ferryName}</td>
                                    <td className="p-4 text-sm">
                                        <span className="inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-blue-100 text-blue-800">
                                            {m.totalPassengers} Pax
                                        </span>
                                    </td>
                                    <td className="p-4 text-right">
                                        <button
                                            onClick={() => handleViewDetails(m.tripId)}
                                            className="px-3 py-1.5 text-xs font-medium text-blue-600 border border-blue-200 rounded hover:bg-blue-50"
                                        >
                                            {selectedTripId === m.tripId ? 'Hide' : 'View Manifest'}
                                        </button>
                                    </td>
                                </tr>
                                {selectedTripId === m.tripId && (
                                    <tr className="bg-gray-50">
                                        <td colSpan={5} className="p-4">
                                            <div className="bg-white border rounded p-4 shadow-sm">
                                                <h3 className="font-semibold mb-3">Passenger List</h3>
                                                {loadingDetails ? (
                                                    <div className="text-sm text-gray-500">Loading...</div>
                                                ) : details?.passengers && details.passengers.length > 0 ? (
                                                    <table className="w-full text-sm">
                                                        <thead>
                                                            <tr className="text-gray-500 border-b">
                                                                <th className="text-left pb-2">Name</th>
                                                                <th className="text-left pb-2">Class</th>
                                                                <th className="text-left pb-2">Status</th>
                                                                <th className="text-left pb-2">Ref</th>
                                                            </tr>
                                                        </thead>
                                                        <tbody className="divide-y">
                                                            {details.passengers.map((p, idx) => (
                                                                <tr key={idx}>
                                                                    <td className="py-2">{p.name}</td>
                                                                    <td className="py-2">{p.ticketClass}</td>
                                                                    <td className="py-2 uppercase text-xs">{p.status}</td>
                                                                    <td className="py-2 font-mono text-xs">{p.reservationId.slice(0, 8)}</td>
                                                                </tr>
                                                            ))}
                                                        </tbody>
                                                    </table>
                                                ) : (
                                                    <div className="text-sm text-gray-500">No passengers found.</div>
                                                )}
                                            </div>
                                        </td>
                                    </tr>
                                )}
                            </>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
    );
}


import { createAuthClient } from "@/infra/supabase/server-auth";
import { SupabaseTenantRepository } from "@/infra/repositories/SupabaseTenantRepository";
import { SupabaseManifestRepository } from "@/modules/ferry-reporting/infrastructure/SupabaseManifestRepository";
import { notFound, redirect } from "next/navigation";
import { getUserContext } from "@/core/context/getUserContext";
import { getTenantContext } from "@/core/context/getTenantContext";
import ManifestsClient from "./ManifestsClient";

interface PageProps {
    params: Promise<{
        tenantSlug: string;
    }>;
}

export default async function ManifestsPage({ params }: PageProps) {
    const supabase = createAuthClient();
    const { data: { user } } = await supabase.auth.getUser();

    if (!user) redirect("/login");

    const { tenantSlug } = await params;
    const tenantRepo = new SupabaseTenantRepository();
    const tenant = await tenantRepo.resolveTenantForUser(user.id, tenantSlug);

    if (!tenant) notFound();

    // Context & RBAC
    const [tenantContext, userContext] = await Promise.all([
        getTenantContext(tenant.id, tenant.slug),
        getUserContext(user.id, tenant.id)
    ]);

    if (!tenantContext || !userContext) redirect('/login');

    if (!userContext.permissions.includes('reports.view') && !userContext.permissions.includes('*')) {
        redirect('/admin/unauthorized');
    }

    const repo = new SupabaseManifestRepository();
    const manifests = await repo.findManifests(tenant.id, {
        startDate: new Date().toISOString()
    });

    return <ManifestsClient tenantSlug={tenantSlug} initialManifests={manifests} />;
}

