'use server'

import { createServiceClient } from "@/utils/supabase/service"

export async function getSalesAnalytics() {
    try {
        const supabase = createServiceClient()
        if (!supabase) throw new Error("Supabase client not initialized")

        const now = new Date()

        // Month-to-Date (MTD) Range
        const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1)
        const endOfToday = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 23, 59, 59)

        // Previous Month for MoM (same day relative to start of month)
        const startOfPrevMonth = new Date(now.getFullYear(), now.getMonth() - 1, 1)
        const endOfPrevMonthToday = new Date(now.getFullYear(), now.getMonth() - 1, now.getDate(), 23, 59, 59)

        // Last 7 Days for Bar Chart
        const sevenDaysAgo = new Date()
        sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 6)
        sevenDaysAgo.setHours(0, 0, 0, 0)

        // 1. Fetch MTD Data
        const { data: mtdOrders, error: mtdError } = await supabase
            .from('clnt_orders')
            .select('created_at, total_amount')
            .gte('created_at', startOfMonth.toISOString())
            .lte('created_at', endOfToday.toISOString())

        if (mtdError) throw mtdError

        // 2. Fetch Previous Month (MoM comparison)
        const { data: prevMonthOrders, error: prevError } = await supabase
            .from('clnt_orders')
            .select('created_at, total_amount')
            .gte('created_at', startOfPrevMonth.toISOString())
            .lte('created_at', endOfPrevMonthToday.toISOString())

        if (prevError) throw prevError

        // 3. Fetch 7-day history for charts
        const { data: weekOrders, error: weekError } = await supabase
            .from('clnt_orders')
            .select('created_at, total_amount')
            .gte('created_at', sevenDaysAgo.toISOString())
            .lte('created_at', endOfToday.toISOString())

        if (weekError) throw weekError

        // Aggregation Helpers
        const aggregate = (data: any[]) => ({
            total: data?.reduce((s, o) => s + Number(o.total_amount), 0) || 0,
            count: data?.length || 0
        })

        const mtd = aggregate(mtdOrders)
        const prevMoM = aggregate(prevMonthOrders)

        // Yesterday's (Daily Increment)
        const yesterdayStr = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 1).toISOString().split('T')[0]
        const { data: yesterdayOrders } = await supabase
            .from('clnt_orders')
            .select('total_amount')
            .gte('created_at', `${yesterdayStr}T00:00:00`)
            .lte('created_at', `${yesterdayStr}T23:59:59`)

        const daily = aggregate(yesterdayOrders || [])

        // 7-Day History for Bars
        const historyDays = Array.from({ length: 7 }).map((_, i) => {
            const d = new Date()
            d.setDate(d.getDate() - (6 - i))
            return d.toISOString().split('T')[0]
        })

        const revenueTrend = historyDays.map(day =>
            weekOrders?.filter(o => o.created_at.startsWith(day))
                .reduce((s, o) => s + Number(o.total_amount), 0) || 0
        )
        const bookingsTrend = historyDays.map(day =>
            weekOrders?.filter(o => o.created_at.startsWith(day)).length || 0
        )

        // Calculate MoM Trend %
        const calcTrend = (curr: number, prev: number) => {
            if (prev === 0) return curr > 0 ? 100 : 0
            return ((curr - prev) / prev) * 100
        }

        return {
            success: true,
            revenue: {
                currentMtd: mtd.total,
                dailyIncrement: daily.total,
                trend: revenueTrend,
                momChange: calcTrend(mtd.total, prevMoM.total)
            },
            bookings: {
                currentMtd: mtd.count,
                dailyIncrement: daily.count,
                trend: bookingsTrend,
                momChange: calcTrend(mtd.count, prevMoM.count)
            }
        }
    } catch (e: any) {
        console.error("Sales Analytics Error:", e)
        return { success: false, error: e.message }
    }
}


import { AdminDashboardContent } from "@/components/admin/admin-dashboard-content"
import { getAdminMenu, getCockpitMenu } from "@/modules/admin-menu/actions"
import { getSalesAnalytics } from "./actions"
import { createClient } from "@/utils/supabase/server"
import { createServiceClient } from "@/utils/supabase/service"
import { AdminPageHeader } from "@/components/admin/admin-page-header"
import { CustomizeButton } from "@/components/admin/customize-button"

interface PageProps {
    searchParams: Promise<{ [key: string]: string | string[] | undefined }>
}

export default async function SalesCockpitPage({ searchParams }: PageProps) {
    const sp = await searchParams
    const isEditMode = sp.edit === 'true'
    const contextId = 'sales-cockpit'

    const supabase = await createClient()
    const { data: { user } } = await supabase.auth.getUser()

    if (!user) {
        return <div className="p-8">Odmowa dostępu</div>
    }

    const serviceSupabase = createServiceClient()
    if (!serviceSupabase) {
        return <div className="p-8">Błąd konfiguracji serwisu</div>
    }
    const { data: profile } = await serviceSupabase
        .from('auth_profiles')
        .select('is_superadmin')
        .eq('id', user.id)
        .single()

    // Fetch cockpit items directly
    const salesSections = await getCockpitMenu('admin.cockpit.sales', isEditMode, contextId)

    if (salesSections.length === 0) {
        return <div className="p-8">Sales cockpit not configured or not found.</div>
    }

    // Determine render order of sections?
    // They are sorted by sort_order in DB/getAdminMenu.
    // admin.cockpit.salesAnalytics (90)
    // menu.sections.sales (100)
    // So Analytics should appear first.

    const stats = await getSalesAnalytics()

    const widgetData = {
        sales: {
            revenue: stats.success ? stats.revenue : null,
            bookings: stats.success ? stats.bookings : null
        }
    }

    return (
        <div className="space-y-12 animate-in fade-in duration-1000">
            <AdminPageHeader
                titleKey="admin.sales.title"
                subtitleKey="admin.sales.description"
                backLink="/admin"
                backLabel="Menu"
            >
                <CustomizeButton />
            </AdminPageHeader>
            <AdminDashboardContent
                initialMenu={salesSections}
                userId={user.id}
                isSuperAdmin={profile?.is_superadmin || false}
                contextId={contextId}
                data={widgetData}
            />
        </div>
    )
}

