import { createAuthClient } from "@/infra/supabase/server-auth";
import { SupabaseTenantRepository } from "@/infra/repositories/SupabaseTenantRepository";
import { notFound, redirect } from "next/navigation";
import { getUserContext } from "@/core/context/getUserContext";
import { getTenantContext } from "@/core/context/getTenantContext";
import SalesDashboard from "./SalesDashboard";
import { getSalesMetricsAction, getSalesDailyAction, getTicketBreakdownAction } from "@/modules/ferry-reporting/sales/actions";

interface PageProps {
    params: Promise<{
        tenantSlug: string;
    }>;
}

export default async function SalesPage({ params }: PageProps) {
    const supabase = createAuthClient();
    const { data: { user } } = await supabase.auth.getUser();

    if (!user) redirect("/login");

    const { tenantSlug } = await params;
    const tenantRepo = new SupabaseTenantRepository();
    const tenant = await tenantRepo.resolveTenantForUser(user.id, tenantSlug);

    if (!tenant) notFound();

    // Context & RBAC
    const [tenantContext, userContext] = await Promise.all([
        getTenantContext(tenant.id, tenant.slug),
        getUserContext(user.id, tenant.id)
    ]);

    if (!tenantContext || !userContext) redirect('/login');

    if (!userContext.permissions.includes('reports.view') && !userContext.permissions.includes('*')) {
        redirect('/admin/unauthorized');
    }

    // Default range: Last 30 days
    const end = new Date();
    const start = new Date();
    start.setDate(start.getDate() - 30);

    // Fetch data in parallel
    const [metrics, dailyRevenue, ticketBreakdown] = await Promise.all([
        getSalesMetricsAction(tenantSlug, start.toISOString(), end.toISOString()),
        getSalesDailyAction(tenantSlug, start.toISOString(), end.toISOString()),
        getTicketBreakdownAction(tenantSlug, start.toISOString(), end.toISOString())
    ]);

    return (
        <SalesDashboard
            tenantSlug={tenantSlug}
            metrics={metrics}
            dailyRevenue={dailyRevenue}
            ticketBreakdown={ticketBreakdown}
            startDate={start.toISOString()}
            endDate={end.toISOString()}
        />
    );
}

'use client';

import React from 'react';
import { SalesMetrics, SalesDailyRevenue, TicketBreakdown } from "@/modules/ferry-reporting/domain/ports";
import { TrendingUp, ShoppingCart, DollarSign, Users } from 'lucide-react';

interface SalesDashboardProps {
    tenantSlug: string;
    metrics: SalesMetrics;
    dailyRevenue: SalesDailyRevenue[];
    ticketBreakdown: TicketBreakdown[];
    startDate: string;
    endDate: string;
}

export default function SalesDashboard({ metrics, dailyRevenue, ticketBreakdown, startDate, endDate }: SalesDashboardProps) {

    // Helper for currency formatting
    const formatCurrency = (amount: number) => {
        return new Intl.NumberFormat('en-US', {
            style: 'currency',
            currency: metrics.currency || 'USD'
        }).format(amount);
    };

    // Calculate max value for chart scaling
    const maxDailyRevenue = Math.max(...dailyRevenue.map(d => d.revenue), 1); // Avoid div by zero

    return (
        <div className="space-y-6">
            {/* Header / Date Range */}
            <div className="flex justify-between items-center">
                <div className="text-sm text-gray-500">
                    Range: <span className="font-medium text-gray-900">{new Date(startDate).toLocaleDateString()} - {new Date(endDate).toLocaleDateString()}</span>
                </div>
                <div className="flex gap-2">
                    <button className="px-3 py-1 bg-white border rounded hover:bg-gray-50 text-sm" onClick={() => alert("Date filtering pending")}>
                        Last 7 Days
                    </button>
                    <button className="px-3 py-1 bg-white border rounded hover:bg-gray-50 text-sm" onClick={() => alert("Date filtering pending")}>
                        Last 30 Days
                    </button>
                </div>
            </div>

            {/* Metrics Cards */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="bg-white p-6 rounded-lg shadow-sm border">
                    <div className="flex justify-between items-start">
                        <div>
                            <p className="text-sm font-medium text-gray-500">Total Revenue</p>
                            <h3 className="text-2xl font-bold mt-2 text-gray-900">{formatCurrency(metrics.totalRevenue)}</h3>
                        </div>
                        <div className="p-2 bg-green-50 rounded-full text-green-600">
                            <DollarSign size={20} />
                        </div>
                    </div>
                </div>

                <div className="bg-white p-6 rounded-lg shadow-sm border">
                    <div className="flex justify-between items-start">
                        <div>
                            <p className="text-sm font-medium text-gray-500">Total Orders</p>
                            <h3 className="text-2xl font-bold mt-2 text-gray-900">{metrics.totalOrders}</h3>
                        </div>
                        <div className="p-2 bg-blue-50 rounded-full text-blue-600">
                            <ShoppingCart size={20} />
                        </div>
                    </div>
                </div>

                <div className="bg-white p-6 rounded-lg shadow-sm border">
                    <div className="flex justify-between items-start">
                        <div>
                            <p className="text-sm font-medium text-gray-500">Avg. Order Value</p>
                            <h3 className="text-2xl font-bold mt-2 text-gray-900">{formatCurrency(metrics.averageOrderValue)}</h3>
                        </div>
                        <div className="p-2 bg-purple-50 rounded-full text-purple-600">
                            <TrendingUp size={20} />
                        </div>
                    </div>
                </div>
            </div>

            {/* Charts Row */}
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                {/* Daily Revenue Bar Chart */}
                <div className="lg:col-span-2 bg-white p-6 rounded-lg shadow-sm border">
                    <h3 className="font-semibold text-gray-900 mb-6">Revenue Trend</h3>
                    <div className="h-64 flex items-end gap-2">
                        {dailyRevenue.length === 0 ? (
                            <div className="w-full h-full flex items-center justify-center text-gray-400 text-sm">No revenue data for this period</div>
                        ) : (
                            dailyRevenue.map((day, idx) => (
                                <div key={idx} className="flex-1 flex flex-col items-center group relative">
                                    {/* Tooltip */}
                                    <div className="absolute bottom-full mb-2 hidden group-hover:block bg-gray-800 text-white text-xs rounded px-2 py-1 whitespace-nowrap z-10">
                                        {day.date}: {formatCurrency(day.revenue)}
                                    </div>
                                    {/* Bar */}
                                    <div
                                        className="w-full bg-blue-500 rounded-t hover:bg-blue-600 transition-all min-w-[4px] max-w-[40px]"
                                        style={{ height: `${(day.revenue / maxDailyRevenue) * 100}%` }}
                                    ></div>
                                    {/* Label (only show some if too many) */}
                                    <div className="mt-2 text-[10px] text-gray-500 transform -rotate-45 origin-top-left whitespace-nowrap overflow-hidden text-ellipsis md:rotate-0">
                                        {new Date(day.date).toLocaleDateString(undefined, { day: 'numeric', month: 'short' })}
                                    </div>
                                </div>
                            ))
                        )}
                    </div>
                </div>

                {/* Ticket Breakdown */}
                <div className="bg-white p-6 rounded-lg shadow-sm border">
                    <h3 className="font-semibold text-gray-900 mb-6">Breakdown by Category</h3>
                    <div className="space-y-4">
                        {ticketBreakdown.length === 0 ? (
                            <div className="text-center text-gray-400 text-sm py-12">No sales data</div>
                        ) : (
                            ticketBreakdown.map((item, idx) => (
                                <div key={idx}>
                                    <div className="flex justify-between text-sm mb-1">
                                        <span className="font-medium text-gray-700">{item.category}</span>
                                        <span className="text-gray-900">{item.count} sold</span>
                                    </div>
                                    <div className="flex justify-between text-xs text-gray-500 mb-1">
                                        <span>Revenue</span>
                                        <span>{formatCurrency(item.revenue)}</span>
                                    </div>
                                    <div className="w-full bg-gray-100 rounded-full h-2 overflow-hidden">
                                        <div
                                            className="bg-green-500 h-2 rounded-full"
                                            style={{ width: metrics.totalRevenue > 0 ? `${(item.revenue / metrics.totalRevenue) * 100}%` : '0%' }}
                                        ></div>
                                    </div>
                                </div>
                            ))
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
}

