import { listUsersAction } from '@/modules/core-admin/users/actions';
import UsersClient from './users-client';

export default async function UsersPage({ params }: { params: Promise<{ tenantSlug: string }> }) {
    const { tenantSlug } = await params;

    let users: any[] = [];
    try {
        users = await listUsersAction(tenantSlug);
    } catch (e) {
        console.error('Failed to list users', e);
    }

    return <UsersClient users={users} tenantSlug={tenantSlug} />;
}


'use client';

import { useState, useTransition } from 'react';
import { useRouter } from 'next/navigation';
import { inviteUserAction, updateUserRoleAction, toggleUserStatusAction } from '@/modules/core-admin/users/actions';

type User = {
    user_id: string;
    email?: string;
    status: string;
    role?: string;
    created_at: string;
};

export default function UsersClient({
    users,
    tenantSlug
}: {
    users: User[];
    tenantSlug: string;
}) {
    const [isPending, startTransition] = useTransition();
    const [showInvite, setShowInvite] = useState(false);
    const router = useRouter();

    return (
        <div className="p-6">
            <div className="flex justify-between items-center mb-6">
                <h1 className="text-2xl font-bold">Users Management</h1>
                <button
                    onClick={() => setShowInvite(true)}
                    className="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700 transition-colors shadow-sm font-medium"
                >
                    + Invite User
                </button>
            </div>

            <div className="bg-white rounded-lg shadow border border-gray-200 overflow-hidden">
                <table className="w-full">
                    <thead className="bg-gray-50 border-b border-gray-200">
                        <tr>
                            <th className="p-4 text-left font-semibold text-gray-600 text-sm">User ID / Email</th>
                            <th className="p-4 text-left font-semibold text-gray-600 text-sm">Role</th>
                            <th className="p-4 text-left font-semibold text-gray-600 text-sm">Status</th>
                            <th className="p-4 text-left font-semibold text-gray-600 text-sm">Joined</th>
                            <th className="p-4 text-right font-semibold text-gray-600 text-sm">Actions</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100">
                        {users.length === 0 && (
                            <tr>
                                <td colSpan={5} className="p-8 text-center text-gray-500">
                                    No users found in this tenant.
                                </td>
                            </tr>
                        )}
                        {users.map((u) => (
                            <UserRow key={u.user_id} user={u} tenantSlug={tenantSlug} />
                        ))}
                    </tbody>
                </table>
            </div>

            <div className="mt-4 text-xs text-gray-400">
                Tenant: {tenantSlug}
            </div>

            {showInvite && (
                <InviteModal
                    tenantSlug={tenantSlug}
                    onClose={() => setShowInvite(false)}
                    onSuccess={() => {
                        setShowInvite(false);
                        router.refresh();
                    }}
                />
            )}
        </div>
    );
}

function UserRow({ user, tenantSlug }: { user: User; tenantSlug: string }) {
    const [isPending, startTransition] = useTransition();

    const handleRoleChange = (newRole: string) => {
        if (confirm(`Change role to ${newRole}?`)) {
            startTransition(async () => {
                await updateUserRoleAction(tenantSlug, user.user_id, newRole);
                window.location.reload(); // Simple reload for parity speed
            });
        }
    };

    const handleToggleStatus = () => {
        const action = user.status === 'blocked' ? 'Active' : 'Blocked';
        if (confirm(`Set status to ${action}?`)) {
            startTransition(async () => {
                await toggleUserStatusAction(tenantSlug, user.user_id, user.status !== 'blocked');
                window.location.reload();
            });
        }
    };

    return (
        <tr className="hover:bg-gray-50 transition-colors">
            <td className="p-4">
                <div className="font-medium text-gray-900">{user.email || 'External User'}</div>
                <div className="text-xs font-mono text-gray-400 mt-1">{user.user_id}</div>
            </td>
            <td className="p-4">
                <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-blue-100 text-blue-800">
                    {user.role || 'Member'}
                </span>
            </td>
            <td className="p-4">
                <span
                    className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${user.status === 'blocked'
                            ? 'bg-red-100 text-red-800'
                            : 'bg-green-100 text-green-800'
                        }`}
                >
                    {user.status || 'Active'}
                </span>
            </td>
            <td className="p-4 text-sm text-gray-500">
                {new Date(user.created_at).toLocaleDateString()}
            </td>
            <td className="p-4 text-right">
                <div className="relative inline-block text-left group">
                    <button className="text-gray-400 hover:text-gray-600 font-medium text-sm border rounded px-3 py-1 hover:bg-gray-100">
                        Manage ▾
                    </button>
                    {/* Zero-Dep Dropdown using CSS hover */}
                    <div className="hidden group-hover:block absolute right-0 mt-0 w-48 rounded-md shadow-lg bg-white ring-1 ring-black ring-opacity-5 z-10">
                        <div className="py-1">
                            <button
                                onClick={() => handleRoleChange('admin')}
                                disabled={isPending}
                                className="block w-full text-left px-4 py-2 text-sm text-gray-700 hover:bg-gray-100"
                            >
                                Set Role: Admin
                            </button>
                            <button
                                onClick={() => handleRoleChange('member')}
                                disabled={isPending}
                                className="block w-full text-left px-4 py-2 text-sm text-gray-700 hover:bg-gray-100"
                            >
                                Set Role: Member
                            </button>
                            <button
                                onClick={() => handleRoleChange('viewer')}
                                disabled={isPending}
                                className="block w-full text-left px-4 py-2 text-sm text-gray-700 hover:bg-gray-100"
                            >
                                Set Role: Viewer
                            </button>
                            <div className="border-t border-gray-100 my-1"></div>
                            <button
                                onClick={handleToggleStatus}
                                disabled={isPending}
                                className={`block w-full text-left px-4 py-2 text-sm ${user.status === 'blocked'
                                        ? 'text-green-600 hover:bg-green-50'
                                        : 'text-red-600 hover:bg-red-50'
                                    }`}
                            >
                                {user.status === 'blocked' ? 'Unblock User' : 'Block Access'}
                            </button>
                        </div>
                    </div>
                </div>
            </td>
        </tr>
    );
}

function InviteModal({
    tenantSlug,
    onClose,
    onSuccess
}: {
    tenantSlug: string;
    onClose: () => void;
    onSuccess: () => void;
}) {
    const [isPending, startTransition] = useTransition();

    return (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
            <div className="bg-white rounded-lg shadow-xl w-full max-w-md p-6">
                <h2 className="text-xl font-bold mb-4">Invite New User</h2>
                <form
                    action={(formData) => {
