'use server'

import { createClient } from "@/utils/supabase/server"
import { revalidatePath } from "next/cache"

export async function getRoles() {
    const supabase = await createClient()
    const { data: roles } = await supabase.from('auth_roles').select('*, auth_role_permissions(app_id)')
    return roles || []
}

export async function createRole(name: string, description: string, apps: string[]) {
    const supabase = await createClient()

    const { data: role, error: roleError } = await supabase
        .from('auth_roles')
        .insert({ name, description })
        .select()
        .single()

    if (roleError) throw new Error(roleError.message)

    if (apps.length > 0) {
        const { error: appError } = await supabase
            .from('auth_role_permissions')
            .insert(apps.map(appId => ({ role_id: role.id, app_id: appId })))

        if (appError) throw new Error(appError.message)
    }

    revalidatePath('/admin/roles')
}

export async function updateRole(id: string, name: string, description: string, apps: string[]) {
    const supabase = await createClient()

    await supabase.from('auth_roles').update({ name, description }).eq('id', id)

    // Refresh apps: delete existing and insert new
    await supabase.from('auth_role_permissions').delete().eq('role_id', id)

    if (apps.length > 0) {
        await supabase
            .from('auth_role_permissions')
            .insert(apps.map(appId => ({ role_id: id, app_id: appId })))
    }

    revalidatePath('/admin/roles')
}

export async function deleteRole(id: string) {
    const supabase = await createClient()
    await supabase.from('auth_roles').delete().eq('id', id)
    revalidatePath('/admin/roles')
}

