import { listRolesAction, listPermissionsAction } from '@/modules/core-admin/roles/actions';
import RolesClient from './roles-client';

export default async function RolesPage({ params }: { params: Promise<{ tenantSlug: string }> }) {
    const { tenantSlug } = await params;

    let roles: any[] = [];
    let permissions: any[] = [];

    try {
        const [r, p] = await Promise.all([
            listRolesAction(tenantSlug),
            listPermissionsAction(tenantSlug)
        ]);
        roles = r;
        permissions = p;
    } catch (e) {
        console.error('Failed to load roles data', e);
    }

    return (
        <RolesClient
            tenantSlug={tenantSlug}
            roles={roles}
            allPermissions={permissions}
