'use client';

import { useState, useTransition } from 'react';
import { useRouter } from 'next/navigation';
import { createRoleAction, deleteRoleAction, updateRolePermissionsAction, updateRoleAction } from '@/modules/core-admin/roles/actions';

type Role = {
    id: string;
    name: string;
    description?: string;
    permissions: string[];
};

type Permission = {
    key: string;
    description: string;
};

export default function RolesClient({
    tenantSlug,
    roles,
    allPermissions
}: {
    tenantSlug: string;
    roles: Role[];
    allPermissions: Permission[];
}) {
    const [isPending, startTransition] = useTransition();
    const [showCreate, setShowCreate] = useState(false);
    const [editingRole, setEditingRole] = useState<Role | null>(null); // For Permissions
    const [updatingRole, setUpdatingRole] = useState<Role | null>(null); // For Details

    // Group permissions by prefix for better UI
    const permissionGroups = allPermissions.reduce((acc, p) => {
        const prefix = p.key.split('.')[0];
        if (!acc[prefix]) acc[prefix] = [];
        acc[prefix].push(p);
        return acc;
    }, {} as Record<string, Permission[]>);

    const handleDelete = async (roleId: string) => {
        if (confirm('Are you sure you want to delete this role?')) {
            startTransition(async () => {
                await deleteRoleAction(tenantSlug, roleId);
            });
        }
    };

    return (
        <div className="p-6">
            <div className="flex justify-between items-center mb-6">
                <h1 className="text-2xl font-bold">Roles & Permissions</h1>
                <button
                    onClick={() => setShowCreate(true)}
                    className="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700 transition-colors"
                >
                    + Create Role
                </button>
            </div>

            <div className="grid gap-4">
                {roles.map((role) => (
                    <div key={role.id} className="bg-white p-4 rounded shadow border border-gray-200">
                        <div className="flex justify-between items-start">
                            <div>
                                <h3 className="font-bold text-lg">{role.name}</h3>
                                <p className="text-gray-500 text-sm">{role.description || 'No description'}</p>
                                <div className="mt-2 flex flex-wrap gap-2">
                                    {role.permissions.map(p => (
                                        <span key={p} className="px-2 py-0.5 bg-gray-100 text-gray-700 rounded text-xs border border-gray-200">
                                            {p}
                                        </span>
                                    ))}
                                    {role.permissions.length === 0 && (
                                        <span className="text-gray-400 text-xs italic">No permissions assigned</span>
                                    )}
                                </div>
                            </div>
                            <div className="flex gap-2">
                                <button
                                    onClick={() => setUpdatingRole(role)}
                                    className="px-3 py-1.5 text-xs font-medium text-gray-600 border border-gray-300 rounded hover:bg-gray-50"
                                >
                                    Edit
                                </button>
                                <button
                                    onClick={() => setEditingRole(role)}
                                    className="px-3 py-1.5 text-xs font-medium text-blue-600 border border-blue-200 rounded hover:bg-blue-50"
                                >
                                    Permissions
                                </button>
                                <button
                                    onClick={() => handleDelete(role.id)}
                                    disabled={isPending}
                                    className="px-3 py-1.5 text-xs font-medium text-red-600 border border-red-200 rounded hover:bg-red-50 disabled:opacity-50"
                                >
                                    Delete
                                </button>
                            </div>
                        </div>
                    </div>
                ))}
            </div>

            {/* Create Modal */}
            {showCreate && (
                <div className="fixed inset-0 bg-black/50 flex item-center justify-center p-4 z-50 overflow-y-auto">
                    <div className="bg-white rounded-lg shadow-xl max-w-md w-full p-6 m-auto">
                        <h2 className="text-xl font-bold mb-4">Create New Role</h2>
                        <form action={async (formData) => {
                            await createRoleAction(tenantSlug, formData);
                            setShowCreate(false);
                        }}>
                            <div className="mb-4">
                                <label className="block text-sm font-medium mb-1">Role Name</label>
                                <input name="name" className="w-full border p-2 rounded" required placeholder="e.g. Content Editor" />
                            </div>
                            <div className="mb-6">
                                <label className="block text-sm font-medium mb-1">Description</label>
                                <textarea name="description" className="w-full border p-2 rounded" placeholder="Optional description" />
                            </div>
                            <div className="flex justify-end gap-2">
                                <button type="button" onClick={() => setShowCreate(false)} className="px-4 py-2 text-gray-600 hover:bg-gray-100 rounded">Cancel</button>
                                <button type="submit" className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700">Create Role</button>
                            </div>
                        </form>
                    </div>
                </div>
            )}

            {/* Edit Permissions Modal */}
            {editingRole && (
                <PermissionEditor
                    role={editingRole}
                    groups={permissionGroups}
                    onClose={() => setEditingRole(null)}
                    onSave={async (roleId, newPermissions) => {
                        await updateRolePermissionsAction(tenantSlug, roleId, newPermissions);
                        setEditingRole(null);
                    }}
                />
            )}

            {/* Edit Details Modal */}
            {updatingRole && (
                <div className="fixed inset-0 bg-black/50 flex item-center justify-center p-4 z-50 overflow-y-auto">
                    <div className="bg-white rounded-lg shadow-xl max-w-md w-full p-6 m-auto">
                        <h2 className="text-xl font-bold mb-4">Edit Role</h2>
                        <form action={async (formData) => {
                            await updateRoleAction(tenantSlug, updatingRole.id, formData);
                            setUpdatingRole(null);
                        }}>
                            <div className="mb-4">
                                <label className="block text-sm font-medium mb-1">Role Name</label>
                                <input name="name" defaultValue={updatingRole.name} className="w-full border p-2 rounded" required />
                            </div>
                            <div className="mb-6">
                                <label className="block text-sm font-medium mb-1">Description</label>
                                <textarea name="description" defaultValue={updatingRole.description || ''} className="w-full border p-2 rounded" />
                            </div>
                            <div className="flex justify-end gap-2">
                                <button type="button" onClick={() => setUpdatingRole(null)} className="px-4 py-2 text-gray-600 hover:bg-gray-100 rounded">Cancel</button>
                                <button type="submit" className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700">Save Changes</button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
}

function PermissionEditor({
    role,
    groups,
    onClose,
    onSave
}: {
    role: Role,
    groups: Record<string, Permission[]>,
    onClose: () => void,
    onSave: (id: string, perms: string[]) => Promise<void>
}) {
    const [selected, setSelected] = useState<Set<string>>(new Set(role.permissions));
    const [isSaving, setIsSaving] = useState(false);

    const toggle = (key: string) => {
        const next = new Set(selected);
        if (next.has(key)) next.delete(key);
        else next.add(key);
        setSelected(next);
    };

    const handleSave = async () => {
        setIsSaving(true);
        try {
            await onSave(role.id, Array.from(selected));
        } finally {
            setIsSaving(false);
        }
    };

    return (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center p-4 z-50">
            <div className="bg-white rounded-lg shadow-xl max-w-4xl w-full max-h-[90vh] flex flex-col">
                <div className="p-6 border-b">
                    <h2 className="text-xl font-bold">Edit Permissions: {role.name}</h2>
                    <p className="text-sm text-gray-500">Select the permissions this role should have.</p>
                </div>

                <div className="flex-1 overflow-y-auto p-6">
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                        {Object.entries(groups).map(([group, perms]) => (
                            <div key={group} className="border rounded p-4">
                                <h3 className="font-semibold capitalize mb-3 border-b pb-2">{group}</h3>
                                <div className="space-y-2">
                                    {perms.map(p => (
                                        <label key={p.key} className="flex items-start gap-2 cursor-pointer hover:bg-gray-50 p-1 rounded">
                                            <input
                                                type="checkbox"
                                                checked={selected.has(p.key)}
                                                onChange={() => toggle(p.key)}
                                                className="mt-1"
                                            />
                                            <div className="text-sm">
                                                <div className="font-mono text-xs text-gray-600">{p.key}</div>
                                                <div className="text-gray-500 text-xs">{p.description}</div>
                                            </div>
                                        </label>
                                    ))}
                                </div>
                            </div>
                        ))}
                    </div>
                </div>

                <div className="p-6 border-t bg-gray-50 flex justify-end gap-2 rounded-b-lg">
                    <button
                        onClick={onClose}
                        className="px-4 py-2 text-gray-600 hover:bg-gray-100 rounded"
                        disabled={isSaving}
                    >
                        Cancel
                    </button>
                    <button
                        onClick={handleSave}
                        className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700 disabled:opacity-50"
                        disabled={isSaving}
                    >
                        {isSaving ? 'Saving...' : `Save ${selected.size} Permissions`}
                    </button>
                </div>
            </div>
        </div>
    );
}

