import { createServiceClient } from "@/utils/supabase/service"
import { createClient } from "@/utils/supabase/server"
import { redirect } from "next/navigation"
import { SessionsContent } from "@/components/admin/sessions/sessions-content"
import { cookies } from "next/headers"

export const metadata = {
    title: 'Sesje Administratorów | Zalew Admin',
    description: 'Monitorowanie aktywnych sesji i urządzeń.',
}

import { getTimezone } from "@/app/admin/settings/actions"

export default async function AdminSessionsPage() {
    const supabase = await createClient()
    const { data: { user } } = await supabase.auth.getUser()

    if (!user) {
        redirect('/admin/login')
    }

    const serviceSupabase = createServiceClient()
    if (!serviceSupabase) {
        return <div className="p-8 text-red-500 font-bold underline text-center bg-white rounded-2xl border border-red-100 shadow-sm mx-auto max-w-lg mt-12">Błąd konfiguracji serwera.</div>
    }

    // Check if user profile
    const { data: profile } = await serviceSupabase
        .from('auth_profiles')
        .select('is_superadmin')
        .eq('id', user.id)
        .single()

    const query = serviceSupabase
        .from('auth_trusted_devices')
        .select(`
            *,
            admin_profiles:user_id (
                login,
                email,
                is_active
            )
        `)
        .order('last_heartbeat_at', { ascending: false })

    if (!profile?.is_superadmin) {
        query.eq('user_id', user.id)
    }

    const [{ data: sessions }, timezone] = await Promise.all([
        query,
        getTimezone()
    ])

    const cookieStore = await cookies()
    const currentDeviceId = cookieStore.get('device_id')?.value

    return (
        <SessionsContent
            sessions={sessions || []}
            currentDeviceId={currentDeviceId || ""}
            isSuperadmin={profile?.is_superadmin || false}
            timezone={timezone}
        />
    )
}

