    }, []);

    // Stable date formatting
    const formatDate = (dateString: string | Date) => {
        if (!mounted) return ''; // Prevent hydration mismatch
        return new Date(dateString).toLocaleString();
    };

    return (
        <div className="bg-white rounded shadow text-black">
            <h2 className="text-xl font-bold p-4 border-b">Active 2FA Sessions</h2>
            <table className="w-full text-left">
                <thead>
                    <tr className="border-b bg-gray-50">
                        <th className="p-3">ID</th>
                        <th className="p-3">User ID</th>
                        <th className="p-3">Expires At</th>
                        <th className="p-3">Status</th>
                    </tr>
                </thead>
                <tbody>
                    {sessions.length === 0 && (
                        <tr><td colSpan={4} className="p-4 text-center text-gray-500">No active sessions.</td></tr>
                    )}
                    {sessions.map(s => (
                        <tr key={s.id} className="border-b hover:bg-gray-50">
                            <td className="p-3 font-mono text-sm">{s.id.substring(0, 8)}...</td>
                            <td className="p-3 font-mono text-sm">{s.userId}</td>
                            <td className="p-3">
                                {mounted ? formatDate(s.expiresAt) : <span className="text-gray-400">Loading date...</span>}
                            </td>
                            <td className="p-3">
                                {s.revokedAt ? (
                                    <span className="text-red-600 bg-red-100 px-2 py-1 rounded text-xs">Revoked</span>
                                ) : (
                                    <span className="text-green-600 bg-green-100 px-2 py-1 rounded text-xs">Active</span>
                                )}
                            </td>
                        </tr>
                    ))}
                </tbody>
            </table>
        </div>
    );
}

