'use server'

import { createClient } from "@/utils/supabase/server"
import { revalidatePath } from "next/cache"

export async function toggleEmailSetting(enabled: boolean) {
    try {
        const supabase = await createClient()

        const { error } = await supabase
            .from("sys_settings")
            .upsert({
                key: 'emails_enabled',
                value: enabled
            })

        if (error) throw error

        revalidatePath("/admin/settings")
        return { success: true }
    } catch (e: any) {
        console.error("Error updating settings:", e)
        return { success: false, error: e.message }
    }
}

export async function getEmailSetting() {
    try {
        const supabase = await createClient()
        const { data } = await supabase
            .from("sys_settings")
            .select("value")
            .eq("key", "emails_enabled")
            .single()

        return !!data?.value
    } catch (e) {
        return true
    }
}

export async function setTimezone(timezone: string) {
    try {
        const supabase = await createClient()
        const { error } = await supabase
            .from("sys_settings")
            .upsert({
                key: 'app_timezone',
                value: timezone // store as string, value is jsonb usually? check schema. 
                // If value is boolean, we might have issue if schema enforces boolean.
                // Assuming value is JSONB or text based on context.
                // If it's a polymorphic column, supabase handles it.
            })

        if (error) throw error
        revalidatePath("/admin")
        return { success: true }
    } catch (e: any) {
        return { success: false, error: e.message }
    }
}

export async function getTimezone() {
    try {
        const supabase = await createClient()
        const { data } = await supabase
            .from("sys_settings")
            .select("value")
            .eq("key", "app_timezone")
            .single()

        // Handle JSONB value unwrapping if needed, or simple text
        // If it's null, default to 'Europe/Warsaw'
        return (data?.value as string) || 'Europe/Warsaw'
    } catch (e) {
        return 'Europe/Warsaw'
    }
}
import { HeatmapThreshold, DEFAULT_HEATMAP_CONFIG } from "./heatmap-config"

export async function getHeatmapConfig() {
    try {
        const supabase = await createClient()
        const { data } = await supabase
            .from("sys_settings")
            .select("value")
            .eq("key", "heatmap_config")
            .single()

        return (data?.value as HeatmapThreshold[]) || DEFAULT_HEATMAP_CONFIG
    } catch (e) {
        return DEFAULT_HEATMAP_CONFIG
    }
}

export async function saveHeatmapConfig(config: HeatmapThreshold[]) {
    try {
        const supabase = await createClient()
        const { error } = await supabase
            .from("sys_settings")
            .upsert({
                key: 'heatmap_config',
                value: config
            })

        if (error) throw error
        revalidatePath("/admin/trips")
        revalidatePath("/admin/settings")
        return { success: true }
    } catch (e: any) {
        console.error("Error saving heatmap config:", e)
        return { success: false, error: e.message }
    }
}

export async function updateProfile(id: string, data: {
    firstName: string,
    lastName: string,
    phone: string,
    email: string
}) {
    try {
        const supabase = await createClient()
        const { error } = await supabase
            .from("auth_profiles")
            .update({
                first_name: data.firstName,
                last_name: data.lastName,
                phone: data.phone,
                email: data.email
            })
            .eq("id", id)

        if (error) throw error
        revalidatePath("/admin")
        revalidatePath("/admin/settings")
        return { success: true }
    } catch (e: any) {
        return { success: false, error: e.message }
    }
}

export async function getProfile() {
    const supabase = await createClient()
    const { data: { user } } = await supabase.auth.getUser()
    if (!user) return null

    const { data } = await supabase
        .from('auth_profiles')
        .select(`
            *,
            role:auth_roles (
                name,
                apps:auth_role_permissions (
                    app_id
                )
            )
        `)
        .eq('id', user.id)
        .single()
    return data
}



