import { Suspense } from 'react';
import { verifyPageAccess } from '@/core/auth/actions';
import { getTenantSettingsAction } from '../actions';
import SettingsClient from './SettingsClient';
import { Loader2 } from 'lucide-react';

export default async function SettingsPage({ params }: { params: Promise<{ tenantSlug: string }> }) {
    const { tenantSlug } = await params;
    // 1. Verify Access & Get Tenant ID
    const { tenantId } = await verifyPageAccess(tenantSlug, 'settings.view');

    // 2. Fetch Data
    const settings = await getTenantSettingsAction(tenantId);

    // 3. Render Client Component
    return (
        <Suspense fallback={<div className="flex justify-center p-12"><Loader2 className="animate-spin h-8 w-8 text-indigo-600" /></div>}>
            <SettingsClient tenantId={tenantId} initialSettings={settings} />
        </Suspense>
    );
}

'use client';

import React, { useState, useEffect } from 'react';
import { TenantSettings } from '@/modules/core-admin/settings/types';
import { updateTenantSettingsAction } from '@/modules/core-admin/settings/actions';
import { Loader2, Save } from 'lucide-react';

interface SettingsClientProps {
    tenantId: string;
    initialSettings: TenantSettings;
}

export default function SettingsClient({ tenantId, initialSettings }: SettingsClientProps) {
    const [settings, setSettings] = useState<TenantSettings>(initialSettings);
    const [loading, setLoading] = useState(false);
    const [message, setMessage] = useState<{ type: 'success' | 'error', text: string } | null>(null);

    const handleSave = async () => {
        setLoading(true);
        setMessage(null);
        try {
            const result = await updateTenantSettingsAction(tenantId, settings);
            if (result.success) {
                setMessage({ type: 'success', text: 'Settings updated successfully' });
            } else {
                setMessage({ type: 'error', text: result.error || 'Failed to update settings' });
            }
        } catch (err) {
            setMessage({ type: 'error', text: 'An unexpected error occurred' });
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center">
                <h2 className="text-xl font-semibold text-gray-900">Tenant Settings</h2>
                <button
                    onClick={handleSave}
                    disabled={loading}
                    className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700 disabled:opacity-50"
                >
                    {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : <Save className="w-4 h-4" />}
                    Save Changes
                </button>
            </div>

            {message && (
                <div className={`p-4 rounded ${message.type === 'success' ? 'bg-green-50 text-green-700' : 'bg-red-50 text-red-700'}`}>
                    {message.text}
                </div>
            )}

            <div className="bg-white p-6 rounded-lg border shadow-sm space-y-4">
                <h3 className="font-medium text-gray-900 border-b pb-2">General</h3>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Portal Name</label>
                        <input
                            type="text"
                            value={settings.portal_name}
                            onChange={(e) => setSettings({ ...settings, portal_name: e.target.value })}
                            className="w-full p-2 border rounded focus:ring-2 focus:ring-blue-500 outline-none"
                            placeholder="e.g. My Ferry Portal"
                        />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Default Locale</label>
                        <select
                            value={settings.locale}
                            onChange={(e) => setSettings({ ...settings, locale: e.target.value })}
                            className="w-full p-2 border rounded focus:ring-2 focus:ring-blue-500 outline-none"
                        >
                            <option value="en">English (en)</option>
                            <option value="pl">Polish (pl)</option>
                            <option value="de">German (de)</option>
                        </select>
                    </div>
                </div>
            </div>

            <div className="bg-white p-6 rounded-lg border shadow-sm space-y-4">
                <h3 className="font-medium text-gray-900 border-b pb-2">Branding</h3>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Logo URL</label>
                        <input
                            type="text"
                            value={settings.branding_json.logo_url || ''}
                            onChange={(e) => setSettings({
                                ...settings,
                                branding_json: { ...settings.branding_json, logo_url: e.target.value }
                            })}
                            className="w-full p-2 border rounded focus:ring-2 focus:ring-blue-500 outline-none"
                            placeholder="https://..."
                        />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Primary Color</label>
                        <div className="flex gap-2">
                            <input
                                type="color"
                                value={settings.branding_json.primary_color || '#000000'}
                                onChange={(e) => setSettings({
                                    ...settings,
                                    branding_json: { ...settings.branding_json, primary_color: e.target.value }
                                })}
                                className="h-10 w-20 p-1 border rounded cursor-pointer"
                            />
                            <input
                                type="text"
                                value={settings.branding_json.primary_color || ''}
                                onChange={(e) => setSettings({
                                    ...settings,
                                    branding_json: { ...settings.branding_json, primary_color: e.target.value }
                                })}
                                className="flex-1 p-2 border rounded focus:ring-2 focus:ring-blue-500 outline-none"
                                placeholder="#000000"
                            />
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}

