import { createClient } from "@/utils/supabase/server"
import { createServiceClient } from "@/utils/supabase/service"
import { AdminDashboardContent } from "@/components/admin/admin-dashboard-content"
import { AdminPageHeader } from "@/components/admin/admin-page-header"
import { getAdminMenu, getCockpitMenu } from "@/modules/admin-menu/actions"
import { CustomizeButton } from "@/components/admin/customize-button"
import { notFound } from "next/navigation"

interface PageProps {
    params: Promise<{ id: string }>
    searchParams: Promise<{ [key: string]: string | string[] | undefined }>
}

export default async function CockpitViewerPage({ params, searchParams }: PageProps) {
    const { id } = await params
    const sp = await searchParams
    const isEditMode = sp.edit === 'true'

    const supabase = await createClient()
    const { data: { user } } = await supabase.auth.getUser()

    if (!user) {
        return <div className="p-8">Odmowa dostępu</div>
    }

    const serviceSupabase = createServiceClient()
    if (!serviceSupabase) {
        return <div className="p-8">Błąd konfiguracji serwisu</div>
    }

    const contextId = `cockpit-${id}`

    // Fetch Cockpit Menu directly by ID or Slug
    // This allows URLs like /admin/cockpits/uslugi to work
    const cockpitMenu = await getCockpitMenu(id, isEditMode, contextId)
    const cockpitSection = cockpitMenu[0]

    let finalSection: import("@/modules/admin-menu/actions").AdminMenuSection | undefined = cockpitSection

    if (!finalSection) {
        // Fallback: If not found in Cockpits, try Legacy Admin Menu (only if ID looks like UUID?)
        // The getCockpitMenu handles both, so if it returns nothing, it really means nothing found.
        // But for backward compatibility with pure sections (if any exist not as cockpits), we check.
        const fullMenu = await getAdminMenu(isEditMode, contextId, { showHidden: true })
        finalSection = fullMenu.find(s => s.id === id || s.name === id)
    }

    if (!finalSection) {
        // Fallback if not found (maybe permissions?)
        // If we really want a 404, we can call it here
        return <div className="p-8">Odmowa dostępu lub sekcja nie istnieje.</div>
    }

    const titleKey = finalSection.name // unified

    // Determine content to render
    const hasApps = finalSection.apps && finalSection.apps.length > 0

    return (
        <div className="space-y-6 animate-in fade-in duration-500 min-h-screen flex flex-col">
            <AdminPageHeader
                titleKey={titleKey}
                backLink="/admin"
            >
                <CustomizeButton />
            </AdminPageHeader>

            {hasApps ? (
                <div className="flex-1">
                    <AdminDashboardContent
                        initialMenu={[finalSection]}
                        userId={user.id}
                        isSuperAdmin={false} // Todo: fetch profile
                        contextId={contextId}
                    />
                </div>
            ) : (
                <div className="flex-1 flex items-center justify-center text-gray-400 text-lg">
                    {/* Render empty state or maybe a widget placeholder? */}
                    Pusto...
                </div>
            )}
        </div>
    )
}

