import { getPlan, getPlanItems } from "../actions"
import { PlanEditorClient } from "./plan-editor-client"
import { createClient } from "@/utils/supabase/server"
import { notFound } from "next/navigation"

export default async function PlanEditorPage({ params }: { params: { id: string } }) {
    const plan = await getPlan(params.id)
    if (!plan) notFound()

    const items = await getPlanItems(params.id)

    // We need fetch auxiliary data for the editor (ferries, routes)
    const supabase = await createClient()
    const { data: ferries } = await supabase.from('clnt_ferries').select('*')
    const { data: routes } = await supabase.from('clnt_routes').select('*, origin:clnt_locations!origin_id(*), destination:clnt_locations!destination_id(*)')

    return (
        <PlanEditorClient
            plan={plan}
            items={items}
            ferries={ferries || []}
            routes={routes || []}
        />
    )
}

'use client'

import { useState } from "react"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Calendar, Ship, MapPin, Clock, Plus, Trash2, Save, Rocket, ArrowLeft } from "lucide-react"
import { format, eachDayOfInterval, isSameDay, addMinutes } from "date-fns"
import { addPlanItem, deletePlanItem, publishPlan } from "../actions"
import { Badge } from "@/components/ui/badge"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { Input } from "@/components/ui/input"
import { useTransition } from "react"
import { useRouter } from "next/navigation"
import Link from "next/link"
import { useTranslation } from "react-i18next"

interface PlanEditorClientProps {
    plan: any
    items: any[]
    ferries: any[]
    routes: any[]
}

export function PlanEditorClient({ plan, items, ferries, routes }: PlanEditorClientProps) {
    const { t } = useTranslation()
    const router = useRouter()
    const [isPending, startTransition] = useTransition()
    const [selectedDate, setSelectedDate] = useState<Date>(new Date(plan.start_date))

    // Form state for new item
    const [newRouteId, setNewRouteId] = useState<string>("")
    const [newFerryId, setNewFerryId] = useState<string>("")
    const [newTime, setNewTime] = useState<string>("09:00")

    const days = eachDayOfInterval({
        start: new Date(plan.start_date),
        end: new Date(plan.end_date)
    })

    const handleAddItem = async () => {
        if (!newRouteId || !newFerryId || !newTime) return

        const route = routes.find(r => r.id === newRouteId)
        const duration = route?.sub_route_duration || route?.duration_minutes || 60

        // Construct timestamps
        const dateStr = format(selectedDate, "yyyy-MM-dd")
        const departure = new Date(`${dateStr}T${newTime}:00`)
        const arrival = addMinutes(departure, duration)

        startTransition(async () => {
            await addPlanItem(
                plan.id,
                newFerryId,
                newRouteId,
                departure.toISOString(),
                arrival.toISOString()
            )
            // Reset slightly but keep route/ferry for rapid entry
            setNewTime(format(addMinutes(departure, 60), "HH:mm")) // Auto-advance time
        })
    }

    const handlePublish = async () => {
        if (!confirm(t('admin.planning.editor.confirmPublish'))) return
        startTransition(async () => {
            try {
                await publishPlan(plan.id)
                alert(t('admin.planning.editor.publishedSuccess'))
                router.push('/admin/planning')
            } catch (e) {
                alert("Error publishing: " + (e as Error).message)
            }
        })
    }

    const currentItems = items.filter(item => isSameDay(new Date(item.departure_time), selectedDate))

    return (
        <div className="space-y-6">
            <div className="flex items-center justify-between">
                <div className="flex items-center gap-4">
                    <Button variant="outline" size="icon" asChild>
                        <Link href="/admin/planning"><ArrowLeft size={16} /></Link>
                    </Button>
                    <div>
                        <h1 className="text-2xl font-bold text-blue-900 flex items-center gap-2">
                            {plan.name}
                            <Badge variant={plan.status === 'published' ? 'default' : 'secondary'}>
                                {plan.status}
                            </Badge>
                        </h1>
                        <p className="text-sm text-slate-500">
                            {format(new Date(plan.start_date), "PP")} - {format(new Date(plan.end_date), "PP")}
                        </p>
                    </div>
                </div>
                {plan.status !== 'published' && (
                    <Button onClick={handlePublish} disabled={isPending || items.length === 0} className="gap-2 bg-green-600 hover:bg-green-700">
                        <Rocket size={16} /> {t('admin.planning.editor.publish')}
                    </Button>
                )}
            </div>

            <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
                {/* Sidebar: Days */}
                <Card className="md:col-span-1 border-blue-100 h-[calc(100vh-200px)] overflow-hidden flex flex-col">
                    <CardHeader className="py-3 bg-blue-50 border-b">
                        <CardTitle className="text-sm font-medium text-blue-900">{t('admin.planning.editor.calendar')}</CardTitle>
                    </CardHeader>
                    <div className="flex-1 overflow-y-auto p-2 space-y-1 custom-scrollbar">
                        {days.map(day => {
                            const isSelected = isSameDay(day, selectedDate)
                            const count = items.filter(i => isSameDay(new Date(i.departure_time), day)).length
                            return (
                                <button
                                    key={day.toISOString()}
                                    onClick={() => setSelectedDate(day)}
                                    className={`w-full text-left px-3 py-2 rounded-md text-sm flex justify-between items-center transition-colors ${isSelected
                                        ? "bg-blue-600 text-white"
                                        : "hover:bg-slate-100 text-slate-700"
                                        }`}
                                >
                                    <span>{format(day, "EEE, MMM d")}</span>
                                    {count > 0 && (
                                        <span className={`text-xs ml-2 px-1.5 py-0.5 rounded-full ${isSelected ? "bg-blue-500 text-white" : "bg-blue-100 text-blue-700"}`}>
                                            {count}
                                        </span>
                                    )}
                                </button>
                            )
                        })}
                    </div>
                </Card>

                {/* Main Content: Day Editor */}
                <Card className="md:col-span-3 border-blue-100 flex flex-col h-[calc(100vh-200px)]">
                    <CardHeader className="py-3 bg-blue-50 border-b flex flex-row justify-between items-center">
                        <CardTitle className="text-sm font-medium text-blue-900 flex items-center gap-2">
                            <Calendar size={16} />
                            {format(selectedDate, "EEEE, MMMM do, yyyy")}
                        </CardTitle>
                        <span className="text-xs text-slate-500">{currentItems.length} {t('admin.planning.editor.tripsPlanned')}</span>
                    </CardHeader>

                    <div className="flex-1 bg-slate-50/50 p-4 overflow-y-auto">
                        {/* New Item Form */}
                        {plan.status !== 'published' && (
                            <div className="bg-white p-4 rounded-lg border shadow-sm mb-6 flex flex-wrap gap-4 items-end">
                                <div className="space-y-1.5 flex-1 min-w-[200px]">
                                    <span className="text-xs font-medium text-slate-700">{t('admin.planning.editor.route')}</span>
                                    <Select value={newRouteId} onValueChange={setNewRouteId}>
                                        <SelectTrigger>
                                            <SelectValue placeholder="Select Route..." />
                                        </SelectTrigger>
                                        <SelectContent>
                                            {routes.map(r => (
                                                <SelectItem key={r.id} value={r.id}>
                                                    {r.origin?.name} &rarr; {r.destination?.name}
                                                </SelectItem>
                                            ))}
                                        </SelectContent>
                                    </Select>
                                </div>
                                <div className="space-y-1.5 w-[200px]">
                                    <span className="text-xs font-medium text-slate-700">{t('admin.planning.editor.ferry')}</span>
                                    <Select value={newFerryId} onValueChange={setNewFerryId}>
                                        <SelectTrigger>
                                            <SelectValue placeholder="Select Ferry..." />
                                        </SelectTrigger>
                                        <SelectContent>
                                            {ferries.map(f => (
                                                <SelectItem key={f.id} value={f.id}>{f.name}</SelectItem>
                                            ))}
                                        </SelectContent>
                                    </Select>
                                </div>
                                <div className="space-y-1.5 w-[120px]">
                                    <span className="text-xs font-medium text-slate-700">{t('admin.planning.editor.time')}</span>
                                    <Input
                                        type="time"
                                        value={newTime}
                                        onChange={(e) => setNewTime(e.target.value)}
                                    />
                                </div>
                                <Button onClick={handleAddItem} disabled={isPending || !newRouteId || !newFerryId || !newTime} className="gap-2">
                                    <Plus size={16} /> {t('admin.planning.editor.add')}
                                </Button>
                            </div>
                        )}

                        {/* List of items */}
                        <div className="space-y-2">
                            {currentItems.length === 0 ? (
                                <div className="text-center py-12 text-slate-400 border-2 border-dashed rounded-lg">
                                    {t('admin.planning.editor.noTrips')}
                                </div>
                            ) : (
                                currentItems.map(item => (
                                    <div key={item.id} className="bg-white p-3 rounded-lg border hover:border-blue-300 transition-colors flex items-center justify-between group">
                                        <div className="flex items-center gap-6">
                                            <div className="flex items-center gap-2 text-blue-900 font-bold w-24">
                                                <Clock size={16} className="text-blue-500" />
                                                {format(new Date(item.departure_time), "HH:mm")}
                                            </div>
                                            <div className="flex items-center gap-2 text-slate-700 min-w-[200px]">
                                                <MapPin size={16} className="text-slate-400" />
                                                {item.route?.origin?.name} <span className="text-slate-300">&rarr;</span> {item.route?.destination?.name}
                                            </div>
                                            <div className="flex items-center gap-2 text-slate-600">
                                                <Ship size={16} className="text-slate-400" />
                                                {item.ferry?.name}
                                            </div>
                                        </div>
                                        {plan.status !== 'published' && (
                                            <Button
                                                variant="ghost"
                                                size="icon"
                                                className="text-red-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"
                                                onClick={() => startTransition(async () => await deletePlanItem(item.id))}
                                            >
                                                <Trash2 size={16} />
                                            </Button>
                                        )}
                                    </div>
                                ))
                            )}
                        </div>
                    </div>
                </Card>
            </div>
        </div>
    )
}

'use server'

import { createClient } from "@/utils/supabase/server"
import { revalidatePath } from "next/cache"
import { redirect } from "next/navigation"

export async function getPlans() {
    const supabase = await createClient()
    const { data, error } = await supabase
        .from('clnt_schedule_plans')
        .select('*')
        .order('created_at', { ascending: false })

    if (error) throw new Error(error.message)
    return data
}

export async function createPlan(formData: FormData) {
    const supabase = await createClient()
    const name = formData.get('name') as string
    const start_date = formData.get('start_date') as string
    const end_date = formData.get('end_date') as string

    let redirectPath = ''
    try {
        const { data, error } = await supabase
            .from('clnt_schedule_plans')
            .insert([{ name, start_date, end_date }])
            .select()
            .single()

        if (error) throw new Error(error.message)
        if (!data) throw new Error("Failed to create plan - no data returned")

        revalidatePath('/admin/planning')
        redirectPath = `/admin/planning/${data.id}`
    } catch (err: any) {
        if (err.digest?.includes('NEXT_REDIRECT')) throw err // Re-throw redirect
        console.error("Error creating plan:", err)
        throw err
    }

    if (redirectPath) redirect(redirectPath)
}

export async function deletePlan(id: string) {
    const supabase = await createClient()
    const { error } = await supabase.from('clnt_schedule_plans').delete().eq('id', id)
    if (error) throw new Error(error.message)
    revalidatePath('/admin/planning')
}

export async function getPlan(id: string) {
    const supabase = await createClient()
    const { data, error } = await supabase
        .from('clnt_schedule_plans')
        .select('*')
        .eq('id', id)
        .single()

    if (error) throw new Error(error.message)
    return data
}

export async function getPlanItems(planId: string) {
    const supabase = await createClient()
    const { data, error } = await supabase
        .from('clnt_plan_items')
        .select(`
            *,
            ferry:clnt_ferries(*),
            route:clnt_routes(*)
        `)
        .eq('plan_id', planId)
        .order('departure_time', { ascending: true })

    if (error) throw new Error(error.message)
    return data
}

export async function addPlanItem(planId: string, ferryId: string, routeId: string, departureTime: string, arrivalTime: string, priceConfig?: any) {
    const supabase = await createClient()
    const { error } = await supabase
        .from('clnt_plan_items')
        .insert([{
            plan_id: planId,
            ferry_id: ferryId,
            route_id: routeId,
            departure_time: departureTime,
            arrival_time: arrivalTime,
            price_configuration: priceConfig
        }])

    if (error) throw new Error(error.message)
    revalidatePath(`/admin/planning/${planId}`)
}

export async function deletePlanItem(id: string) {
    const supabase = await createClient()
    const { error } = await supabase.from('clnt_plan_items').delete().eq('id', id)
    if (error) throw new Error(error.message)
    revalidatePath('/admin/planning/[id]', 'page')
}

export async function publishPlan(planId: string) {
    const supabase = await createClient()

    // 1. Get all items
    const { data: items, error: itemsError } = await supabase
        .from('clnt_plan_items')
        .select('*')
        .eq('plan_id', planId)

    if (itemsError) throw new Error(itemsError.message)
    if (!items || items.length === 0) throw new Error("Plan is empty")

    // 2. We need to create trips. 
    // The plan_items have timestamps.
    const tripsToCreate = items.map(item => ({
        ferry_id: item.ferry_id,
        route_id: item.route_id,
        departure_time: item.departure_time,
        arrival_time: item.arrival_time,
        status: 'SCHEDULED',
        // pricing is separate or jsonb? 
        // trips table usually has pricing logic or uses defaults if not specified? 
        // For now let's assume trips table supports basic insert.
        // We might need to copy price_configuration if it exists in trips table.
        // Checking schema via memory or previous interactions: `trips` has `pricing` jsonb or relation?
        // Step 604 showed `TripListFilters` and step 614 `PriceEditor`.
        // `PriceEditor` works on `trip.pricing` which suggests a relation or jsonb.
        // Creating a trip usually inserts into `trips` and potentially `trip_pricing`.
        // If we want to keep it simple, we insert trips. The pricing might be default.
    }))

    const { error: insertError } = await supabase.from('clnt_trips').insert(tripsToCreate)
    if (insertError) throw new Error(insertError.message)

    // 3. Mark plan as published
    const { error: updateError } = await supabase
        .from('clnt_schedule_plans')
        .update({ status: 'published' })
        .eq('id', planId)

    if (updateError) throw new Error(updateError.message)

    revalidatePath(`/admin/planning/${planId}`)
    revalidatePath('/admin/trips')
}

'use client'

import { useState } from "react"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog"
import { createPlan, deletePlan } from "./actions"
import Link from "next/link"
import { Calendar, Plus, Trash2, ArrowRight } from "lucide-react"

import { useTranslation } from "react-i18next"

export function CreatePlanDialog() {
    const { t } = useTranslation()
    return (
        <Dialog>
            <DialogTrigger asChild>
                <Button className="gap-2">
                    <Plus size={16} /> {t('admin.planning.newPlan')}
                </Button>
            </DialogTrigger>
            <DialogContent>
                <DialogHeader>
                    <DialogTitle>{t('admin.planning.createDialog.title')}</DialogTitle>
                </DialogHeader>
                <form action={createPlan} className="space-y-4">
                    <div className="space-y-2">
                        <Label htmlFor="name">{t('admin.planning.createDialog.name')}</Label>
                        <Input id="name" name="name" placeholder={t('admin.planning.createDialog.placeholder')} required />
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-2">
                            <Label htmlFor="start_date">{t('admin.planning.createDialog.start')}</Label>
                            <Input id="start_date" name="start_date" type="date" required />
                        </div>
                        <div className="space-y-2">
                            <Label htmlFor="end_date">{t('admin.planning.createDialog.end')}</Label>
                            <Input id="end_date" name="end_date" type="date" required />
                        </div>
                    </div>
                    <Button type="submit" className="w-full">{t('admin.planning.createDialog.submit')}</Button>
                </form>
            </DialogContent>
        </Dialog>
    )
}

import { getPlans } from "./actions"
import { CreatePlanDialog } from "./create-plan-dialog"
import { PlanningList } from "./planning-list"
import { PlanningHeader } from "./planning-header"

export default async function PlanningPage() {
    const plans = await getPlans()

    return (
        <div className="space-y-6 w-full max-w-none">
            <div className="flex items-center justify-between">
                <PlanningHeader />
                <CreatePlanDialog />
            </div>

            <PlanningList plans={plans} />
        </div>
    )
}

"use client"

import { useTranslation } from "react-i18next"

export function PlanningHeader() {
    const { t } = useTranslation()
    return (
        <div>
            <h1 className="text-3xl font-bold tracking-tight text-blue-900">{t('admin.planning.pageTitle')}</h1>
            <p className="text-muted-foreground">{t('admin.planning.pageDesc')}</p>
        </div>
    )
}

"use client"

import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Badge } from "@/components/ui/badge"
import { Calendar, Trash2, ArrowRight, FileText } from "lucide-react"
import Link from "next/link"
import { format } from "date-fns"
import { useTranslation } from "react-i18next"
import { deletePlan } from "./actions"

export function PlanningList({ plans }: { plans: any[] }) {
    const { t } = useTranslation()

    return (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {plans.map((plan: any) => (
                <Card key={plan.id} className="group hover:border-blue-400 transition-colors">
                    <CardHeader className="pb-3">
                        <div className="flex justify-between items-start">
                            <CardTitle className="text-lg font-bold text-blue-800">{plan.name}</CardTitle>
                            <Badge variant={plan.status === 'published' ? 'default' : 'secondary'}>
                                {plan.status.toUpperCase()}
                            </Badge>
                        </div>
                        <CardDescription className="flex items-center gap-2 text-xs">
                            <Calendar size={12} />
                            {format(new Date(plan.start_date), "PP")} - {format(new Date(plan.end_date), "PP")}
                        </CardDescription>
                    </CardHeader>
                    <CardContent>
                        <div className="flex items-center justify-between mt-4">
                            <div className="text-sm text-slate-500">
                                {t('admin.planning.lastUpdated')}: {format(new Date(plan.updated_at), "MMM d, HH:mm")}
                            </div>
                            <div className="flex gap-2">
                                <Button
                                    variant="ghost"
                                    size="icon"
                                    className="text-red-400 hover:text-red-600 hover:bg-red-50"
                                    onClick={async () => {
                                        if (confirm("Are you sure?")) await deletePlan(plan.id)
                                    }}
                                >
                                    <Trash2 size={16} />
                                </Button>
                                <Button asChild size="sm" className="gap-1">
                                    <Link href={`/admin/planning/${plan.id}`}>
                                        Edit <ArrowRight size={14} />
                                    </Link>
                                </Button>
                            </div>
                        </div>
                    </CardContent>
                </Card>
            ))}
            {plans.length === 0 && (
                <div className="col-span-full text-center py-12 bg-slate-50 rounded-lg border border-dashed">
                    <FileText className="mx-auto h-12 w-12 text-slate-300 mb-4" />
                    <h3 className="text-lg font-medium text-slate-900">{t('admin.planning.noPlans')}</h3>
                    <p className="text-slate-500 mb-4">{t('admin.planning.noPlansDesc')}</p>
                </div>
            )}
        </div>
    )
}

